insert into public.courses
    (code, name, hours, description, exclusions, breadth, prereq_tree)
values
    ('FRE299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('FRE304H1', 'Contemporary French Women''s Prose Fiction', '24L', 'An analysis of selected prose texts of the last hundred years written by major French women authors, emphasizing themes and textual strategies used to represent the female subject, her relationship to language, and the role of ethnicity, class, and gender in the construction of identity.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE240H1", "FRE245H1"]}, {"operator": "OR", "items": ["FRE241H1", "FRE246H1"]}]}'::jsonb),
    ('FRE310H1', 'Relations between Text and Other Media', '24L', 'Literary texts and other forms of media (photographs, cinematographic images, paintings) have been associated in a fascinating relation in hundreds of works of French literature. An exploration of this inextricable weaving together of verbal and visual experiences as it pertains to literature through the study of interdisciplinary theoretical texts focused on photography, painting, and cinema.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE240H1", "FRE245H1"]}, {"operator": "OR", "items": ["FRE241H1", "FRE246H1"]}]}'::jsonb),
    ('FRE314H1', 'Quebec and French-Canadian Literature', '24L', 'This course aims to explore the literature from Quebec and other French-speaking parts of Canada. Literary texts by French Canadian authors will be analyzed, and various themes such as identity (self, others, multiculturalism, nationalism), heritage (family, tradition, culture), and representations of place and linguistic values will be studied.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE240H1", "FRE245H1"]}, {"operator": "OR", "items": ["FRE241H1", "FRE246H1"]}]}'::jsonb),
    ('FRE318H1', 'Medieval French Literature', '24L', 'Religious fervour, chivalry, romance and ribald humour, heroic deeds, marvellous adventures, and exotic travels as found in selected texts from the French Middle Ages. Readings in modern French translations with appropriate reference to the original language.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE240H1", "FRE245H1"]}, {"operator": "OR", "items": ["FRE241H1", "FRE246H1"]}]}'::jsonb),
    ('FRE319H1', 'Laughter and Thought in French Renaissance Literature', '24L', 'An overview of the fascinating literary diversity, prose, theatre and poetry essential to the changing humanistic discourse of the French Renaissance and Baroque periods. The underscoring of important historical events - Reformation, Great Discoveries, Printing - to explain the philosophical and literary values produced by such violent times.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE240H1", "FRE245H1"]}, {"operator": "OR", "items": ["FRE241H1", "FRE246H1"]}]}'::jsonb),
    ('FRE320H1', 'French Literature of Classicism and Enlightenment', '24L', 'An introduction to French literature between Classicism and the French Revolution with particular emphasis on its relationship to philosophical, cultural, and political movements of the Enlightenment, providing historical depth to philosophical and socio-political foundations of today''s life. A privileged access to, and critique of, modernity in the postmodern age.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE240H1", "FRE245H1"]}, {"operator": "OR", "items": ["FRE241H1", "FRE246H1"]}]}'::jsonb),
    ('FRE324H1', 'French Literature in the Time of Revolutions and Industrialization', '24L', 'The long 19th century (1789-1914) is characterized by change: from political upheavals to literary, scientific, and media revolutions, the spread of literacy, and the rapid development of industrialization and colonization. A study of the evolution of literature (genres, forms, movements), as influenced by these changing socio-political and economic contexts.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE240H1", "FRE245H1"]}, {"operator": "OR", "items": ["FRE241H1", "FRE246H1"]}]}'::jsonb),
    ('FRE326H1', 'Contemporary French Literature', '24L', 'Characterized by experimentation and the crisis of representation, French literature of the 20th and 21st centuries has undergone numerous transformations in form, content, and generic boundaries. A study of these literary movements, trends, and transgressions in poetry, prose, and theatre.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE240H1", "FRE245H1"]}, {"operator": "OR", "items": ["FRE241H1", "FRE246H1"]}]}'::jsonb),
    ('FRE332H1', 'Francophone Literatures', '24L', 'A comprehensive introduction to Francophone literatures and cultures, examining the linguistic, aesthetic, and discursive specificities as represented by authors of the Francophone world. Focus on the concepts of colonialism, representation, alienation, emigration, and nationalism.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE240H1", "FRE245H1"]}, {"operator": "OR", "items": ["FRE241H1", "FRE246H1"]}]}'::jsonb),
    ('FRE334H1', 'Francophone Cinema', '24L', 'Through films from across the spectrum of the Francophone world, a study of the diversity of the French colonial empire as well as the different aesthetic, historical, and cultural effects of colonialism and post-independence experience on various cinematic representations.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE240H1", "FRE245H1"]}, {"operator": "OR", "items": ["FRE241H1", "FRE246H1"]}]}'::jsonb),
    ('FRE336H1', 'Postcolonialism: Francophone Literatures', '24L', 'The fundamentals of postcolonial theories, with emphasis on how they relate to the Francophone world. The dialogue between fiction and theory, as well as the modalities of a coherent Francophone postcolonial identity in a global world.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE240H1", "FRE245H1"]}, {"operator": "OR", "items": ["FRE241H1", "FRE246H1"]}]}'::jsonb),
    ('FRE345H1', 'Literary Genres', '24L', 'Survey of the main literary genres and analysis of their features, with in-depth study of two of the genres: narrative (epic poem, novel, short narrative), lyric poetry, drama (tragedy, comedy, farce, mystery play), essay. Readings of selected texts, chosen for their representative potential and their historical relevance.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["FRE240H1", "FRE245H1"]}, {"operator": "OR", "items": ["FRE241H1", "FRE246H1"]}]}'::jsonb),
    ('FRE376H1', 'French Phonology and Phonetics', '36L', 'Why does French sound the way it does? What does it mean to have a (regional or foreign) accent? How can linguistic and socio-historical factors explain pronunciation differences in the French-speaking world? Which differences are perceptible and/or carry social meaning, and why? This course provides an introduction to the formal study of sound, as applied to French data. Through transcription and acoustic analysis, students enhance their ability to distinguish sound contrasts used in French and other languages and work collectively to formulate and evaluate hypotheses about sound systems.', null, 2, '{"operator": "AND", "items": ["FRE272H1"]}'::jsonb),
    ('FRE378H1', 'French Syntax', '36L', 'A study of the distribution and relationships of the syntagmatic components of contemporary French; of sentential structure, including the principles of coordination, subordination and expansion; and of major theoretical approaches.', null, 2, '{"operator": "AND", "items": ["FRE272H1"]}'::jsonb),
    ('FRE379H1', 'Sociolinguistics of Quebec and Canadian French', '36L', 'The relationship between language use and social factors such as socio-economic status, social context and gender identity. Theoretical notions are derived through exploration of quantitative analyses, focusing on variation and change in French in Quebec and elsewhere in Canada.', null, 3, '{"operator": "AND", "items": ["FRE272H1"]}'::jsonb),
    ('FRE383H1', 'Quantitative Methods for the Study of French', '24L/12T', 'An introduction to the foundations of quantitative research on French. Topics include differences between quantitative and qualitative analyses; hypothesis formulation; experimental design; and data collection and analysis including basic statistical methods. Phenomena investigated come from Canadian and European varieties as well as studies of second language learners.', null, 3, '{"operator": "AND", "items": ["FRE272H1"]}'::jsonb),
    ('FRE384H1', 'Teaching French as a Second Language', '36L', 'This course is designed for students who aim for a career in teaching French as a second language or who wish to apply academic learning in a professional context, build their network, and explore potential career paths. It introduces recent methods and approaches and includes a significant experiential learning component in partnership with local school boards and private schools. This course welcomes the participation of students who are fluent French speakers or whose command of the French language is equivalent to near-native proficiency.', null, 1, '{"operator": "AND", "items": ["FRE272H1", {"operator": "OR", "items": ["FSL322H1", "FSL321Y1", "FSL420H1"]}]}'::jsonb),
    ('FRE386H1', 'French Semantics and Pragmatics', '36L', 'What do words and sentences mean? How do language users access meaning? How do child and adult learners of French determine the meanings of words and complex sentences in context? What kinds of inferences do people make during conversation? This course provides an introduction to the formal study of linguistic meaning, as applied to French data. Students are introduced to analytical and experimental approaches to semantics and pragmatics.', null, 2, '{"operator": "AND", "items": ["FRE272H1"]}'::jsonb),
    ('FRE387H1', 'French Morphology', '36L', 'A study of the morphological system of modern French, its relationship to syntax and phonology; theoretical notions derived from the analysis of specific data.', null, 2, '{"operator": "AND", "items": ["FRE272H1"]}'::jsonb),
    ('FRE398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('FRE398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('FRE399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('FRE399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('FRE410H1', 'Advanced Topics in Quebec Literature', '24S', 'An advanced interdisciplinary research seminar devoted to specific issues of Québécois literature and culture. Focus on a literary genre, a particular subject matter, a literary movement, or based on a multidisciplinary approach to cinema, arts, and music. For more information, see https://www.french.utoronto.ca/undergraduate', null, 1, '{"operator": "AND", "items": ["FRE246H1", {"credits": 1.0, "department": null}, {"operator": "OR", "items": ["FRE310H1", "FRE314H1", "FRE318H1", "FRE319H1", "FRE320H1", "FRE324H1", "FRE326H1", "FRE332H1", "FRE334H1", "FRE336H1", "FRE345H1"]}]}'::jsonb),
    ('FRE438H1', 'Advanced Topics in Francophone Literatures', '24S', 'An advanced seminar dedicated to specific issues of the Francophone literature and culture. Focusing on an author, a literary genre, or based on a multidisciplinary approach involving cinema, arts and music, each seminar reflects the professor''s current research. For more information, see https://www.french.utoronto.ca/undergraduate', null, 1, '{"operator": "AND", "items": ["FRE246H1", {"credits": 1.0, "department": null}, {"operator": "OR", "items": ["FRE310H1", "FRE314H1", "FRE318H1", "FRE319H1", "FRE320H1", "FRE324H1", "FRE326H1", "FRE332H1", "FRE334H1", "FRE336H1", "FRE345H1"]}]}'::jsonb),
    ('FRE441H1', 'Advanced Topics in French Literature', '24S', 'An advanced, research-oriented seminar devoted to specific issues of French literature and culture. Focus on a literary genre, a particular subject or literary movement, or based on a multidisciplinary approach involving cinema, arts, and music. For more information, see https://www.french.utoronto.ca/undergraduate', null, 1, '{"operator": "AND", "items": ["FRE246H1", {"credits": 1.0, "department": null}, {"operator": "OR", "items": ["FRE310H1", "FRE314H1", "FRE318H1", "FRE319H1", "FRE320H1", "FRE324H1", "FRE326H1", "FRE332H1", "FRE334H1", "FRE336H1", "FRE345H1"]}]}'::jsonb),
    ('FRE443H1', 'Advanced Topics: Authors', '24S', 'An advanced, research-oriented seminar devoted to questions concerning the authors practice, originality, and oeuvre. Production, performance and prominence, characteristic genres, religious and philosophical thought, theoretical reflection on literature, language, and belonging as aspects of the analysis of one single authors body of writing. For more information, see https://www.french.utoronto.ca/undergraduate', null, 1, '{"operator": "AND", "items": ["FRE246H1", {"credits": 1.0, "department": null}, {"operator": "OR", "items": ["FRE310H1", "FRE314H1", "FRE318H1", "FRE319H1", "FRE320H1", "FRE324H1", "FRE326H1", "FRE332H1", "FRE334H1", "FRE336H1", "FRE345H1"]}]}'::jsonb),
    ('FRE446H1', 'Advanced Studies in Literary Theory', '24S', 'An advanced, research-oriented course devoted to specific issues in French literary theory. Focus on particular theoretical concepts, paradigms, schools, trends, movements or major thinkers. For more information, see https://www.french.utoronto.ca/undergraduate', null, 1, '{"operator": "AND", "items": ["FRE246H1", {"credits": 1.0, "department": null}, {"operator": "OR", "items": ["FRE310H1", "FRE314H1", "FRE318H1", "FRE319H1", "FRE320H1", "FRE324H1", "FRE326H1", "FRE332H1", "FRE334H1", "FRE336H1", "FRE345H1"]}]}'::jsonb),
    ('FRE471H1', 'Medieval French Language', '12T/24S', 'This course aims to ensure an understanding of Old French, to read most of the medieval texts. From a selection of texts, it explores the form of the language in various centuries and regions and provide a basis for understanding the history of the French language. This course is also listed in the offerings of the Graduate department of French.', null, 1, '{"operator": "OR", "items": ["FRE272H1", "FRE273H1"]}'::jsonb),
    ('FRE483H1', 'Experimental Methods in French Linguistics', '36L', 'This course is designed to provide students with the skills and knowledge required to carry out language-related research with human subjects. The course introduces students to research design and ethics, common experimental methodologies in linguistics research, and data analysis. The course includes a practical component that will provide students with the opportunity to design and carry out a corpus study or web-based linguistics experiment. Throughout the course, students will also be encouraged to reflect on how language research can contribute to broader domains in society, including education and health.', null, 2, '{"operator": "AND", "items": ["FRE383H1"]}'::jsonb),
    ('FRE486H1', 'Special Topics in French Linguistics', '12T/24S', 'An advanced course on a particular topic in the use, acquisition, history or synchronic analysis of French. Please see the French Department website https://www.french.utoronto.ca/undergraduate for the description of the particular course in a given year', 'JFL478H1', 2, null::jsonb),
    ('FRE487H1', 'Advanced Topics in Bilingualism and L2 acquisition', '12T/24S', 'This course examines how adult learners acquire various aspects of French language (vocabulary, syntax and/or phonology). It also provides in-depth, practical training in methodological design and quantitative analysis culminating in students'' undertaking of individual experimental studies.', null, 2, '{"operator": "AND", "items": ["FRE376H1", "FRE378H1", "FRE383H1", {"operator": "OR", "items": ["FRE388H1", "JFG388H1"]}]}'::jsonb),
    ('FRE488H1', 'Special Topics in Advanced Linguistics I', '12T/24S', 'An advanced seminar on a specific aspect of French linguistics. For more information, see https://www.french.utoronto.ca/undergraduate.', null, 2, null::jsonb),
    ('FRE489H1', 'Special Topics in Advanced Linguistics II', '12T/24S', 'An advanced seminar on a specific aspect of French linguistics. For more information, see https://www.french.utoronto.ca/undergraduate.', null, 2, null::jsonb),
    ('FRE490Y1', 'Senior Essay', null, 'A research project on a linguistic, literary, or second language learning topic to be proposed by the student and supervised by a Faculty member, culminating in a major research paper. Not eligible for CR/NCR option. For information on the application process and deadlines, please visit our website.', null, null, null::jsonb),
    ('FRE491H1', 'Independent Study', null, 'A research project on a linguistic, literary, or second language learning topic to be proposed by the student and supervised by a Faculty member on a topic of common interest, including readings, discussions, papers. Not eligible for CR/NCR option. For information on the application process and deadlines, please visit our website.', null, null, null::jsonb),
    ('FRE492H1', 'Independent Study', null, 'A research project on a linguistic, literary, or second language learning topic to be proposed by the student and supervised by a Faculty member on a topic of common interest, including readings, discussions, papers. Not eligible for CR/NCR option. For information on the application process and deadlines, please visit our website.', null, null, null::jsonb),
    ('FSL100H1', 'Elementary French I', '36L', 'An intensive basic course in spoken and written French for students who have absolutely no prior knowledge of French: comprehension, speaking, reading, and writing.', 'FSL102H1,  FSL120H1,  FSL121Y1,  FSL122H1, FSL 200+ level courses', 1, null::jsonb),
    ('FSL102H1', 'Elementary French II', '36L', 'An intensive basic course in spoken and written French for students who have minimal French experience.', 'FSL120H1,  FSL121Y1,  FSL122H1, FSL 200+ level courses, placement in  FSL120H1,  FSL122H1, FSL200+ level courses based on the results of the French Placement Test', 1, '{"operator": "AND", "items": ["FSL100H1"]}'::jsonb),
    ('FSL120H1', 'Elementary French III', '36L/12T', 'This course is intended for students having some knowledge of French but wishing to increase their proficiency in written and spoken French comprehension and production. Students also gain an introduction to a variety of French-speaking cultures.', 'FSL121Y1,  FSL122H1, FSL 200+ level courses, placement in  FSL122H1 or FSL200+ level courses based on the results of the French Placement Test.', 1, '{"operator": "AND", "items": ["FSL102H1"]}'::jsonb),
    ('FSL122H1', 'Elementary French IV', '36L/12T', 'This course is intended for students having some knowledge of French but wishing to further increase their proficiency in written and spoken French comprehension and production. The focus will be on developing greater autonomy and exploring a variety of French-speaking cultures.', 'FSL121Y1, FSL 200+ level courses, placement in FSL200+ level courses based on the results of the French Placement Test.', 1, '{"operator": "AND", "items": ["FSL120H1"]}'::jsonb),
    ('FSL195Y0', 'French Language in Tours I', '48L/48T', 'Intended for students having some knowledge of French but wishing to increase their proficiency to that of normal University entrance through complete immersion in French language and culture in Tours, France. Offers training in written and spoken French; reinforcement of reading comprehension and aural abilities; and an introduction to French culture of the Touraine region. Specific course content will depend on language placement according to the Institut de Touraine. Students must write the in-person Faculty of Arts & Science (St. George) Department of French placement test upon their return to Toronto to determine their appropriate next level. (This course is offered only during the Summer Session through the Summer Abroad Program. Details related to the timetable and deadlines are posted on the Summer Abroad website at https://summerabroad.utoronto.ca/.)', 'FSL121Y1,  FSL121Y0,  FSL122H1,  FSL220H1,  FSL221Y1,  FSL221Y0,  FSL222H1,  FSL224H1,  FSL225H1,  FSL226H1,  FSL271H1,  FSL295Y0,  FSL312H1,  FSL313H1,  FSL314H1,  FSL315H1,  FSL320H1,  FSL321Y1,  FSL321Y0,  FSL322H1,  FSL375H1,  FSL375Y1,  FSL415H1,  FSL420H1,  FSL421Y1,  FSL421Y0,  FSL442H1,  FSL443H1,  FSL442H0,  FSL443H0,  FSL472H1,  FSL473H1,  FSL475H1,  FRE210H1,  FRE245H1,  FRE272H1,  FRE273H1', 1, null::jsonb),
    ('FSL220H1', 'Intermediate French I', '36L/12T', 'This course provides students with the opportunity to become proficient, focused, autonomous French language learners. The course''s main objective is to provide a communicative learning environment through activities structured around real-world, everyday contexts.', 'FSL221Y1,  FSL222H1,  FSL224H1,  FSL225H1,  FSL226H1,  FSL271H1, FSL300+ level courses, placement in  FSL222H1 or higher based on the results of the French Placement Test.', 1, '{"operator": "OR", "items": ["FSL121Y1", "FSL122H1"]}'::jsonb),
    ('FSL222H1', 'Intermediate French II', '36L/12T', 'This course provides students with the opportunity to become proficient, focused, autonomous French language learners. The course provides a communicative learning environment that develops cultural competence and linguistic awareness through activities in structured around real-world, everyday contexts. Students who are fluent French speakers, whose command of the French language is equivalent to near-native proficiency are not permitted to take this course.', 'FSL221Y1,  FSL271H1, FSL 300+ level courses, any FRE course, placement in FSL300+ level courses based on the results of the French Placement Test.', 1, '{"operator": "AND", "items": ["FSL220H1"]}'::jsonb),
    ('FSL224H1', 'Practical French for Exploring Linguistics', '24L/12T', 'This course is designed to present students with the practical skills, grammatical knowledge and metalinguistic awareness needed to engage with introductory French linguistics courses. Students will hone higher-order analytical skills related to French language and linguistics through comprehension and production exercises and activities. A variety of textual excerpts selected from several subfields of linguistics will allow exposure to the basic elements of French linguistics through which students will develop awareness and comfort with academic writing and academic discourse in French. Emphasis is on the appropriate use of formal registers, terminology, incorporation of logical connectors and analytical thinking in written and spoken French.', 'FSL225H1,  FSL312H1,  FSL313H1,  FSL314H1,  FSL315H1,  FSL322H1,  FSL375Y1,  FSL375H1, FSL 400-level courses.', 1, '{"operator": "AND", "items": ["FSL220H1"]}'::jsonb),
    ('FSL225H1', 'Practical French for Exploring Literature', '24L/12T', 'This course is designed to present students with the practical skills, grammatical knowledge and metalinguistic awareness needed to engage with introductory French literature courses. Students will hone higher-order analytical skills related to French language and literature through comprehension and production exercises and activities. A variety of textual excerpts selected from geographically diverse essays, poetry and novels will allow exposure to the basic elements of French literary analysis through which students will develop awareness and comfort with academic writing and academic discourse in French. Emphasis is on the appropriate use of formal registers, terminology, incorporation of logical connectors and analytical thinking in written and spoken French.', 'FSL224H1,  FSL312H1,  FSL313H1,  FSL314H1,  FSL315H1,  FSL322H1,  FSL375Y1,  FSL375H1, FSL 400-level courses.', 1, '{"operator": "AND", "items": ["FSL220H1"]}'::jsonb),
    ('FSL226H1', 'Strategies for Autonomous Learning in French as a Second Language', '24L/12T', 'This course provides French language learners with an understanding of how one best acquires French as a second or third language including various FSL strategies that allow for effective, autonomous learning. It further implements a structure to encourage continuous active reflection and self-assessment. Students will first learn about the types of knowledge and sub-skills that must be acquired to master French including vocabulary and grammar. Language benchmarks and self-evaluation tools are then introduced to help learners to profile their four main competences (reading, writing, listening, and speaking). Subsequently, they will receive practical training in the use of specific online resources (e.g., Bon Patron) geared towards improving French writing.', 'FRE226H1,  FRE225Y1/ JFI225Y1,  FSL375H1,  FSL375Y1, FSL 400-level courses', 2, '{"operator": "OR", "items": ["FSL221Y1", "FSL222H1"]}'::jsonb),
    ('FSL295Y0', 'French Language in Tours II', '48L/48T', 'Intended for those who have some knowledge of French, this course provides students with the opportunity to become proficient, focused, autonomous French language learners through complete immersion in French language and culture in Tours, France. The course''s main objective is to provide a communicative learning environment through activities based in real-world, everyday contexts, as well as an introduction to French culture of the Touraine region. Specific course content will depend on language placement according to the Institut de Touraine. Students must write the in-person Faculty of Arts & Science (St. George) Department of French placement test upon their return to Toronto to determine their appropriate next level. (This course is offered only during the Summer Session through the Summer Abroad Program. Details related to the timetable and deadlines are posted on the Summer Abroad website at https://summerabroad.utoronto.ca/.)', 'FSL312H1,  FSL313H1,  FSL314H1,  FSL315H1,  FSL320H1,  FSL321Y1,  FSL321Y0,  FSL322H1,  FSL375H1,  FSL375Y1,  FSL415H1,  FSL420H1,  FSL421Y1,  FSL421Y0,  FSL442H1,  FSL443H1,  FSL442H0,  FSL443H0,  FSL472H1,  FSL473H1,  FSL475H1', 1, null::jsonb),
    ('FSL312H1', 'Writing French: the Language of the Media', '36L', 'Using current online French media, broaden your understanding of the French language; deepen your grammatical knowledge; expand your vocabulary (including idioms); review key aspects of French syntax; and fine-tune your reading skills in French. Weekly reading and writing workshops are an integral part of this course.', 'FSL320H1,  FSL321Y1,  FSL322H1,  FSL375H1,  FSL375Y1, FSL 400-level courses. Students who are fluent French speakers or whose command of the French language is equivalent to near-native proficiency must contact the Department of French before enrolling in this course.', 1, '{"operator": "OR", "items": ["FSL221Y1", "FSL222H1"]}'::jsonb),
    ('FSL314H1', 'French for the Arts', '36L', 'Introduction to the study of central themes in French artistic expression, designed to familiarize students with key concepts and vocabularies relevant to the subject. Study of modes of artistic representation, (visual, performing arts) and their contribution to the rich heritage and identity of French culture. Observation, description and analysis of various artistic mediums.', 'FSL320H1,  FSL321Y1,  FSL322H1,  FSL375H1,  FSL375Y1, FSL 400-level courses. Students who are fluent French speakers or whose command of the French language is equivalent to near-native proficiency must contact the Department of French before enrolling in this course.', 1, '{"operator": "OR", "items": ["FSL221Y1", "FSL222H1"]}'::jsonb),
    ('FSL315H1', 'French Oral Communication for Professional and Academic Contexts', '36L', 'This course is designed for students who wish to develop their oral communication skills in French in preparation for bilingual employment, community service, and academic activities in Canada and abroad. Emphasis is placed on the development of skills for accurate oral language use in professional and academic contexts: researched oral presentations, debates, interviews, and student-led discussions. Students will learn how to adapt their speaking style and register to different audiences and situations, use appropriate vocabulary, and self-correct.', 'FSL320H1,  FSL321Y1,  FSL322H1,  FSL375H1,  FSL375Y1, FSL 400-level courses. Students who are fluent French speakers or whose command of the French language is equivalent to near-native proficiency must contact the Department of French before enrolling in this course.', 1, '{"operator": "OR", "items": ["FSL221Y1", "FSL222H1"]}'::jsonb),
    ('FSL320H1', 'Intermediate French III', '36L', 'This course is intended for students who have already mastered the basic competences in French language proficiency. The materials used in this course adopt an active approach which puts emphasis on the student being at the centre of the learning process. Students will solidify writing, and speaking skills as well as understanding of written and spoken French through exploration of a variety of cultures and viewpoints.', 'FSL321Y1,  FSL322H1,  FSL375Y1,  FSL375H1, FSL 400-level courses. Placement in  FSL322H1 or higher based on the results of the French Placement Test.', 1, '{"operator": "OR", "items": ["FSL221Y1", "FSL222H1"]}'::jsonb),
    ('FSL322H1', 'Intermediate French IV', '36L', 'This course is intended as a transition from intermediate- to advanced-level French language proficiency. The materials used in this course adopt an active approach which puts emphasis on the student being at the centre of the learning process. Students will solidify writing, and speaking skills as well as understanding of written and spoken French of various registers through exploration of a variety of cultures and viewpoints.', 'FSL321Y1,  FSL375Y1,  FSL375H1, any FSL 400-level course, placement at the FSL400+ level based on the results of the French Placement Test. May not be taken concurrently with  FSL312H1,  FSL313H1,  FSL314H1,  FSL315H1.', 1, '{"operator": "OR", "items": ["FSL320H1"]}'::jsonb),
    ('FSL375H1', 'Practical Translation: French - English', '36L', 'This introduction to translation, is designed to improve students'' mastery of French stylistics through English to French and French to English translations. Emphasis is on the practice of translation of a variety of texts and documents with an introduction to the practice of oral interpretation from one language to the other.', 'FSL375Y1,  FSL415H1,  FSL442H1,  FSL443H1,  FSL472H1,  FSL473H1,  FSL475H1. Students who are fluent French speakers or whose command of the French language is equivalent to near-native proficiency must contact the Department of French before enrolling in this course.', 1, '{"operator": "OR", "items": [{"credits": 1.0, "department": "FSL"}]}'::jsonb),
    ('FSL415H1', 'Business French', '36S', 'This course is designed to strengthen oral and written communication skills in French and develop intercultural competence for a variety of career paths including public relations, international development, federal and provincial government. Students will gain expertise in spoken and written French through in-class activities supported by multimedia.', 'Students who are fluent French speakers or whose command of the French language is equivalent to near-native proficiency must contact the Department of French before enrolling in this course.', 2, '{"operator": "OR", "items": ["FSL321Y1", "FSL322H1", "FSL315H1"]}'::jsonb),
    ('FSL420H1', 'Advanced French I', '36L', 'This advanced course in French aims to provide students with a broader understanding and appreciation of French and Francophone culture through the reading and discussion of a variety of texts and multimedia materials. Emphasis is placed on mastery of language skills such as reading comprehension and vocabulary, oral and written communication.', 'FSL421Y1,  FSL442H1,  FSL443H1,  FSL472H1. Students who are fluent French speakers or whose command of the French language is equivalent to near-native proficiency must contact the Department of French before enrolling in this course.', 1, '{"operator": "OR", "items": ["FSL321Y1", "FSL322H1"]}'::jsonb),
    ('FSL442H1', 'Advanced Written French II', '36L', 'Designed for students who wish to consolidate and perfect their writing abilities. Skills developed include the mastery of register-based differences; use of rhetorical and stylistic techniques and systematic self-correction.', 'Students who are fluent French speakers or whose command of the French language is equivalent to near-native proficiency must contact the Department of French before enrolling in this course.', 1, '{"operator": "OR", "items": ["FSL421Y1", "FSL420H1"]}'::jsonb),
    ('FSL443H1', 'Advanced Oral French II', '36L', 'This course is designed for students who wish to consolidate and perfect their oral (speaking and listening) abilities. Oral production and improvement of pronunciation will be practiced through reading exercises, presentations, debates, and discussions focusing on a rich vocabulary and contextually appropriate speech registers. Training in the comprehension of spoken French will aim at the development of students'' listening skills through the study of recordings related to various situations and topics.', 'FSL473H1. Students who are fluent French speakers or whose command of the French language is equivalent to near-native proficiency must contact the Department of French before enrolling in this course.', 1, '{"operator": "OR", "items": ["FSL421Y1", "FSL420H1", "FSL375Y1", {"operator": "AND", "items": ["FSL375H1", {"credits": 0.5, "department": "FRE"}]}]}'::jsonb),
    ('FSL472H1', 'Reading and Writing Fiction and Non-Fiction in French', '36L', 'An online course designed for students who wish to further develop their reading and writing skills in French. Students will acquire analytic tools to comprehend, analyze and write fiction and non-fiction texts. Multimedia approach to understanding the cultural experiences of francophone world.', 'FSL442H1. Students who are fluent French speakers or whose command of the French language is equivalent to near-native proficiency must contact the Department of French before enrolling in this course.', 1, '{"operator": "OR", "items": ["FSL375Y1", {"operator": "AND", "items": ["FSL375H1", {"credits": 0.5, "department": "FRE"}]}, "FSL420H1"]}'::jsonb),
    ('FSL475H1', 'Creative Writing in French', '36L', 'Do you like creative writing? Are you simply curious about it? Do you want to hone your writing skills in French and develop your creative voice in the process? Then this course is for you. Part workshop in which constructive and supportive feedback will help you develop your writing in French and your creativity, part literary discussion on various aspects of literary technique such as character, setting, plot, point of view, structure or revision (through reading).', 'Students who are fluent French speakers or whose command of the French language is equivalent to near-native proficiency must contact the Department of French before enrolling in this course.', 1, '{"operator": "OR", "items": ["FSL375Y1", "FSL375H1", "FSL421Y1", "FSL420H1"]}'::jsonb),
    ('GER100Y1', 'Introduction to German', '96P', 'This is the language course to take if you have had no previous experience of the German language. The emphasis is on comprehension, speaking, reading, writing, vocabulary and basic grammar. This course can be counted towards all programs in German. Note: Students with any previous knowledge of German are REQUIRED to take a placement test offered at the department.', 'Senior high school German or equivalent. Note: Students with any previous knowledge of German are required to take a placement test offered at the department.', 1, null::jsonb),
    ('GER101H1', 'Introduction to German b', '48P', 'This course is intended for students with some prior knowledge of German. It is equivalent to the Spring Term of  GER100Y1. The emphasis is on comprehension, speaking, reading, writing, vocabulary and basic grammar.', 'Senior high school German or equivalent.  GER100Y1.', 1, null::jsonb),
    ('GER150H1', 'Introduction to German Culture (E)', '24L/12T', 'This course taught in English is intended for students who are unfamiliar with German culture. It examines historical, political and cultural developments in Germany from about 1871 to the present focusing on literary and non-literary texts. (Note: This course is required for the major and specialist program; it should be taken within the first two years.)', null, 1, null::jsonb),
    ('GER194H1', 'Our Vampires, Ourselves (E)', '24S', 'Vampires are among the most fascinating figures of popular culture. Since Bram Stoker''s Dracula (1897) – and, in fact, well before that – they have been haunting the human imagination in various shapes and forms. This course examines the figure of the vampire as a potent cultural metaphor in the German context and beyond, showing how every age embraces the vampires it needs and gets the vampires it deserves. The goal is to teach students to reflect critically and independently on issues of self and society and to develop a structured approach to critical thinking in general. All readings and class discussions will be in English. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('GER195H1', 'Cities, Real and Imagined (E)', '24S', 'Cities have been described as places of desire and places of fear. They pulse with life, bringing together people from different class, gender, and ethnic backgrounds, simultaneously giving rise to a sense of freedom and oppression, a sense of belonging and alienation. This course will explore the city as a physical reality that shapes our lives, but is also a projection of our deepest imaginings. Through readings of philosophical and sociological texts by influential theorists of the city, we will consider various ancient and modern conceptions of urban space and subjectivity. Alongside these theoretical readings, we will also examine literary and filmic representations of the city as a space of desire, memory and power. All readings and class discussions are in English. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('GER198H1', 'Technology and the Human in German Literature and Thought (E)', '24S', 'Technology has changed our lives, and scientific knowledge has enhanced human capacities. At the same time, though, this development is also experienced as a threat. Killing missiles, controlling ''Big Brothers,'' and monstrous creatures are often considered the flip-side of technological advancement. This course asks: What is the relationship between technology and the "human"? Can there be progress of technology without a regress of humanity? Or is technology liberating us from the bonds of nature? We will discuss possible answers to these questions by looking at key texts in German literature, philosophy, and cultural history from the eighteenth century to Post-Modernity. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('GER200Y0', 'Intermediate German 1', '96S', 'This course continues the work done in  GER100Y1/  GER101H1. It further expands on basic grammar and vocabulary, practice in comprehension, composition, and conversation.', null, 1, '{"operator": "OR", "items": ["GER100Y1", "GER101H1"]}'::jsonb),
    ('GER200Y1', 'Intermediate German 1', '96P', 'This course continues the work done in  GER100Y1 /  GER101H1. It further expands on basic grammar and vocabulary, practice in comprehension, composition, and conversation.', null, 1, '{"operator": "OR", "items": ["GER100Y1", "GER101H1"]}'::jsonb),
    ('GER201H1', 'Intermediate German 1b', '48P', 'This course is equivalent to the Spring Term of  GER200Y1. It further expands on basic grammar and vocabulary, practice in comprehension, composition, and conversation. The Department reserves the right to place students in the appropriate language course on the 200- and 300 levels.', 'GER200Y1', 1, null::jsonb),
    ('GER205H1', 'Masterpieces of German Literature 1', '36S', 'This course offers a transition from the language courses to the topic courses on the 300-level. It introduces students to German literature and provides them with working methods and analytical tools relevant for the study of German literary texts in the original German. Note: This course is required for the major program. It should be taken as early as possible, and cannot be taken after completion of  GER300Y1 or  GER301H1. This course is the prerequisite course for 300-level topic courses in German.', 'GER300Y1,  GER301H1', 1, '{"operator": "OR", "items": ["GER100Y1"]}'::jsonb),
    ('GER210H1', 'Poets and Power: Art, Media, and the Nazis (E)', '12T/24S', 'To the surprise of many, aesthetics played a vital role in the lives of Nazis and their politics. Hitler was a failed painter, Goebbels a poet, and Göring a collector; other high-ranking officials likewise fashioned themselves as artists. In this course, we will examine how these personal predilections transformed into an aesthetic vision of politics: through the fascist cult of physical perfection, the theatrics of political media, anti-Semitic entertainment films, and the eroticization of the Führer-figure. We will investigate this marriage of beauty and violence and ask how it helped to make the "Third Reich" attractive to many Germans. Beginning with the great avant-garde experiments of the pre-Nazi era, we will analyze why Hitler banned this "degenerate" art – even though he adopted some of its style in propaganda posters. We will continue by examining the Nazis'' glorification of Greek and Roman images of beauty and their aesthetic justifications for genocide. Throughout the course, we will consider some of the high points of German culture – in philosophy, music, and literature – and ask: How did a society that produced such works of genius also create Nazism and the Holocaust? Is high culture necessarily a bulwark against barbarism? And do we have similarly seductive combinations of culture and politics in our world today? How might we notice such allures yet still mark their dangers, maintain our critical distance, and resist?', null, 1, null::jsonb),
    ('GER220H1', 'Great Works of German Literature in Translation (E)', '24L/12T', 'This course taught in English is an introduction to major authors of German literature, such as J.W. Goethe, F. Kafka, T. Mann, G. Grass, C. Wolf and E.S. Özdamar, focusing on their key works and introducing central topics.', null, 1, null::jsonb),
    ('GER251H1', 'German and European Cinema (E)', '24P/24S', 'This course examines German cinema against the backdrop of European film history. European films share common references points anchored in the cataclysms of two world wars, and have also negotiated analogous postwar transformations in family life, urbanization, the regional and the national, cultural identity, labour relations, post-socialist societies, and state security. A comparative approach enables examination of what binds German cinema to European cinema – shared histories and political concerns--as well as what is nationally unique and distinctive. By matching select films with readings from social theory, cultural studies, and film studies, we will compare and contrast these socio-historical concerns while also attending to the medium specificities of film style, aesthetics, and narrative form.', null, 1, null::jsonb),
    ('GER261H1', 'Elementary Yiddish 1', '36L', 'This course introduces Yiddish language, literature, music, theater, and cinema through interactive multi-media seminars, designed to build proficiency in reading, writing and comprehending. No prior knowledge of Yiddish is required.', 'GER260Y1', 1, null::jsonb),
    ('GER262H1', 'Elementary Yiddish 2', '36L', 'This course is the continuation of  GER261H1, Elementary Yiddish 1. While learning the language the course will also introduce students to Yiddish literature & culture, providing a greater understanding of the historical and contemporary, religious and secular communities that speak and spoke this language.', 'GER260Y1', 1, '{"operator": "OR", "items": ["GER261H1"]}'::jsonb),
    ('GER270H1', 'Money and Economy in German Literature and Culture (E)', '24L/12T', 'In this course, we examine key literary, philosophical, and cultural texts, in order to understand how modern culture approaches problems such as property, debt, and exchange value.', null, 1, null::jsonb),
    ('GER272H1', 'Introduction to Business German', '36P', 'This course introduces students to basic concepts and vocabulary necessary for the German business context. All the language skills (reading, writing, listening, and speaking) will be practiced in appropriate business contexts.', null, 1, null::jsonb),
    ('GER275H1', 'Marx, Nietzsche, Freud (E)', '24L/12T', 'This is an introductory course to the thought of Karl Marx, Friedrich Nietzsche, and Sigmund Freud and their pioneering contributions to the understanding of the individual and society in modernity. Readings include selections from writings of the early Marx, the Communist Manifesto, and Capital, Nietzsche''s critique of culture, academe, and nationalism, and Freud''s theory of culture, his views on the psychopathology of everyday life, on the meaning of dreams, symptoms, the return of the repressed, and what it might mean to live in a free society.', null, 1, null::jsonb),
    ('GER290H1', 'Global Issues - German Contexts (E)', '24S', 'The movement of cultural products, material goods, capital, people, ideas, and information across national borders has resulted in a new quality of global interdependency. The course explores the contemporary character of globalization patterns and problems as they bear on German-speaking contexts. Readings in globalization history and theory.', null, 3, null::jsonb),
    ('GER299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GER299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GER300Y0', 'Intermediate German 2', '96S', 'Continuing the work done in  GER100Y1 and  GER200Y1, this course offers German at the intermediate level focusing on extension of vocabulary, specific problems of grammar, essay-writing, reading and conversation. The Department reserves the right to place students in the appropriate course in the series  GER200Y1 and  GER300Y1.', null, 1, '{"operator": "OR", "items": ["GER200Y1", "GER201H1", "GER200Y0"]}'::jsonb),
    ('GER300Y1', 'Intermediate German 2', '96P', 'Continuing the work done in  GER100Y1 and  GER200Y1, this course offers German at the intermediate level focusing on extension of vocabulary, specific problems of grammar, essay-writing, reading and conversation. The Department reserves the right to place students in the appropriate course in the series  GER200Y1 and  GER300Y1.', null, 1, '{"operator": "OR", "items": ["GER200Y1", "GER201H1"]}'::jsonb),
    ('GER301H1', 'Intermediate German 2b', '48P', 'This course is equivalent to the Spring Term of  GER300Y1. It further expands on basic grammar and vocabulary, practice in comprehension, composition, and conversation at the intermediate level. The Department reserves the right to place students in the appropriate language course on the 200- and 300 levels.', 'GER300Y1', 1, null::jsonb),
    ('GER310H1', 'Contemporary German Culture and Media', '24S', 'This course focuses on contemporary German culture as expressed through a variety of media. It approaches Germany and Germany''s position within Europe and the world mainly (but not exclusively) through non-literary texts.', null, 1, '{"operator": "OR", "items": ["GER200Y1"]}'::jsonb),
    ('GER320H1', 'Age of Goethe: Revolution and Romanticism', '24S', 'Goethe and his contemporaries saw themselves faced with a rapidly changing world. This course examines the innovative literary experiments they developed in response to these changing times.', null, 1, '{"operator": "OR", "items": ["GER205H1"]}'::jsonb),
    ('GER321H1', 'Literary Realism in the Industrial Age', '24S', 'This course focuses on German authors of the nineteenth century. Literary, political and philosophical texts are analyzed as a discussion of political uprisings, the industrial revolution and the emergence of German nationalism.', null, 1, '{"operator": "OR", "items": ["GER205H1"]}'::jsonb),
    ('GER322H1', 'Kafka''s World', '24S', 'Franz Kafka''s texts are read in the literary, historical, and philosophical context of fin-de-siècle Prague and central Europe.', null, 1, '{"operator": "OR", "items": ["GER205H1"]}'::jsonb),
    ('GER323H1', 'Weimar: Sex and Politics in the Roaring Twenties', '24S', 'Focusing roughly on the period from 1918 to 1945, this course examines literary and artistic movements like Dada, Bauhaus, the Golden Age in German film in the decades between World War I and Nazism.', null, 1, '{"operator": "OR", "items": ["GER205H1"]}'::jsonb),
    ('GER325H1', 'Open Topics in German Studies', '12S', 'This third-year course taught in German offers an in-depth exploration of diverse themes within German Studies, with a focus that varies from year to year. This course covers a wide range of topics, which may include contemporary issues in German-speaking societies, seminal German-language literary works, influential films, and philosophical movements.', null, null, '{"operator": "OR", "items": ["GER205H1"]}'::jsonb),
    ('GER326H1', 'Writing Memory: Post 1945', '24S', 'An examination of post-World War II German literature and culture from Zero Hour through to present-day debates about the Holocaust and its memorialization within a German context.', null, 1, '{"operator": "OR", "items": ["GER205H1"]}'::jsonb),
    ('GER330H1', 'Open Topics in German Studies', '12S', 'This third-year course taught in English offers an in-depth exploration of diverse themes within German Studies, with a focus that varies from year to year. This course covers a wide range of topics, which may include contemporary issues in German-speaking societies, seminal German-language literary works, influential films, and philosophical movements.', null, null, null::jsonb),
    ('GER332H1', 'Deviance - Madness - Outsiders', '24S', 'An analysis of the artistic confrontation with deviance, madness, and outsiders. The course covers expressions of this confrontation in a variety of genres.', null, 1, '{"operator": "OR", "items": ["GER205H1"]}'::jsonb),
    ('GER334H1', 'Post-Migrant Germany', '24S', 'This course investigates contemporary German culture by paying attention to its other or alternate voices and perspectives, i.e. those not usually prevalent in mainstream cultural and sociopolitical discourses.', 'GER423H1', 1, '{"operator": "OR", "items": ["GER205H1"]}'::jsonb),
    ('GER336H1', 'Berlin Between East and West', '24S', 'This course offers an exploration of the cultural developments of one of the most exciting capitals of the world, from the Bismarckian era to German reunification and beyond.', null, 1, '{"operator": "OR", "items": ["GER205H1"]}'::jsonb),
    ('GER340H1', 'German Theater Production', '48S', 'The course offers close reading, rehearsing and staging of a play. Students will become familiar with the different steps of a theater production, be introduced to basic acting and staging techniques and get acquainted to leading theories of theater.', null, 1, '{"operator": "OR", "items": ["GER200Y1"]}'::jsonb),
    ('GER345H1', 'Nietzsche', '24L/12T', 'This course introduces students to Nietzsche, the philosopher, critic, and cultural theorist and examines the critically enduring significance of his legacy. Students will be familiarized with his critical contributions to epistemology, ethics, psychology, the theory of history, culture, and education as well as his impact on rethinking the agenda of philosophy. A particular aspect of the course will be the contextualization of his interventions in the intellectual landscape of his period and Nietzsche''s notoriously provocative writing style.', null, null, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('GER350H1', 'German Visual Cultures', '24P/24S', 'This course presents students with a survey of the history and development of the German cinema. It examines major trends of German cinematography focusing on thematic and formal aspects.', null, 1, '{"operator": "OR", "items": ["GER205H1"]}'::jsonb),
    ('GER354Y0', 'Special Topics Summer Course (E)', '48S', 'The topics of this course taught in English and open to students from other disciplines vary from year to year. Interested students can address questions to Woodsworth College.', null, 1, null::jsonb),
    ('GER360H1', 'Intermediate Yiddish', '36P', 'The course conducted in Yiddish offers a review of basic grammar, stylistics, study of short literary texts.', 'GER463Y1', 1, '{"operator": "AND", "items": ["GER260Y1"]}'::jsonb),
    ('GER361H1', 'Yiddish Literature in Translation (E)', '24S', 'An overview of the major figures and tendencies in modern Yiddish literature and culture from the beginning of the 19th century to the present. Readings (in English) of modern Yiddish prose, poetry, drama and cinema.', null, 1, null::jsonb),
    ('GER367H1', 'Topics in Yiddish or German Jewish Literature and Culture [E]', '24S', 'Topics in modern Yiddish or German Jewish literature and culture from the beginning of the 19th century to the present, featuring a selection of readings of modern Yiddish prose, poetry, drama and cinema. Taught in English and open to students across disciplines.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('GER370H1', 'German Business Culture', '36P', 'This course provides students with a working knowledge of German business culture that allows them to navigate the German workplace. The main focus is to deepen students'' knowledge of business concepts. Note: This course is required for the minor program in Business German', null, 1, '{"operator": "OR", "items": ["GER272H1", "GER200Y1", "GER201H1"]}'::jsonb),
    ('GER372H1', 'Navigating German Work Environments', '36P', 'This course offers an intensive development of the linguistic skills needed in the context of business transactions and management in German-speaking countries. Through materials from various sources, students develop oral and written skills for competence in German business communication as well as cross-cultural awareness.', null, 1, '{"operator": "AND", "items": ["GER370H1"]}'::jsonb),
    ('GER391H1', 'iPRAKTIKUM Experiential Learning and Internationalization Internship', '24P', 'The course provides curricular support for a variety of work and community-engaged, experiential learning placements in the GTA and in German-speaking countries. The placements are designed to deepen linguistic, cultural, and analytical skills acquired in the classroom in work-related environments, create an awareness of the translatability of academic knowledge to other contexts, promote global competency, and foster links to the community. The number of weekly hours spent in the field, the scope of learning objectives, and the nature of reflective activities are determined on an individual basis in consultation with the host institution, the German Department, and other units in which the student is pursuing a program degree (as required). In addition to successfully achieving the formulated learning goals, students must complete assignments such as eJournals and research papers as well as participate in peer-to-peer reporting and post-placement interviews.', null, 3, '{"operator": "AND", "items": ["GER100Y1", "GER200Y1"]}'::jsonb),
    ('GER398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GER398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GER399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GER399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GER400H1', 'Advanced German 1', '48P', 'This is a course for advanced learners of German reviewing complex features of the language and introducing them to aspects of German stylistics. The emphasis lies on oral and written communication.', null, 1, '{"operator": "OR", "items": ["GER300Y1", "GER301H1"]}'::jsonb),
    ('GER401H1', 'Advanced German 2', '48P', 'This is a course for advanced learners of German reviewing complex features of the language and introducing them to aspects of German stylistics. The emphasis lies on oral and written communication.', null, 1, '{"operator": "AND", "items": ["GER400H1"]}'::jsonb),
    ('GER410H1', 'Topics in German Intellectual History (E)', '24S', 'This course taught in English offers an examination of key moments and themes in German intellectual history from the Enlightenment to the present.', null, 2, null::jsonb),
    ('GER426H1', 'Medieval Language and Culture [E]', '36S', 'This course offers an introduction to the language, literature and culture of Medieval Germany. The reading and translation of exemplary medieval German texts will introduce students to Middle High German and provide an insight into epochal concepts like courtly love and chivalry as well as courtly and monastic designs of identity.', null, 1, '{"operator": "AND", "items": ["GER300Y1", "GER205H1"]}'::jsonb),
    ('GER430H1', 'Topics in German Literature and Culture', '24S', 'An open course which explores specific aspects of German literature and culture.', null, 1, '{"operator": "AND", "items": ["GER305H1"]}'::jsonb),
    ('GER431H1', 'Topics in Germanic Studies', '24S', 'An open course which explores specific aspects of Germanic Studies.', null, 1, '{"operator": "AND", "items": ["GER305H1"]}'::jsonb),
    ('GER460H1', 'Advanced Yiddish', '36P', 'This course conducted entirely in Yiddish focuses on advanced reading, writing, vocabulary and conversation, the study of poetry, short fiction, and memoir literature by leading authors. Selected advanced grammatical topics are presented in conjunction with the study of texts.', 'GER462H1', 1, '{"operator": "AND", "items": ["GER360H1"]}'::jsonb),
    ('GER463Y1', 'Yiddish Language for German Speakers', '48P', 'The course is designed as an intensive Yiddish language training. The goal is to teach German speakers to read, write and speak in Yiddish. The curriculum relies on the German language skills of the students, and focuses on differences between Yiddish ad German grammar and vocabulary. Upon the completion of the course, students should be able to read Yiddish literary texts with a minimal use of dictionary. Note: Graduate students can take the course in preparation for their Yiddish competency test.', 'GER260Y1,  GER360H1,  GER462H1', 1, '{"operator": "AND", "items": [{"credits": 3.0, "department": "GER"}]}'::jsonb),
    ('GER490H1', 'Independent Study', '24S', 'A reading & research project in Germanic literature and/or culture involving a substantive research component. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GER491Y1', 'Individual Studies', '48S', 'A scholarly project chosen by the student and supervised by a member of the staff. The form of the project and the manner of its execution are determined in consultation with the supervisor. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GGR101H1', 'Histories of Environmental Change', '24L', 'This course will investigate geological, biological and archaeological evidence of environmental change. We will examine the processes that have driven and will drive environmental change and how past societies have shaped and responded to these changes. The emphasis is on the current interglacial period, or Holocene, and how shifts in population and technologies have affected human-environment interactions. As language of the Holocene gives way, for many, to that the Anthropocene, the implications of environmental change for present and future human societies will be our concluding concern.', null, 4, null::jsonb),
    ('GGR107H1', 'Environment, Food and People', '24L/12T', 'Examines the relations between food, nature, and society. Food is fundamental to human existence, and central to most cultures; it also has significant and widespread effects on the physical and social environments. Food is used as a lens to explore human-environment interactions locally and globally. Serves as an introduction to environmental and human geography.', null, 3, null::jsonb),
    ('GGR112H1', 'Geopolitics, Globalization, and Inequality', '24L/8T', 'This course is an introduction to key approaches and concepts in political, cultural, and economic geography. Our focus will be on pressing contemporary phenomena with deep historical roots, including border initiatives, colonialism and development, globalization and global health, migration, and diplomacy and militarization. Without aiming for a comprehensive approach, examples will be diverse and drawn from around the planet.', null, 3, null::jsonb),
    ('GGR124H1', 'Cities and Urban Life', '24L/6T', 'Offers an introduction to North American cities and urbanization in a global context. It explores social, cultural, political and economic forces, processes, and events that shape contemporary urbanism. The course adopts the lens of ''fixity'' and ''flow'' to examine how the movement of people, ideas, goods, and capital, as well as their containment in the infrastructure and space of the city, give rise to particular urban forms.', 'GGR207H5', 3, null::jsonb),
    ('GGR172H1', 'Digital Earth', '24L/12T', 'This course examines the changing role of geographic information and maps in society. It considers how spatial information is produced, organized, and used in different historical, cultural, and political contexts. Topics examined include: the effects of the shift from print to digital mapping; implications of mobile spatial technologies and the geoweb; open source and open access; production and control of spatial data and information; and alternative cartographies. Introduces concepts of Geospatial Literacy, Critical Mapping and Critical GIS.', 'GGR225H1', 3, null::jsonb),
    ('GGR196H1', 'The Yard: Micro-Geographies of Household Outdoor Spaces', '24S', 'A “yard” is the area of land immediately adjacent to a building, often a residence. By examining micro-geographies (that is, detailed empirical studies of a small, specific locale) of these ubiquitous, everyday spaces, the course explores how yards are intimately connected with broader ecologies, cultures, and social relations, all of which can be explored using geographic theories and techniques. The course also serves as an introduction to other subjects that are relevant to navigating post-secondary life, such as: critical reading; conducting university-level research; presenting and communicating ideas in the classroom; teamwork, and how to benefit from it; and developing social networks. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('GGR197H1', 'Re(story)ing the Earth: Indigenous Wisdoms, Ecological Stewardship, and Global Climate Action', '24S', 'In current times of ecological precarity, marked by climate change, ecological degradation and mass species extinction, the task of ecological restoration has become an urgent, perhaps the most urgent challenge for humanity. At its core, this task is fundamentally about re-story-ing human relationships with the more-than-human world. It is about changing the story of who we are as humans and how we relate to and belong to the rest of the world. For this, we would do well to turn to Indigenous cultures around the world for guidance. Indigenous Peoples around the world have often maintained relationships of care, respect and reciprocity with the natural world and offer pathways healing ecologies (and us in the process). The course will draw from Indigenous worldviews, ontologies, activism, and environmental justice movements from around the world to question top-down, market-oriented, technocentric solutions to climate change and ecological crisis; and will explore alternative ways of organizing our social and economic lives to address it. We will learn from Indigenous scholars, and from Indigenous Elders and community leaders from Canada and the global South, about ecological stewardship, efforts for decolonization and social transformation, and learn how to translate these lessons to everyday environmentalism that we can practice here and now. This learning will be facilitated by guest lectures, videos, and virtual visits with communities in different parts of the world. Action-oriented assignments will foster problem-solving and experiential learning. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('GGR198H1', 'Mobility and Borders', '24S', 'This course examines the political geographies of transnational migration. It asks how spaces of migration and mobility are political, and how migration politics are tied to inequalities wrought through intersecting histories of race, class, and gender. It seeks to extend our understandings of migrants, borders, and mobility, and it explores the processes through which mobility is produced, delimited and structured. We will consider the transnational politics of migration, the militarization of border zones, and the political spaces of migrant displacement, dispossession, and dislocation. The seminar readings focus on classical paradigms as well as emerging approaches in immigration studies. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('GGR199H1', 'Global Racial Capitalism in the 21st Century', '24S', 'This course uses the tools of political economy, decolonial and anti-colonial theory, and critical approaches to the study of racism to explore how the construction of racial categories continues to be integral to the working of capitalist systems. We will explore the reasons why capitalism was never meant to work for everyone by examining how and why racial categories have continued to matter since capitalism''s earliest formations. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('GGR203H1', 'Introduction to Climatology', '36L', 'Introduction to the large scale processes responsible for determining global and regional climate and atmospheric circulation patterns, as well as the small scale processes responsible for determining the microclimates of specific environments.', null, 5, null::jsonb),
    ('GGR217H1', 'Urban Landscapes and Planning', '24L/4T', 'Considers the role of planning in shaping the urban landscape through historical and contemporary examples that illustrate the interplay of modernist and post-modernist approaches to city building. Traces the origins, competing rationalities and lingering effects of planning in the production of urban space. Broaches possibilities for engaging planning critically to address challenges of social and environmental justice in cities today.', 'GGR361H1', 3, null::jsonb),
    ('GGR221H1', 'New Economic Spaces', '24L/4T', 'Provides an introduction to economic geography and economic geography theory from the 1970s on, illustrating the different ways that geographers have conceptualized the restructuring of resource industries, manufacturing and services. The crisis of Fordism and the rise of new production models will be given particular attention, along with the reorganization of finance, the rise of cultural industries and the globalization of commodity chains. New regimes of governance of the economy will also be considered.', null, 3, null::jsonb),
    ('GGR223H1', 'Environment, Society and Resources', '24L/6T', 'Focuses on society-environment relations and different approaches to resource governance and management. This includes exploration of the spatial, social, and political economic origins and implications of humans'' changing relations to nature. Drawing on debates from environmental governance and political ecology literatures, the course also investigates the ways that different actors and institutions have framed and sought solutions to environmental and resource challenges.', null, 3, null::jsonb),
    ('GGR240H1', 'Geographies of Colonialism in North America', '24L/5T', 'This course considers the creation and consolidation of settler colonies in the region known to many as North America. With an eye to the colonial present, the course focuses on the period from the 15th century to the early 20th century. Cultural texts and place-specific cases are used to ground themes and processes that also bear on the wider field of historical geography, including narratives of discovery and possession; ecological imperialism and environmental transformation; the (re)settlement of land and colonial government; enslavement and industrialization; frontiers, borders, and resource extraction; and some of the Indigenous geographies that preceded, were transformed by and transformed, and exceeded the reach of colonial power. Potential field trip.', null, 3, null::jsonb),
    ('GGR246H1', 'Geography of Canada', '24L', 'Social and economic differences have been, and continue to be, a prominent feature of Canada''s geography. In this course these differences are examined at a regional and local scale. The course adopts a thematic approach and considers issues such as historical development, urbanization, industrialization, immigration and population change, Canada''s cultural mosaic and native issues. Emphasis will be placed on the evolution of social and economic policies and Canada''s incorporation into a global economy.', 'GGR202H5', 3, null::jsonb),
    ('GGR251H1', 'Geography of Innovation', '24L', 'Explores how new technologies and industries are generated and sustained, or failed to be. Focuses on the dynamics of leading technological sectors such as electronics, automobiles and biotechnology in their geographical and historical contexts. We critically scrutinise the iconic Silicon Valley along with other major innovative regions/nations, and investigate the key role of universities and finance in driving innovation and entrepreneurship.', 'GGR300H1 (2014-15)', 3, null::jsonb),
    ('GGR252H1', 'Marketing Geography', '24L/4T', 'Geography matters in the success of both public and private sector organizations. Using mostly retail examples contemporary location problems are addressed. The geographies of demand and supply are analyzed and trade area and site selection techniques are applied. The relevance of the planning context and utility of geovisualization techniques such as GIS are also briefly considered.', 'GGR252H5', 3, null::jsonb),
    ('GGR254H1', 'Geography USA', '24L', 'After a short historical overview of the making of America, this course focuses on contemporary issues in American society, economy, politics, race, regional distinctions and disparities, urban development.', null, 3, null::jsonb),
    ('GGR259H1', 'Urban Growth and Decline', '24L', 'The growth and decline of cities have been and continue to be preoccupations of scholars and practitioners alike. This course is an introduction to the causes and consequences of urban growth and decline at the neighbourhood, municipal, and regional levels. Special attention will be paid to North American cities, but others outside of that sphere will be discussed as well. Concepts and topics will include a consideration of the following: rural to urban migration; industrialization and deindustrialization; urban renewal; suburbanization; austerity and neoliberalism; racial avoidance and discrimination; gentrification; and capital switching and uneven development.', null, 3, null::jsonb),
    ('GGR270H1', 'Introductory Analytical Methods', '24L/12T', 'Theory and practical application of elementary quantitative techniques in geography emphasizing descriptive, inferential and spatial statistical analysis, probability, and sampling.', 'ECO220Y1/  ECO227Y1/  EEB225H1/  GGR270Y1/  LIN305H1/  POL232H1/  PSY201H1/  SOC202H1/  STA220H1/  STA248H1/  STA261H1', 5, null::jsonb),
    ('GGR271H1', 'Social Research Methods', '24L', 'Practical course on field methods designed to enable students to carry out their own research projects. Behavioural observation, interviewing, questionnaire design, sampling theory, content analysis of written and graphic material, data coding and focus groups.', 'SOC200H1/  SOC204H1/  CRI350H1/  ENV223H1', 3, null::jsonb),
    ('GGR272H1', 'Geographic Information and Mapping I', '24L/24P', 'Introduction to digital mapping and spatial analysis using geographic information systems (GIS). Students learn how to use GIS software to find, edit, analyze and map geographic data to create their own maps, analyze geographic problems and use techniques that can be applied to a variety of subject areas.', 'GGRB30H3,  GGR278H5', 5, null::jsonb),
    ('GGR273H1', 'Geographic Information and Mapping II', '24L/24P', 'Builds on  GGR272H1 by providing students with practical spatial analysis methods and the underlying theory needed to understand how to approach various geographic problems using geographic information system (GIS) software and a variety of data types and sources.', 'GGRB32H3', 5, '{"operator": "AND", "items": ["GGR272H1"]}'::jsonb),
    ('GGR274H1', 'Introductory Computation and Data Science for the Social Sciences', '24L/12T', 'Social scientists are increasingly working with big and complex datasets that contain spatial, group-level, and individual-level dimensions to answer questions about society. In this course, students will develop introductory programming knowledge and data acumen in order to create and run computer programs to explore where, when, and why social processes occur, drawing on theories from geography, linguistics, sociology, anthropology, economics, political science, and psychology. Instruction will focus on applying current data analysis libraries, communicating and translating data science methods to both researchers and the public, distinguishing causation from correlation and coincidence, and negotiating tradeoffs between different computational and statistical approaches.', 'CSC111H1,  CSC148H1,  STA130H1,  STA238H1,  STA248H1,  STA261H1,  EEB125H1', 5, null::jsonb),
    ('GGR299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GGR299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GGR314H1', 'Global Warming', '30L/6T', 'A comprehensive examination of the greenhouse warming problem, beginning with economic, carbon cycle, and climate model projections; impacts on and adaptive responses of agriculture, forests, fisheries, and water resources; options and policies to reduce greenhouse gas emissions.', 'GGR377H5', 5, null::jsonb),
    ('GGR315H1', 'Environmental Remote Sensing', '24L/24P', 'Principles of optical, active and passive microwave remote sensing; satellite orbit and sensor characteristics; image processing and analysis techniques and software; and environmental remote sensing applications.', 'GGR337H1,  GGR337H5', 5, null::jsonb),
    ('GGR320H1', 'Geographies of Transnationalism, Migration, and Gender', '24L', 'This course examines recent changes in global migration processes. Specifically, the course addresses the transnationalization and feminization of migrant populations and various segments of the global labor force. The coursework focuses on analyzing classical paradigms in migration studies, as well as emerging theoretical approaches to gender and migration. In addition, it traces the shifting empirical trends in gendered employment and mobility patterns. It uses in-depth case study material to query the frameworks employed in migration studies and to understand the grounded implications of gendered migration. It pays particular attention to the interventions made by feminist geographers in debates about work, migration, place, and space.', null, 3, null::jsonb),
    ('GGR323H1', 'Commons, Commoning and Nature', '24L', 'This course examines the role of commons and commoning practices in rethinking how we share natural resources, nurture life-in-common and build more meaningful worlds. Topics covered include: the political and economic history of the commons and their erasure; social and environmental movements; geographies of commons governance; urban commons; more-than-human commons; and post-capitalist alternatives to address ecosystem emergencies. The course draws from Institutional and complexity theory; feminist decolonial theory; Indigenous philosophy; Black feminist thought; new materialism and posthumanism to understand the challenges and possibilities of reviving commons and commoning practices.', 'GGR387H1 (Special Topics in Environmental Geography: Commons, Commoning and Ecologies of Care in a Post-Covid World), offered in Winter 2021', 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('GGR324H1', 'Spatial Political Economy', '24L', 'This course aims to explore how economic agents act and interact in space and how this creates subdivisions within the global, national and regional political economy. In a largely conceptual and interdisciplinary manner, the course investigates the role of institutions in the relational economy and the spatial construction of the political economy. Institutions are viewed as formal or informal stabilizations of economic interaction. Questions which guide the analysis are related to how institutions are established, how they evolve, how they impact economic action, and how they are changed through political and economic action at different spatial scales. Through this, the course introduces a relational and spatial perspective to the analysis of economic action and institutions. This perspective is based on the assumption that economic action is situated in socio-institutional contexts, evolves along particular paths and, at the same time, remains fundamentally contingent. Topics to be discussed include the social construction of economic space, industrial organization and location, the establishment and maintenance of economic networks, as well as processes of firm formation, learning and knowledge creation.', 'POL371H1', 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('GGR326H1', 'Remaking the Global Economy', '24L', 'Examines links between global economic integration and geographically uneven economic development. Focuses on debates and empirical studies on global production networks (GPNs), and associated issues such as offshoring, outsourcing, and upgrading. Blends analysis of both theory and practice of business firms and regional development. Seeks to develop an in-depth understanding of the key actors driving contemporary global economic transformation, within the ''transnational space'' constituted and structured by transnational firms, state institutions, and ideologies.', 'GGR300H1 (Special Topics in Geography I: Remaking the Global Economy), offered in Winter 2014', 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('GGR327H1', 'Geography and Gender', '24L', 'Introduction to the work of feminist geographers. The course will explore the relationship between gender and space, emphasizing spatial cognition, architecture, and layout of the city.', 'GGR313H5', 3, null::jsonb),
    ('GGR328H1', 'Labour Geographies', '24L', 'Explores changes in the nature of work and the structure and geography of labour markets. Topics will include globalization, lean production, flexibility and risk, industrial relations, workfare, the body at work, and gender and work.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"credits": 1.0, "department": "Geography"}]}'::jsonb),
    ('GGR329H1', 'The Global Food System', '24L', 'Explores the changing global geographies of food by tracing international movements of food through both mainstream and ''alternative'' supply chains. The implications for sustainability, food security, community autonomy and health are investigated.', 'GGR287H5', 3, null::jsonb),
    ('GGR332H1', 'Social Geographies of Climate Change', '24L', 'Analyses the social and behavioural geographies of climate change, including: climate change communication (how we interpret and communicate climate science); climate change prevention strategies, from the macro to micro scale; and possibilities for climate change adaptation.', 'GGR387H1 (Special Topics in Environmental Geography: The Social Geographies of Climate Change), offered in Winter 2020', 3, null::jsonb),
    ('GGR334H1', 'Water Resource Management', '24L', 'Managing demand and supply; linkages between water quality and human health. Case studies from the industrial world and from developing countries, rural and urban. Implications of population growth and climate change for water resource management.', 'GGR288H5', 3, null::jsonb),
    ('GGR336H1', 'Urban Historical Geography of North America', '24L', 'This course explores the emergence and reproduction of class and racial social spaces, the development of new economic spaces, and the growing importance of the reform and planning movements. Emphasis is on metropolitan development between 1850 and 1950.', null, 3, null::jsonb),
    ('GGR338H1', 'Social Transformation and Environment in the Majority World', '24L', 'This course draws upon a number of geographical theories, debates and case studies to explore the geographical implications of an increasingly interconnected global capitalist economy for interactions among the people and environments in places in the ''majority world''. Situated within the context of climate change this course examines the evolution of discourses of ''development'' and their relationship to western (Anglo-American) racialized notions of progress and modernity.', null, 3, null::jsonb),
    ('GGR339H1', 'Urban Political Geographies', '24L', 'Investigates North American urban political geography, exploring conflicts over immigration, environment, gentrification, homelessness, labour market restructuring, ''race'' and racism, urban sprawl, nature and environment, gender, sexuality, security, and segregation. Explores competing visions of city life and claims on urban space. The course investigates how these struggles connect to economic, social and environmental politics at larger spatial scales, and considers different theoretical frameworks that geographers have developed to make sense of both the persistence of old problems and the emergence of new ones. Potential field trip, cost: approximately $21.', 'GGR349H5', 3, null::jsonb),
    ('GGR340H1', 'Health Geography', '24L', 'An exploration of the aspects of health in which place or location matters. Particular attention will be paid to the role of environments (physical, social, etc.) in explaining differences in health between places, the structuring of health-related behaviour in place, and the development of health policy for places.', null, 3, '{"operator": "OR", "items": ["GGR270H1", {"operator": "AND", "items": ["STA220H1", "HST250H1"]}]}'::jsonb),
    ('GGR341H1', 'The Changing Geography of Latin America', '24L', 'Seeks to develop a general understanding of present-day Latin America by focusing on human-environment interactions, past and present. Case studies are used to understand the diversity of Latin American landscapes (physical and cultural), and how they are changing within the context of globalization.', null, 3, null::jsonb),
    ('GGR342H1', 'The Changing Geography of Southeast Asia', '24L', 'Examines changes in the social, political and economic geography of Southeast Asian countries. Examples drawn from Thailand, Singapore, Indonesia, Vietnam and the Philippines as these emerging newly industrialized countries enter the 21st century. Emphasis on political-economy, urbanization and environment since 1950.', null, 3, null::jsonb),
    ('GGR343H1', 'The Changing Geography of China', '36L', 'The evolving social, political and economic landscape of China. Focus on development strategies and their effects on agriculture, industry, urbanization, city planning and the environment since 1949. Special attention paid to the interconnected development trajectories shaping urban and rural areas, together with the complex interactions between the built and social environments.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('GGR344H1', 'Institutions and Governance: Germany in Comparative Perspective', '24L', 'The goal of this course is to explore the structure and geography of the German political economy in the context of economic globalization by systematically comparing institutional conditions with those in other countries. This perspective enables us to identify different capitalist systems and characterize Germany as a more socially balanced economic governance model compared with market-liberal systems in the US, UK and Canada. Drawing on the varieties-of-capitalism and other approaches, the main themes in the course address the institutional conditions for development. In a comparative perspective, the course explores topics, such as the role of collective agents and collective bargaining, corporate governance and finance, inter-firm co-operation and regional networks, social security systems, and population structure and immigration. To better understand the current challenges to the German governance model, the institutional opportunities and limitations are investigated under which different regional economies develop in unequal ways.', 'POL372H1', 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('GGR347H1', 'Energy Efficiency and Beyond', '24L/6T', 'Examines the options available for dramatically reducing our use of primary energy with no reduction in meaningful energy services, through more efficient use of energy at the scale of energy-using devices and of entire energy systems. Topics covered include energy use in buildings, transportation, industry, and agriculture. Offered alternate years from  GGR348H1.', 'GGR333H1,  JGE347H1', 5, null::jsonb),
    ('GGR348H1', 'Carbon-Free Energy Systems', '24L/6T', 'Examines the options available for providing energy from carbon-free energy sources: solar, wind, biomass, nuclear, and fossil fuels with capture and sequestration of CO2. The hydrogen economy is also discussed. Offered alternate years from  GGR347H1.', 'GGR333H1,  JGE348H1', 5, null::jsonb),
    ('GGR349H1', 'Managing Urban Natures', '24L', 'Recent calls to action by the Intergovernmental Panel on Climate Change and the World Wildlife Fund indicate we are at a crossroads in responding to accelerating global warming and biodiversity loss. Cities are often at the forefront of these transformations, both in feeling their effects but also initiating responses. How might we reimagine our cities in a way that promotes thriving and equitable ecosystems? What tools exist in the policy landscape to initiate needed changes? What innovative responses are emerging to confront the challenges of increased flooding, rising temperatures, habitat fragmentation, and food insecurity? How might we reimagine an urban commons? With a primary focus on Canadian cities, in this course we explore the ways divergent conceptualizations of urban-nature have informed policies and practices drawing largely from critical, political ecology, and Indigenous perspectives; the policy landscape that informs current urban planning; and new and innovative approaches that help us to reshape and reimagine our relationships to urban nature, including initiatives led by municipalities, non-government organizations and citizens groups.', 'GGR300H1 (Topics: Managing Urban Natures), offered in Fall 2017', 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('GGR353H1', 'Planning for Local and Regional Economic Development', '24L', 'Years of post-War socioeconomic convergence notwithstanding, scholars and policymakers at all spatial scales have noted a relatively recent and alarming trend toward rapidly accelerating socioeconomic polarization. Rich nations are diverging from poorer ones on myriad metrics as are rich and poor localities. In response, social scientists generally, and economic development planners in particular, have been attempting to understand what lies behind this trend and, more importantly, to conceive of methods of intervening in the market to produce more sustainable outcomes while also addressing the effects of spatially uneven development. This course will introduce students to the study and practice of planning for local and regional development, largely and the local and regional scales.', 'GGR389H1 (Planning for Community Economic Development) offered in Fall 2024', 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('GGR354H1', 'Infrastructure', '24L', 'Infrastructure is the term that describes the transportation systems, sewers, pipes, and power lines that provide urban dwellers with necessary public services. In recent years, billions of dollars of public money have been spent upgrading existing infrastructure, and planning and delivering new facilities. Infrastructure has many impacts on the way that people in cities live. The way that infrastructure systems are planned, financed, and distributed impact on environmental sustainability, job creation, social equity, economic development, and urban livability. Moreover, infrastructure has the potential to both serve existing populations, and shape the way that future communities are built. Through lectures, discussions, workshops, readings of scholarly articles and case studies, the course will aim to engage students in the key topics and debates related to the provision of urban infrastructure. Topics to be covered will include: project planning, causes and cures for cost overruns, funding models, financing mechanisms such as public-private partnerships, and the politics of facility planning and management.', 'GGR300H1 (Topics: Infrastructure), offered in Summer 2017', 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('GGR357H1', 'Housing and Community Development', '24L', 'Focuses on the importance of adequate housing and quality neighbourhoods. It roots theoretical explanations and policy debates in realities using Canada and Toronto as examples. Topics covered include the evolution of public policies relating to social housing, rental housing, homeownership, neighborhoods, and homelessness.', null, 3, null::jsonb),
    ('GGR359H1', 'Comparative Urban Policy', '24L', 'This course considers urban public policy. Urban policy is not natural or inevitable response to urban problems. It is actively produced (and contested) by an array of voices, institutions, and social forces. Actualized urban policies are thus best understood and evaluated as products of these influences. The first half of the course will cover broad theoretical matters pertaining to the production of urban policy. The second half of the course will focus more intensively on one problem—urban decline—and explore the actualized approaches that have been brought to bear to manage it.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"credits": 1.0, "department": "Geography"}]}'::jsonb),
    ('GGR360H1', 'Culture, History, and Landscape', '24L', 'The history of approaches to the idea of landscape. A consideration of the origins and uses of the term in geographical inquiry will be followed by a series of case studies, global in scope, from the Early Modern period to the present. Emphasis will be placed on the representational and lived aspects of landscapes, as well as struggles over their definition, interpretation, and use.', null, 1, null::jsonb),
    ('GGR363H1', 'Critical Geographies: An Introduction to Radical Ideas on Space, Society and Culture', '36L', 'Introduces a diversity of critical perspectives for geographers and others, including anarchism, Marxism, feminism, sexual politics, postcolonialism, anti-imperialism and anti-racism. In so doing it illustrates how such radical ideas about space, society and culture have contributed to our political thought and action.', null, 3, null::jsonb),
    ('GGR372H1', 'GIS for Public Health', '24L/12P', 'The goal of this course is to leave students with appreciation of the power of Geographic Information Systems (GIS) to explore and analyze spatial health and medical data. The course will focus on organizing health data in a GIS, clustering detection methods, and basic spatial statistics. Other topics like agent-based models and visualization techniques will be touched upon. Lab work will provide hands on experience with example data, leaving students with a firm grasp of contemporary health and medical problems and a skill set of spatial analytical methods that can be used to solve them.', 'GGR335H5', 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, "GGR272H1"]}'::jsonb),
    ('GGR373H1', 'Advanced Geographic Information Systems', '24L/24P', 'Advanced theory, techniques, and applications in geographic information systems (GIS), including interpolation, geostatistics, modeling, and raster and vector analysis. GIS project design and implementation.', null, 5, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, "GGR273H1"]}'::jsonb),
    ('GGR374H1', 'Urban Dynamics', '24L', 'This course will focus on the social and economic repercussions associated with the formation and evolution of polynuclear urban regions in response to global economic restructuring. Foci will include the importance of knowledge and innovation in the process of economic development, social and economic polarization at multiple spatial scales, planning interventions to address these polarities, and strategies and tactics in the promotion of more sustainable urban-centred regional economies.', null, 3, null::jsonb),
    ('GGR375H1', 'Introduction to Programming in GIS', '24L', 'This course will introduce students to the fundamentals of programming, followed by an applied focus on using these skills in geographic information systems. Students will learn how to programmatically edit spatial data, automate common processes, and conduct complex spatial analyses. The course will emphasize open-source software that enriches geospatial data analysis alongside the data processing and analytical capabilities of existing GIS software. Classroom time will be a mix of short lectures and laboratory exercises.', 'GGR386H1 (Special Topics in Geographic Information Systems: Programming in GIS), offered in Fall 2019 and Winter 2021', 5, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["GGR272H1", "GGR274H1"]}]}'::jsonb),
    ('GGR376H1', 'Geovisualization', '24L', 'Visualizing geographic information forms an important step in aiding visual thinking, generating hypotheses, and communicating findings relating to places. Geovisualization not only involves the display of spatial data through static maps, but also the process of creating 3D, dynamic, or interactive visualizations for data exploration, insights, and analysis. This course will introduce the foundations and capabilities of geovisualization for scientific communication, and students will learn techniques and tools to develop and critically appraise a range of geovisual outputs.', 'GGR386H1 (Special Topic: Geovisualization), offered in Fall 2022', 5, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["GGR272H1", "GGR274H1"]}]}'::jsonb),
    ('GGR377H1', 'Introduction to Urban Data Analytics', '24L/12P', 'This course draws on census and economic data collection, processing, and analysis to teach written and visual storytelling about cities with data and maps, while exploring the uses of real-time data and analytics to solve urban problems. It provides a socio-economic and political context for the use of big data and the smart cities movement, focusing on data ethics and governance.', null, 3, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('GGR382H1', 'Field Course in Human Geography', null, 'Introduction to field studies in human geography. The course includes exercises and a project during a one-week field study in late August or early September, some preparation during the preceding summer and complementary practical work and/or seminars during the Fall Term. Each student is required to pay the costs of their transportation and accommodation (field trip costs: $600). Students must submit an application directly to the Department in the spring (see the Geography website for details in March). Course may be limited by size. Not eligible for CR/NCR option.', 'GGR389H5', 3, null::jsonb),
    ('GGR385H1', 'Special Topics in Geography', '24L', 'Content in any given year varies by instructor. Students must meet the prerequisites set by the department (see the Geography website for details in May). The program in which this course can be used depends on its content.', null, null, null::jsonb),
    ('GGR386H1', 'Special Topics in Geographic Information Systems', '24L', 'Content in any given year varies by instructor. Students must meet the prerequisites set by the department (see the Geography website for details in May). Can be used towards GIS, Human Geography, and Environmental Geography programs.', null, null, '{"operator": "AND", "items": ["GGR272H1"]}'::jsonb),
    ('GGR387H1', 'Special Topics in Environmental Geography', '24L', 'Content in any given year varies by instructor. Students must meet the prerequisites set by the department (see the Geography website for details in May). Can be used towards Environmental Geography and Human Geography programs.', null, 3, null::jsonb),
    ('GGR388H1', 'Special Topics in Physical & Environmental Geography', '24L', 'Content in any given year varies by instructor. Students must meet the prerequisites set by the department (see the Geography website for details in May). Can be used towards Physical & Environmental Geography and Environmental Geography programs.', null, 5, null::jsonb),
    ('GGR389H1', 'Special Topics in Human Geography', '24L', 'Content in any given year varies by instructor. Students must meet the prerequisites set by the department (see the Geography website for details in May). Can be used towards Human Geography programs.', null, 3, null::jsonb),
    ('GGR390H1', 'Field Methods', null, 'Introduction to field methods in geomorphology, vegetation mapping/analysis, soils, hydrology, and climatology. The course includes exercises and a group project during a one-week field camp, a little preparation during the preceding summer, and complementary practical work and/or seminars during the Fall Term. Each student is required to pay the costs of their transportation and accommodation (field trip costs: approximately $495). This course meets the field requirement for Physical & Environmental Geography programs. The field camp normally runs for one week at the end of August. Students must submit an application directly to the Department in the spring (see the Geography website for details in March). Course may be limited by size. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["JEG100H1", "GGR201H1", "GGR203H1", "GGR205H1", "GGR206H1", "GGR305H1", "ENV234H1"]}]}'::jsonb),
    ('GGR398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GGR398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GGR399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GGR399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GGR400H1', 'Special Topics in Geography I', '24S', 'Content in any given year depends on instructor. The program in which this course can be used depends on its context. Consult Departmental Office in April.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR401H1', 'Special Topics in Geography II', null, 'Content in any given year depends on instructor. The program in which this course can be used depends on its context. Consult Departmental Office in April.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR413H1', 'Watershed Hydroecology', '24L', 'Modern developments in hydrology and ecology, including form and process models, interactions of hydrology, ecology and geomorphology; the course emphasizes the use of computer simulation models of drainage basin processes.', null, 5, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR415H1', 'Advanced Remote Sensing', '18L/8T/4P/2S', 'Building on  GGR315H1 (formerly  GGR337H1) Environmental Remote Sensing with advanced theories and techniques for land cover mapping, vegetation biophysical and biochemical parameter retrievals, optical and thermal remote sensing of urban environment, and application of satellite remote sensing to terrestrial water and carbon cycle estimation. Basic radiative transfer theories as applied to vegetation will be given in some detail as the basis for various remote sensing applications. Optical instruments for measuring vegetation structural parameters will be demonstrated in the field.', 'GGR414H1', 5, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["GGR315H1", "GGR337H1"]}]}'::jsonb),
    ('GGR416H1', 'Environmental Impact Assessment', '24L/4T', 'Environmental impact assessment (EIA) has emerged as a key component of environmental planning and management. EIAs are planning tools to predict and assess the potential costs and benefits of proposed projects, policies, and plans and avoid or mitigate the adverse impacts of these proposals. This course focuses on the origins, principles, scope, and purpose of EIA from theoretical and practical perspectives, emphasizing the Canadian context. We will also explore the various components of EIAs and critically evaluate techniques to assess, predict, and mitigate impacts. Through course readings, in-class activities, and assignments, we will engage critiques of EIAs, particularly as they relate to considerations of climate change, sustainability, long-term monitoring, meaningful public engagement, indigenous people''s rights, dispossession and resettlement, and environmental justice. Case studies will allow students to learn about current practices in EIA and develop skills to examine and improve EIA processes.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 2.0, "department": "GGR"}, "GGR270H1", "GGR271H1"]}'::jsonb),
    ('GGR418H1', 'Geographies of Extraction', '24S', 'Examines political aspects of the appropriation of natural resources, including policy and regulation, environmental impacts, and social justice. Emphasis is placed on reading contemporary literature on the politics of resource access and control from geography and other social science disciplines.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "GGR223H1"]}'::jsonb),
    ('GGR419H1', 'Environmental Justice', '24S', 'Examines how environmental problems affect people, communities and societies differentially and how marginalized communities and people often bear the brunt of environmental costs, while contributing little to their creation. It uses readings and case studies from across the globe to address the production of environmental injustice and the struggle for environmental justice.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR421H1', 'Histories of Geographical Thought', '24S', 'The history of geography as an intellectual subject, focusing primarily on the modern period, and on the genealogies of central concepts. Disciplinary developments will be situated next to broader contexts, including imperialism and militarism, the relationship between culture and nature, and the shifting social role of the academy.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR424H1', 'Transportation Geography and Planning', '24L', 'Introductory overview of major issues in interurban and intraurban transportation at the local, national and international scale. Topics include urban transportation, land use patterns and the environment, causes of and cures for congestion, public transit, infrastructure finance, and transport planning and policy setting.', 'CITC18H3', 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["GGR124H1", "GGR217H1", "GGR221H1"]}]}'::jsonb),
    ('GGR429H1', 'Innovation and Governance', '24S', 'The course focuses on a broad range of topics related to innovation and governance, such as (i) technological change and its social and economic consequences, (ii) the spatial effects which result from this, and (iii) the necessities for economic policies at different territorial levels. Since international competitiveness of industrialized economies cannot be based on cost advantages alone, future growth in the knowledge-based economy will be increasingly associated with capabilities related to creativity, knowledge generation and innovation. As a consequence, questions regarding the performance in innovation and effectiveness of policy support become decisive at the firm level, regional level and national level. The first part of the course deals with conceptual foundations of innovation processes, such as evolutionary and institutional views of innovation. In the second part, national configurations of innovation processes are investigated. The third part deals with innovation at the subnational level, focusing on regional clustering, institution building, multilevel governance, and regionalized innovation systems.', 'POL408H1', 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR430H1', 'Geographies of Markets', '36S', 'Focuses on actually-existing markets and their geographically-mediated formation and assemblage. Explores how markets are produced, stabilized, reshaped and fall apart at multiple geographic scales. We examine issues such as the debates on states versus markets, embeddedness of markets, neoliberalism and moral justification of markets, varieties of capitalism, regionally variegated capitalism, post-socialist market transitions, and the dynamic evolution of market institutions and economic landscapes.', 'GGR400H1 (2013-14)', 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"credits": 1.0, "department": "Geography"}]}'::jsonb),
    ('GGR431H1', 'Regional Dynamics', '24L', 'Economic activity, and related indices of socioeconomic well-being and human capital, have always tended to concentrate in space, leaving specific regions to be classified as “creative”, “developed”, or “core” regions and others as “have-not”, “less-developed, “peripheral”, or “marginal” regions. As a result, regional economic change has been very difficult to fully explain (and certainly predict) using conventional (orthodox) theories and methods. This course examines the theoretical linkage between related trends in terms of globalization, vertical disintegration, specialization, innovation, and the locational behaviour of firms. We will focus on the seemingly counter-intuitive finding that regional economic change in a time of increasing global interdependence is increasingly dependent on the local context. Topics will include evolutionary economic geography, path dependence, economic clusters, learning regions, the role of institutions, knowledge spill-overs, and the geography of innovation, among others. We will see why the economic activity is becoming ever more concentrated in space even as it globalizes. The course makes extensive use of empirical case studies from around the globe.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["GGR221H1", "GGR251H1"]}]}'::jsonb),
    ('GGR432H1', 'China in the Global Political Economy', '24S', 'Set against the backdrop of the rise of China, and following the perspective of geographic political economy, this seminar course examines the interactions between and mutual transformations of the Chinese economy and the global economy. We will focus on the evolving political and institutional foundations of China''s post-Mao, hybrid, hierarchical market-authoritarian system. Key sectors – telecoms, Internet, semiconductor, and automobile – will be examined to understand the nuances of China''s integration into the global production through state-directed uneven domestic development, and in turn the challenges raised by escalating international conflicts.', 'GGR389H1 (Special Topic: China in the Global Political Economy), offered in Fall 2022', 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR433H1', 'Built Environment and Health', '36S', 'Linking across fields that include public health, geography and planning, this course examines the growing evidence and ways in which human health is affected by the design and development of the built environment in which we live, work and play. The course considers how various planning and development decisions impact population and individual health, particularly in relation to chronic diseases, injuries, and mental health. Potential of several local field trips (transportation costs: approximately $20).', 'GGR400H1 (Special Topics in Geography I: Built Environments & Health), offered in Winter 2013', 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR434H1', 'Building Community Resilience', '36S', 'Examines concepts of resilience as a way of building the capacity of communities to (a) respond to predicted disruptions/shocks associated with climate change, global pandemics, anticipated disruptions in global food supply, energy insecurity, and environmental degradation; and (b) nurture the development of alternative spaces that support the emergence of more life-sustaining structures and practices. Includes explicit attention to equity and public health, and explores issues such as: participatory governance of social-ecological systems, the nature of social change, complexity science, the role of social movements, indigenous and political ecology perspectives.', 'GGR400H1 (2011-12)', 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR437H1', 'Geographies of Waste', '36S', 'This seminar course examines how waste is made and how it circulates locally, regionally, and globally. It considers changing conceptions of ''waste'' and the wider systems that have shaped efforts to manage waste through a selection of historic and contemporary geographies of waste. We will examine waste as a resource (e.g., recycling, composting) and waste avoided (e.g., reuse, repair). Through case studies, we will analyze waste – including urban wastewater – in relation to policy and planning, political economy, forms of labour and infrastructure, and the social norms and values that have shaped people''s relationship to it.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR438H1', 'Environment and Development', '36S', 'Examines the implications of development – as an economic and social project – for how the environment is used, by whom, and to what ends. Draws on literatures in political ecology and critical development geography. Topics include: interpretations of scarcity and degradation, questions of consumption, and the greening of development. Examines expansion of and struggles over new forms of green infrastructure in urban and rural settings.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR456H1', 'Entanglements of Power: Race, Sexuality and the City', '24S', 'This course investigates the city as a space sculpted by particular configurations and relations of power, and productive of those forms. It considers shifting urban geographies of identity, economy and desire with a focus on race and racism, settler colonialism, empire, the laboring body, sexuality, and sexual identity. Course participants will engage a series of case studies of particular urban spaces and struggles, drawing on conceptual support from scholarship in urban geography, anti-colonial thought, political economy, black studies, feminist and queer theory, Indigenous and settler colonial studies, as well as literature and other artistic work.', 'GGR400H1 (Special Topics in Geography I: Entanglements of Power: Race, Sexuality and the City), offered in Fall 2018', 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR458H1', 'Selected Topics in Urban Geography', '24L', 'This course focuses on a special topic in urban geography and covers it with more depth than would otherwise be the case in a survey-oriented class. The aim is to utilize this single topic as a vehicle to understanding how urban geographical ideas are produced more widely. Check the department website for the theme (updated each year).', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR460H1', 'Global Cities, Urban Planning, Critical Theory', '36S', 'This seminar addresses the relationship between urbanization and global economic, political, cultural, social, demographic, technological and ecological dynamics. It does so with an emphasis on the contested legacies of city planning, urban design, architecture and urban political activism, by drawing on historical studies of global cities as well as critical-theoretical perspectives on the ''production of space''. While broaching the question what''s ''production of space'' got to do with social justice, we explore—with reference to pioneering thinkers in the fields of planning, architecture and critical theory—such concepts as radical planning, the urban revolution and the right to the city.', 'GGR400H1 (Topics: Planning and Global Cities), offered in Winter 2018', 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR462H1', 'GIS Research Project', '24L', 'Students work in groups to develop their own research project and then acquire, organize and analyze geographic data to complete it. Emphasis is placed on research design, project management and the application of GIS concepts and skills learned in previous courses to a practical problem.', null, 5, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "GGR373H1"]}'::jsonb),
    ('GGR472H1', 'Developing Web Maps', '24L', 'Explores the power of web mapping and CyberGIS, with a focus on hands-on learning and open source software. Students will learn about relevant software (exploring various APIs), data structures, methods, and cartographic and visualization techniques. Finally, students will work in groups to develop and deliver their own online web maps from scratch, on a topic of their choosing.', null, 5, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, "GGR272H1", {"operator": "OR", "items": ["GGR273H1", "GGR274H1"]}]}'::jsonb),
    ('GGR473H1', 'Geospatial Big Data', '24L', 'Advances in sensing and mobile technologies have contributed to the increasing availability of large volume georeferenced data such as geo-tagged social media content, GPS traces, and crowdsourced maps. While geospatial big data provide a major source for innovation and analysis, challenges relating to data handling, processing, and interpretation have simultaneously arisen. In this course, students will build a critical understanding of the evolution, potential, and biases of geospatial big data. Knowledge of geo-computational techniques to handle geospatial big data and perform meaningful analysis will also be developed and applied.', 'GGR401H1 (Special Topic: Geospatial Big Data), offered in Fall 2022', 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}, {"operator": "OR", "items": ["GGR272H1", "GGR274H1"]}]}'::jsonb),
    ('GGR482H1', 'Toronto Field Course', null, 'Examines the production of urban landscapes, built environments and social spaces in Toronto and surrounding areas through in-depth case studies. Coverage will vary some depending on instructor. The course consists of local field trips and in-class seminars and lectures. Students must submit an application directly to the Department in the spring (see the Geography website for details in March). Course may be limited by size. Not eligible for CR/NCR option. Field trip costs are normally low, but may go up to $153.', null, 3, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR491Y1', 'Research Project', null, 'Specially designed for students wishing to gain experience in conducting research in their area of specialization. Of particular value for geographers interested in graduate study, or positions in government, planning and consulting firms where research skills may be an asset. Students select a research problem and complete a project under the supervision of a faculty member. Enrolment requires written permission from a faculty supervisor and Associate Chair, Undergraduate; early discussion with a likely supervisor is encouraged. Enrolment may be completed at any time up to September; open to students in a Specialist or Major Program sponsored by the Department of Geography. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR492H1', 'Senior Practicum', null, 'Students design and implement an independent applied geography/planning project in consultation with an employer (paid or volunteer), who will act as their "client." Enrolment requires written permission from a staff supervisor and Associate Chair, Undergraduate. Only open to students who are enrolled in a Specialist or Major program sponsored by the Department of Geography. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GGR492Y1', 'Senior Practicum', null, 'Students design and implement an independent applied geography/planning/GIS project in consultation with an employer (paid or volunteer), who will act as their “client”. Enrolment required written permission from a staff supervisor and Associate Chair, Undergraduate. Only open to students who have completed 10.0 credits and who are enrolled in a Specialist, Major or GIS minor program sponsored by the Department of Geography. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('GGR493Y1', 'Geography Professional Experience', null, 'Undertake professional placement matching academic interests and career goals. Students meet regularly during the year in class to cover topics such as: reflective writing, project management, career planning, and the application of academic skills in professional contexts. Research project required that connects a topic related to placement with academic literatures. Normally, one day per week spent at placement site. For students in their final year of a Geography major or specialist program of study, or the GIS Minor. Satisfies program requirements based on placement. Students must submit an application directly to the Department in the spring (see the Geography website for details in March). Course may be limited by size. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 14.5, "department": null}]}'::jsonb),
    ('GGR496H1', 'Independent Research', null, 'Independent research extension to one of the courses already completed in Geographic Information Systems. Enrolment requires written permission from a faculty supervisor and Associate Chair, Undergraduate. Only open to students who are in Year 3 or higher and who are enrolled in the GIS program sponsored by the Department of Geography. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR497H1', 'Independent Research', null, 'Independent research extension to one of the courses already completed in Environmental Geography. Enrolment requires written permission from a faculty supervisor and Associate Chair, Undergraduate. Only open to students who are in Year 3 or higher and who are enrolled in a Specialist or Major program sponsored by the Department of Geography. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR498H1', 'Independent Research', null, 'Independent research extension to one of the courses already completed in Physical Geography. Enrolment requires written permission from a faculty supervisor and Associate Chair, Undergraduate. Only open to students in Year 3 or higher and who are enrolled in a Specialist or Major program sponsored by the Department of Geography. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GGR499H1', 'Independent Research', null, 'Independent research extension to one of the courses already completed in a social science or humanities branch of Geography. Enrolment requires written permission from a faculty supervisor and Associate Chair, Undergraduate. Only open to students in Year 3 or higher who are enrolled in a Specialist or Major program sponsored by the Department of Geography. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 10.0, "department": null}]}'::jsonb),
    ('GRK101H1', 'Introductory Ancient Greek I', '48S', 'An intensive introduction to Ancient Greek for students who have no knowledge of the language; preparation for the reading of Ancient Greek literature.', 'GRK100Y1. Students who have studied Ancient Greek previously must obtain permission from the Undergraduate Coordinator before enrolling.', 1, null::jsonb),
    ('GRK102H1', 'Introductory Ancient Greek II', '48S', 'A continuation of the intensive introduction to Ancient Greek in GRK 101H1. Also appropriate for students who have some training in Ancient Greek, but have not completed a whole credit course at University or a final-year (Grade 12) course in secondary school.', 'GRK100Y1', 1, '{"operator": "AND", "items": ["GRK101H1"]}'::jsonb),
    ('GRK201H1', 'Intermediate Ancient Greek I', '48S', 'Reading of selections of Ancient Greek prose works with systematic language study.', null, 1, '{"operator": "AND", "items": [{"operator": "OR", "items": ["GRK100Y1", "GRK102H1"]}]}'::jsonb),
    ('GRK202H1', 'Intermediate Ancient Greek II', '48S', 'Continued language training with readings in Ancient Greek prose and verse.', null, 1, '{"operator": "AND", "items": ["GRK201H1"]}'::jsonb),
    ('GRK340H1', 'Greek Philosophy I', '36S', 'Readings from one or more philosophical texts.', null, 1, '{"operator": "AND", "items": ["GRK202H1"]}'::jsonb),
    ('GRK341H1', 'Greek Historians I', '36S', 'Readings from one or more Greek Historians.', null, 1, '{"operator": "AND", "items": ["GRK202H1"]}'::jsonb),
    ('GRK343H1', 'Greek Prose Authors I', '36S', 'Readings from Greek prose authors (e.g., biography, novels, essays, texts in koine).', null, 1, '{"operator": "AND", "items": ["GRK202H1"]}'::jsonb),
    ('GRK350H1', 'Greek Epic I', '36S', 'Readings from Greek epics, including Homer.', null, 1, '{"operator": "AND", "items": ["GRK202H1"]}'::jsonb),
    ('GRK351H1', 'Greek Drama I', '36S', 'Readings from Greek tragedy and/or comedy.', null, 1, '{"operator": "AND", "items": ["GRK202H1"]}'::jsonb),
    ('GRK353H1', 'Greek Verse Authors I', '36S', 'Readings from Greek verse (e.g., elegy, iambics, lyric).', null, 1, '{"operator": "AND", "items": ["GRK202H1"]}'::jsonb),
    ('GRK354H1', 'Greek of Classical Athens I', '36S', 'Readings from one or more Greek texts, in prose or poetry, from Athens of the 5th-4th centuries BCE.', null, 1, '{"operator": "AND", "items": ["GRK202H1"]}'::jsonb),
    ('GRK355H1', 'Post-Classical Greek I', '36S', 'Readings from one or more Greek texts, in prose or poetry, from the Hellenistic and/or Roman Period.', null, 1, '{"operator": "AND", "items": ["GRK202H1"]}'::jsonb),
    ('GRK428H1', 'Independent Studies', null, 'Independent Studies. Not eligible for CR/NCR option.', 'GRK428Y1', 1, null::jsonb),
    ('GRK429H1', 'Independent Studies', null, 'Independent Studies. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('GRK440H1', 'Greek Philosophy II', '48S', 'Advanced readings from one or more philosophical texts.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "GRK"}]}'::jsonb),
    ('GRK441H1', 'Greek Historians II', '48S', 'Advanced readings from one or more Greek historians.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "GRK"}]}'::jsonb),
    ('GRK443H1', 'Greek Prose Authors II', '48S', 'Advanced readings from Greek prose authors (e.g., biography, novels, essays, texts in koine).', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "GRK"}]}'::jsonb),
    ('GRK450H1', 'Greek Epic II', '48S', 'Advanced readings from Greek epics, including Homer.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "GRK"}]}'::jsonb),
    ('GRK451H1', 'Greek Drama II', '48S', 'Advanced readings from Greek tragedy and/or comedy.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "GRK"}]}'::jsonb),
    ('GRK453H1', 'Greek Verse Authors II', '48S', 'Advanced readings from Greek verse (e.g., elegy, iambic, lyric).', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "GRK"}]}'::jsonb),
    ('GRK454H1', 'Greek of Classical Athens II', '48S', 'Advanced readings from one or more Greek texts, in prose or poetry, from Athens of the 5th-4th centuries BCE.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "GRK"}]}'::jsonb),
    ('GRK455H1', 'Post-Classical Greek II', '48S', 'Advanced readings from one or more Greek texts, in prose or poetry, from the Hellenistic and/or Roman Period.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": "GRK"}]}'::jsonb),
    ('HIS100Y1', 'History of the Arctic', '48L/20T', 'People have made the Arctic home for millennia, creating circumpolar cultures in its challenging climate. This course compares and examines connections in the contested polar region through several themes: cultures in contact, trade and exploration, environment, crime and punishment, and defense and sovereignty.', 'HIS101Y1,  HIS102Y1,  HIS103Y1,  HIS106Y1,  HIS107Y1,  HIS108Y1,  HIS109Y1,  HIS110Y1', 3, null::jsonb),
    ('HIS101Y1', 'Histories of Violence', '48L/20T', 'Ranging widely chronologically and geographically, this course explores the phenomenon of violence in history. It examines the role and meanings of violence in particular societies (such as ancient Greece and samurai Japan), the ideological foundations and use of violence in the clash of cultures (as in slavery, holy wars, colonization, and genocide), and the effects and memorialization of violence.', 'HIS100Y1,  HIS102Y1,  HIS103Y1,  HIS106Y1,  HIS107Y1,  HIS108Y1,  HIS109Y1,  HIS110Y1', 2, null::jsonb),
    ('HIS102Y1', 'Empires, Encounters and Exchanges', '48L/20T', 'Can we speak of “international relations” before the modern concept of nation-states was established? What forms did globalization take in the pre-modern era? How did early global exchange shape our world today? Students in this course study interactions among peoples, empires, and cultures, in multiple regions of the world (specific areas and time periods will change depending on the professors teaching in any given year). Topics include the impact of new goods and technologies; dissemination of ideas and religions; voyages of migration and exploration; and episodes of conquest and colonization. Analysis of primary sources and intensive focus on becoming strong writers.', 'HIS100Y1,  HIS101Y1,  HIS103Y1,  HIS106Y1,  HIS107Y1,  HIS108Y1,  HIS109Y1,  HIS110Y1,  HISA04H3/  HISA05H3', 2, null::jsonb),
    ('HIS103Y1', 'Strategy and Statecraft: War, Diplomacy, and the Development of the International System, 1600–1945', '48L/20T', 'This course explores the history of the international state system, encouraging students to consider how this system has been constantly adapting and evolving for hundreds of years as states compete for power. It examines how wars between European states, along with diplomacy, empire-building, and the quest for wealth, led—unintentionally in many ways—to a broader, international system not confined only to European “great powers.” Students will study themes such as strategy and war, empire and imperialism, and trade, diplomacy, and state-building to understand the rise and fall of major states and empires over the centuries. Key events include the Thirty Years War in Europe; the global implications of the Seven Years War and Napoleonic Wars; and the roles of non-European regions like China, India, Japan, and the United States in the 18th and 19th centuries. The course also considers the effects of imperial competition in Africa and Asia, both for the imperial powers and the peoples and states of those continents; the diplomacy and competition that led to the First World War; and the global impact of the Second World War, with the rise of “superpowers” and the collapse of the European and Japanese empires.', 'HIS100Y1,  HIS101Y1,  HIS102Y1,  HIS106Y1,  HIS107Y1,  HIS108Y1,  HIS109Y1,  HIS110Y1', 3, null::jsonb),
    ('HIS106Y1', 'The African Diaspora in the Americas, 1492-1804', '48L/20T', 'This course introduces the history of the African Diaspora in the Americas, from 1492-1804. Lectures and readings will draw from primary sources and historical scholarship to focus on a range of topics, including slavery and the slave trade, race relations, gender and sexuality, religious and cultural practices, and liberation struggles.', 'HIS100Y1,  HIS101Y1,  HIS102Y1,  HIS103Y1,  HIS107Y1,  HIS108Y1,  HIS109Y1,  HIS110Y1', 3, null::jsonb),
    ('HIS107Y1', 'Approaches to East Asian History', '48L/20T', 'This course draws on the history of China, Korea and Japan between 1600 to 1950 to explore historical issues of gender, nationalism, war and relations with the West.', 'HIS100Y1,  HIS101Y1,  HIS102Y1,  HIS103Y1,  HIS106Y1,  HIS108Y1,  HIS109Y1,  HIS110Y1,  HIS284H5/ EAS204Y1', 3, null::jsonb),
    ('HIS108Y1', 'What is History?', '48L/20T', 'This course offers an introduction to history as a discipline - to the history of the discipline itself, to the questions, categories, and methodologies that constitute it, to the ways these interrogations and methods have evolved in varied times and places, and to the methodologies students need to acquire to engage in historical inquiry and writing. The course will be part methodological workshop, part epistemological reflection. Designed for any students interested in the study of the past or considering the History major.', 'HIS100Y1,  HIS101Y1,  HIS102Y1,  HIS103Y1,  HIS106Y1,  HIS107Y1,  HIS109Y1,  HIS110Y1', 3, null::jsonb),
    ('HIS109Y1', 'The Development of European Civilization, 1350-1945', '48L/20T', 'The shape of traditional society; the forces at work on the social, political, economic, cultural and intellectual structures of Western Europe since the high Middle Ages: the Structure of Traditional Society; the First Period of Challenges, 1350-1650; the Second Period of Challenges, 1650-1815; Confidence, Stability and Progress, 1815-1914; the Collapse of the Old Order and the Condition of Modern Europe, 1914-1945.', 'HIS100Y1,  HIS101Y1,  HIS102Y1,  HIS103Y1,  HIS106Y1,  HIS107Y1,  HIS108Y1,  HIS110Y1', 3, null::jsonb),
    ('HIS110Y1', 'History of the Indian Ocean World', '48L/20T', 'This course introduces you to the connected and interdependent world people who lived between the present day cities of Dakar, in West Africa, and Jakarta, in Indonesia, from about 1000 to the present. We explore in this class the three "C"s which have linked human experience in Africa and Asia via routes which connected the Indian Ocean World: Connectedness, Contingency, and Cosmopolitanism. We study how people who lived more than a thousand years before our time transported ideas, products, and scripts by land and sea via routes that connected large parts of Africa, Central & South Asia, and East and Southeast Asia, and their histories. The land and sea routes connected these communities and the cosmopolitan outlook of the hosts provided the contingent conditions for a Buddhist monks to travel from all over China to Southern and Southeast Asia; Muslim scholars to travel from West Africa to Indonesia; and merchants and writers to move within these worlds. Human migration, economic trade, and religious conversion had linked the lands and the seas, making it possible for our imams, merchants, monks, and servants to traverse these territories, across the Africa and Asia. This vibrant and wealthy world of African and Asian thinkers, merchants, leaders, and communities became the envy of the world, and as late as the seventeenth century, these crazy rich Africans and Asians dominated the world as it was known. We''ll see how history is contingent--and that human migration, economic exploitation, lack of reciprocity, and legacies of European colonial racism have disrupted the cosmopolitan worlds of the Indian Ocean. The world is different today, but more than three quarters of the human population still live in Africa and Asia--see the richness of their worlds as it was for thousands of years, and what will be left for the people of this world as climate change makes the seas rise.', 'HIS100Y1,  HIS101Y1,  HIS102Y1,  HIS103Y1,  HIS106Y1,  HIS107Y1,  HIS108Y1,  HIS109Y1', 3, null::jsonb),
    ('HIS111H1', 'Artificial Intelligence and the Fourth Industrial Revolution: Lessons from History', '24L/10T', 'The AI Age is driving a new, “Fourth Industrial Revolution,” according to World Economic Forum founder, Klaus Schwab. Could the real histories of the first three industrial revolutions help us navigate the disinformation crisis and the social, political, economic and environmental impact of this shift? Algorithmic platforms and AI tools, like those used in Instagram, TikTok, and YouTube are relatively new, but the hidden power structures that have shaped their rise and use are not. This course explores the big histories behind algorithmic technologies in two ways. First, class discussions, workshops, and guest lectures introduce students to overlooked histories behind our present moment, from the wild history of venture capital and tech monopolies to the rise of the early internet, and the big histories behind issues like facial recognition, celebrity, militarization, and privacy. Second, we explore the human reasons behind how and why social media platforms and AI tools, have amplified and automated disinformation and historical biases online. Hands-on research and projects help students explore and develop real solutions to displace disinformation, protect democratic elections, and provide the public better access to accurate historical content on social media. Restricted to first-year students.', null, 3, null::jsonb),
    ('HIS112H1', 'Ten Events that Changed the World', '24L/10T', 'This course examines ten events changed the world and continue to have ramifications today. Events may change year to year, depending on the instructor. Students will learn how historians work to understand the significance of these moments, human agency, and the idea of an “event,” itself.', null, 3, null::jsonb),
    ('HIS115H1', 'History Now: How the Past Shapes the Present', '24L/20T', 'In this introduction to the discipline of history, the instructor chooses several pressing issues facing the world today and delves into their pasts. The course helps us understand what the study of history can and cannot teach us about the present moment, and the challenges and opportunities of using history to understand our present – and potentially our future, as well. Students will assess historical “truth claims” made across multiple media, how to find and make use of credible scholarship, and how historians make use of primary sources. Assignments will focus on the development of critical reading and strong writing skills. In tutorial discussions, students will practice making effective oral arguments.', null, 3, null::jsonb),
    ('HIS190H1', 'Freedom Schools', '24S', 'This first-year seminar explores radical traditions of education beyond and in resistance to formal schooling. Transnational in scope—and journeying from the late nineteenth century to the present day—we will study the pedagogical innovations and grassroots struggles of anarchic youth, guerrilla intellectuals, and feminist revolutionaries who used education broadly, and historical inquiry in particular, as tools for empowerment and collective liberation. Focusing on primary sources from archives of anticapitalist, antiracist and anticolonial movements, we will investigate traditions of self-teaching and co-learning, genealogies of critical and transformative pedagogies, the construction of decolonial survival and supplementary schools, student mobilizations within and against the university, as well as abolitionist education in our contemporary moment. This course invites participants to interrogate the relationship of education to freedom and justice through collective criticism, self-reflection and creative expression. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('HIS191H1', 'Pandemics and Human History', '24S', 'We have all just lived through a major historical disruption caused by CoViD-19. In this course, you will be invited to use your experience of the pandemic as a tool for understanding other times, other places, and the study of history itself. We will study plagues and diseases from the ancient world to the Twentieth Century, and introduce methods from social, cultural, and economic history, as well as concepts from the histories of science and medicine. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('HIS192H1', 'A History of Queer Asia', '24S', 'A first-year seminar on the history of queerness, in all its complexity and diversity, in the no less complex and diverse settings of East, South, and Southeast Asia. Our journey will encompass empires and Indigenous peoples, rulers and rebels, and range from early recorded history down to the twentieth century. Focus will be placed on primary sources and introducing students to the evolving definitions of "queerness" itself. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('HIS193H1', 'Calls to Action: The TRC and Residential Schools in Canadian History', '24S', 'The last Indian Residential School in Canada closed in 1996. For more than a century and half before that, the Canadian state supported church-run residential schools intended to take Indigenous children away from their families, cultures, languages and traditions. Over 150,000 children passed through the doors of these different schools that operated from coast to coast. Using the formal report of the Truth and Reconciliation Commission as a central text, this course explores that history and the ongoing legacy of residential schools in Canada while introducing first year students to historical research methods and sources. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('HIS194H1', 'Power, Resistance, and the Graphic Novel', '24S', 'This course will look broadly at the question of power and resistance in the Americas (Canada, the United States, and Latin America) through the prism of graphic novels. Each week we will read a graphic novel related to important historical moments or events, drawing on scholarly articles to help us contextualize the novel. We will discuss the medium of graphic novels, their history and place in the broader culture, as well as how they might help or hinder our ability to study and disseminate information about the past. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('HIS195H1', 'Remembering and Forgetting', '24S', 'This course introduces students to the interdisciplinary study of history by exploring processes of remembering and forgetting intrinsic to every society. Topics include the ideas of history and memory, memory cultures and narratives and counternarratives and the study of legal trials, museums, monuments, novels and films as popular vehicles of historical knowledge. The course analyzes in particular how the experiences of war and violence have been both remembered and forgotten. The intersection, and dislocation, between trauma and remembrance is a main theme, as is the topic of collective memories in post-conflict societies. Restricted to first-year students. Not eligible for CR/NCR option.', 'AMS199H1', 3, null::jsonb),
    ('HIS196H1', 'Religion and Violence', '24S', 'This seminar explores the roles of religion in extreme violence. Working backward from the 1990s (Rwanda, Yugoslavia), we will consider cases including Guatemala, Cambodia, Indonesia, the Holocaust, Armenians, German Southwest Africa, and genocide of Indigenous peoples in North America. Students will produce a final project based on original research. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('HIS197H1', 'Medieval Medicine', '24S', 'This course focuses on the theories and practices of medicine in Europe, c.500-1500, by examining surviving evidence from the period, including (in translation) pharmaceutical recipes, diagnostic guides, doctor''s records, treatises on anatomy, surgery and gynecology, commentaries on Hippocrates and Galen, laws and regulations for physicians, university lectures, disputes in court records, satirical writings against physicians, and so on, as well as visual evidence of artifacts, surgical instruments, manuscript illumination/diagrams, hospital sites and design. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('HIS198H1', 'Decolonizing Women''s History', '24S', 'This course introduces students to the historiographical and theoretical debates in women''s and gender history from a global perspective, with emphasis on the local histories of women in the non-western world. Students will study the themes in women''s history as articulated by first and second wave feminists. The second part of the class deconstructs the basic assumptions of Western feminism through the perspective of post-colonial feminist writings and empirical studies. The readings are structured so that you consider how examples from Asia disrupt narratives of universality in Western feminist epistemologies. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('HIS200H1', 'Drunk History', '24L/12T', 'Histories of wine or beer or vodka often focus either on the production of these alcoholic beverages and their role in national or local economies, or on the ways that drinking is part of celebration. But drunkenness enters the historical record in other ways, too—not just as a social lubricant but as a social ill, one associated with intimate violence or violence to the self and with mass protest. From worries about the Gin Craze to race-based restrictions on consumption, from tax policies to policing, this class will consider the many ways that drunkenness has been accepted, denounced, and legislated in societies around the world.', 'HIS195H1 (Drunk History), offered in Fall 2019 and Winter 2021.', 3, null::jsonb),
    ('HIS205H1', 'From Women''s History to Gender History', '24L/10T', 'This course critically examines gender in the context of politics, society, culture, and economics across a range of comparative times and spaces depending on instructor expertise. In what ways have gendered norms and transgressions been part of human societies and lived experiences? How have those norms shifted across historical and geographical contexts? How has the history of gender impacted gender as it is lived and made political today?  Throughout the course, we will be querying the theoretical assumptions underlying and framing the historical texts we are studying, as well as assessing the different kinds of primary sources used to recover women''s and gender history.', 'HIS245Y1', 3, null::jsonb),
    ('HIS205Y1', 'Topics in Women''s History', '48L/20T', 'This course introduces students to the diverse experiences of women from a comparative perspective. Students will study how women''s strategies have shaped the major cultural, economic, political and social processes in the world and how these processes have affected women''s experiences in their particular societies.  By studying women''s history from both local and global perspectives, students will engage critically with claims that women''s history is universal.  The local focus of the course will rotate between Africa, Asia, Europe, and North America, depending on the expertise of the instructors.', 'HIS245Y1', 2, null::jsonb),
    ('HIS208Y1', 'History of the Jewish People', '48L/20T', 'This course explores the origins of the Jewish people, beginning with the Bible and ending in the 21st Century. We will follow the development of Jewish social and cultural life across the Muslim and Christian worlds and discuss how Jews adapted to the constraints and opportunities provided by the non-Jewish majority. We will also learn about key Jewish books and concepts, including the Talmud, Kabbalah (Jewish mysticism), Halakhah (Jewish law), and Jewish philosophy. Finally, we will investigate the Jewish movements that arose in response to the challenges of modernity and new ideologies.', null, 3, null::jsonb),
    ('HIS218H1', 'Environmental History', '24L/8T', 'A lecture-based course designed to introduce students to key moments and concepts in the field of environmental history since c. 1400. This course will track the reciprocal influence of humans and the non-human world since the so-called "Columbian Exchange," emphasizing the ways in which the non-human world-from plants, animals, and disease organisms to water, topography, and geography- have shaped human endeavours. At the same time, students will engage with many of the ways in which human beings have shaped the world around us, from empire and colonization, to industrial capitalism, nuclear power, and modern wildlife conservation.', null, 3, null::jsonb),
    ('HIS219Y1', 'Medieval Mediterranean History', '48L/20T', 'A new approach to medieval history, this course focuses on the Mediterranean world as a site for the convergence of Western and Eastern Christian, Muslim, Jewish, sub-Saharan African, and East Asian peoples and cultures. It treats topics such as political and military conflict, including Muslim conquests and the Crusades; the situation of religious minorities; religious conversion; cultural exchange; commerce; slavery; aspects of material culture, such as art and architecture; and family and gender from a comparative perspective.', 'HIS303H1,  HIS308H1', 3, null::jsonb),
    ('HIS220Y1', 'The Shape of Medieval Society', '48L/20T', 'Immersion in medieval western Europe with extensive readings of primary sources from late Roman times to 1500 and use of works of art. The goal is to understand medieval society on its own terms, as much as possible.', 'HIS220Y5/  HIS220H5/  HIS221H5/  HISB60H3/  HISB61H3', 3, null::jsonb),
    ('HIS221H1', 'African American History to 1865', '24L/10T', 'An introduction to the history of Africans and people of African descent in the Americas generally, and the United States in particular. Major themes include modernity and the transatlantic slave trade; capitalism and reparations; Atlantic crossings; African women, gender, and racial formations; representation, resistance, and rebellion; nation-building; abolitionism and civil war; historical method and the political uses of the past.', 'HIS298Y1 (2016-17)', 3, null::jsonb),
    ('HIS222H1', 'African American History from 1865 to the Present', '24L/10T', 'This course examines the history of black people in the United States after the abolition of slavery. Major themes include the promise and tragedy of Reconstruction; gender and Jim Crow; race and respectability; migration, transnationalism, and 20th century black diasporas; black radical traditions and freedom movements; intersectionality and black feminisms; the drug war and mass incarceration; sexuality and the boundaries of blackness.', 'HIS 298Y1 (2016-17)', 3, null::jsonb),
    ('HIS230H1', 'Indigenous and Early Colonial Caribbean History', '24L/12P', 'This course introduces students to the study of Caribbean history from first human settlement to the late 18th century. Subject matter covered includes indigenous social structures, cosmology and politics; the process of European conquest; the economics, society and political order of colonial society; the Middle Passage; the everyday lives and struggles of enslaved peoples.', 'HIS294Y1', 3, null::jsonb),
    ('HIS231H1', 'Revolution and Emancipation in the Colonial Caribbean', '24L/12P', 'This course explores the history of the late eighteenth and nineteenth century Caribbean, from the Haitian Revolution to the U.S. occupation of Cuba and Puerto Rico. Students learn about the first struggles for political independence; the struggle to abolish the slave trade; slave emancipation; indentureship and struggles to define freedom after emancipation.', 'HIS294Y1', 3, null::jsonb),
    ('HIS240H1', 'The First World War: A Global History', '24L/10T', 'This course offers an introduction to the global history of the First World War. It aims to introduce students to the different ways historians have sought to understand the war, as well as scholarly and intellectual challenges that come with studying an event of this magnitude and horror. In general, students will examine the origins and causes of the conflict, survey the factors that shaped the course of the war, and consider how and why the fighting came to an end when it did. These broad approaches will be supplemented with consideration of specific examples from around the world.', null, 3, null::jsonb),
    ('HIS241H1', 'Europe in the Nineteenth Century, 1815-1914', '24L/10T', 'Intellectual changes in Britain, France, Germany, Austria-Hungary, Italy, Russia and other countries are discussed. The course examines large-scale political, social and cultural changes that created today''s modern world.', 'EUR200Y1/  EUR200Y5/  FGI200Y5/  HIS241H5/  HISB93H3', 3, null::jsonb),
    ('HIS242H1', 'Europe in the 20th Century', '24L/10T', 'The evolution of European politics, culture, and society from 1914: the two world wars, Fascism and Nazism, the post-1945 reconstruction and the movement towards European integration.', 'EUR200Y1/ EUR200Y5/ FGI200Y5/ HIS242H5/ HISB94H3', 3, null::jsonb),
    ('HIS243H1', 'Early Modern Europe (15th-17th Centuries)', '24L/10T', 'The shape of modern European society is set in the early modern period. Expansion overseas sets some European nations on a path of imperial and colonial development which shapes international relations into the twenty-first century. The revival of classical forms revolutionizes art and architecture, and provides new models for education, politics, law, science, and gender relations. The split of the Christian Church into Protestant and Catholic denominations inspires intellectual and artistic creativity, sparks violent wars, and is brought around the globe by missionaries. Modern states and our fascination with determining ''national identity'' take shape out of the competition between dynasties, social classes, faiths and territories.', null, 3, null::jsonb),
    ('HIS244H1', 'Early Modern Europe, 1648-1815', '24L/10T', 'This course will survey the history of Europe from the Thirty Year''s War to the Napoleonic Empire. We will explore the principal themes which transformed Europe during this period: the birth of the modern nation-state; the increasing scale of warfare; the scientific revolution and the Enlightenment; the emergence of capitalist economies; the consolidation of transatlantic colonial empires; and the French Revolution. Students will read a range of primary and secondary source materials; attendance at lectures, participation in tutorials, course reading, and writing are all required components for this course.', null, 3, null::jsonb),
    ('HIS245H1', 'European Colonialism, 1700- 1965', '24L/10T', 'This course will introduce students to the history of European colonialism. It will analyze the nature of colonial rule, the impact of empire on both colonies and metropoles, and delve into questions of power, gender and culture. It considers slavery and abolition, imperial networks, colonial capital, colonial competition, colonial cultures, the twilight of colonial rule, and a variety of settings.', null, 3, null::jsonb),
    ('HIS247H1', 'The Second World War: A Global History', '24L/12T', 'This course offers an introduction to the global history of the Second World War. It aims to expose students to historiographical debates regarding the war, the use of primary sources, and the scholarly and intellectual challenges that come with studying an event of this magnitude and horror. In general, students will examine the origins and causes of the conflict, survey the factors that shaped the course of the war, and consider how and why the fighting came to an end when it did. These broad approaches will be supplemented with consideration of specific examples from around the world.', null, 3, null::jsonb),
    ('HIS250Y1', 'History of Russia', '48L/20T', 'This course introduces the history of the modern Russian Federation and its predecessor states from the founding of Moscow through the ages of the Russian Empire and of the Soviet Union to the present day. Emphasis is placed on reading primary source documents.', 'HIS250H1/ HIS250H5', 3, null::jsonb),
    ('HIS251Y1', 'History of East Central Europe', '48L/20T', 'The Polish, Czech, and Hungarian background; the Balkans in the late medieval and early modern periods. Renaissance, Reformation and Counter-reformation, decline and national awakening to the beginning of the 19th century. Partitioned Poland, nationalism in the 19th century; World War I, Peace Settlement, interwar years and the Communist period.', null, 3, null::jsonb),
    ('HIS252H1', 'Soccer: History of the World''s Game', '24L/10T', 'This course examines the history of the world''s most popular sport, soccer, in broader social, economic, and cultural context. We will retrace the emergence of the modern game in nineteenth-century Britain; its mobilization as a vehicle for political, social, cultural, and gendered identities; fandom and supporter culture; and the economics of soccer. Students will engage with a wide range of primary sources and scholarly literature from an array of disciplinary perspectives (including history, cultural anthropology, sociology, literature, and economics). While the course is appropriate for History majors, it is accessible to students from other units as well.', null, 3, null::jsonb),
    ('HIS262H1', 'Canada: A Short History of Here', '24L/10T', 'Designed for non-history students, this introductory survey fulfills the Society and Its Institutions breadth requirement.  It is open to all who want to know more about Canada.  Make sense of politics today and develop a deeper understanding of Canadian society and its institutions through study of the major events and demographic trends that have shaped the development of this country.  Topics will include First Nations/newcomer relations (including treaties and the Truth & Reconciliation report), French/English relations (including Quebec separatism), regionalism, the North, economic history, constitutional developments, and the development of Canadian identity, including common symbols associated with Canada.  No essay requirement.  Instead, enhance your critical reading and thinking skills through short writing assignments and weekly discussions of tutorial readings.  *This course will not count towards History program requirements or as a prerequisite for upper level courses*', 'HIS263Y1,  HIS264H1', 3, null::jsonb),
    ('HIS264H1', 'Critical Issues in Canadian History', '24L/12T', 'This course introduces key issues in Canadian history and foundational principles of historical analysis. It is particularly suited to potential History majors/specialists, although other students are welcome. It is not a comprehensive survey. Examples serve to deepen analysis and introduce important methods and debates, preparing students for upper year courses in Canadian history.', 'HIS262H1,  HIS263Y1', 3, null::jsonb),
    ('HIS265Y1', 'Black Canadian History', '48L/20T', 'This course explores the historical experiences of persons of African descent in Canada. We begin by examining the presence of free and enslaved Africans in New France and British North America, moving into twentieth century themes exploring Black liberation, immigration and resistance in Canada. The course brings into sharp focus the historical production of racial categories and racist thought and practice in Canada and examines the experiences of Black Canadians within the context of ''multiculturalism.''', null, 3, null::jsonb),
    ('HIS266H1', 'Asian Canadian History', '24L/10T', 'The course examines the history of Asian Canadians from the mid-1800s to the present by analyzing their contributions to the socio-cultural, economic, and political development of Canada. It explores how Asian Canadian history reconfigures prevailing understanding of race, migration, multiculturalism, and national identity through intersectional, comparative, and transnational frameworks.', 'CDN230H1,  UNI230H1', 3, null::jsonb),
    ('HIS267H1', 'Business History', '24L/10T', 'Business, and its history and evolution, is a fundamental aspect of understanding modernity. Capitalism and globalization, two of the most important aspect of business and its history, shape our world in profound ways. Utilizing a “glocal” approach that combines global and Canadian business history cases within a transnational context, this course seeks to interrogate and understand the evolution and development of modern business, capitalism and globalization from the late 19th Century into the early 21st.', null, 3, null::jsonb),
    ('HIS268H1', 'Law and History', '24L/10T', 'The Federal Interpretation Act of Canada states that the ''law is always speaking''. If the law is always speaking, then it must be speaking in present tense. But if it only speaks in present tense, does it have a past? How might we consider the field of law from different historical angles? This course will introduce students to different historical approaches to and uses of law. Using examples from a wide array of legal traditions (e.g. Common Law, Civil Law, Indigenous Law, Islamic Law), the course will help students gain a greater appreciation for the function, study, and development of law across different times and places.', null, 3, null::jsonb),
    ('HIS271Y1', 'American History Since 1607', '48L/20T', 'A survey of the economic, social, cultural, and political history of the United States from the colonial era to present times.', 'HIS271H5/ HIS272H5/ HISB30H3/ HISB31H3', 3, null::jsonb),
    ('HIS280Y1', 'History of China', '48L/20T', 'A critical history of the place we today call China from prehistoric times to the 21st century, tracing shifting borders, identities, governments, and cultures while challenging any singular definition of "China."', null, 3, null::jsonb),
    ('HIS282Y1', 'History of South Asia', '48L/20T', 'A rigorous survey of major themes in the history of South Asia (mapped largely but not exclusively by India, Pakistan and Bangladesh), using primary and secondary sources and addressing historiographical debates. Delves into regional complexities and considers broad questions about political economy, colonial governing, anti-colonial nationalism, capitalism, gender and cultural politics. Emphasizes the period after 1750; begins with an overview of ancient, medieval and Mughal history before turning to the British Empire. Addresses how understandings of pre-modern worlds inform contemporary politics and cultures; contextualizes South Asia within current global formations.', 'HIS282H5/  HISB57H3', 3, null::jsonb),
    ('HIS283Y1', 'History of Southeast Asia: How the Lands Below the Winds Reshaped the World', '48L/20T', 'This course examines how the cultural, economic, religious, and social histories of "Southeast Asia" [Brunei, Cambodia, East Timor, Indonesia, Laos, Malaysia, Myanmar (Burma), the Philippines, Thailand, & Vietnam] shaped the world as we see it today. Lectures will demonstrate how the millennia-long cultural and material exchanges Southeast Asians engaged via water across the Indian and Pacific Oceans and the lands across Eurasia affected the lives of its inhabitants and the proximal and distant regions with which it had contact. In Tutorials, students will be trained to read primary sources. Themes to be explored include economic exchange, colonialism and its impact, gender and sexual diversity, and religion and society.', null, 3, null::jsonb),
    ('HIS285H1', 'History of Chinese Diasporas in the Americas', '24L/12T', 'Explores histories of ethnic Chinese and Chinese diasporas in the Americas, especially in Canada and the United States. Investigates events from the 19th, 20th, and 21st centuries. Topics include migrations, diasporas, transnationalism, identities, families, communities, cultures, and racialization, as well as relations with their host societies and with China.', null, 3, null::jsonb),
    ('HIS291H1', 'Latin America: The Colonial Period', '24L/10T', 'The evolution of Spanish and Portuguese America from pre-Columbian civilizations to the wars of independence.', 'HIS291Y1/ HIS290H5', 3, null::jsonb),
    ('HIS292H1', 'Latin America: The National Period', '24L/10T', 'A survey of Latin American history from the wars of independence to the present day.', 'HIS292Y1/ HIS290H5', 3, null::jsonb),
    ('HIS293H1', 'The Making of the Atlantic World, 1480-1804', '24L/10T', 'This course introduces students to the social, economic, cultural and political history of the Atlantic world resulting from European exploration and colonization in the Americas beginning in the 1490s and the growth of the transatlantic slave trade. It focuses on interactions between Africans, Europeans, and Amerindians around the Atlantic Ocean.', null, 3, null::jsonb),
    ('HIS295Y1', 'History of Africa', '48L/24T', 'An introduction to African history and the methodology of history more broadly, this course sets out to question how historians do history, examine differences in theories of knowledge, and explore the relationship between academic and cultural representations of the past. The course also draws on anthropology and related disciplines.', 'HIS295H5', 2, null::jsonb),
    ('HIS297Y1', 'History of Africa from a Gender Perspective', '48L/20T', 'This survey of African history is analytical rather than narrative in its approach. It rethinks the way that African history has hitherto been conceptualized and taught by placing the question of gender at the center of the story of Africa.', null, 3, null::jsonb),
    ('HIS298Y0', 'Themes & Issues in History', '48L/20T', 'This is a thematic survey course addressing issues of gender, class, ethnicity, religion, war, economics and political strife through broad-sweep coverage of a region''s history. Prepares students for upper-level study through exposure to eyewitness primary sources and conflicting secondary interpretations of events.', null, 3, null::jsonb),
    ('HIS299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HIS299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HIS300H1', 'Energy and Environment in Canadian History', '24L', 'This course examines the history of energy in Canada from the perspective of environment, business, state, daily life, and culture, with emphasis on the twentieth century. Topics include Big Oil, large dams, nuclear power, energy colonialism, pipeline disputes, climate change, daily life, and the relationship between energy and social power.', null, 3, null::jsonb),
    ('HIS301H1', 'World War II France', '24L', 'This third-year lecture course examines the experience of the Second World War in France. Special attention is paid to questions of collaboration, resistance and accommodation. Other topics include the role of the French overseas colonies in this era, the issue of internal vs. external resistance, and the fate of civilian populations. Students engage with a set of primary and secondary sources as well as visual material that includes films.', 'VIC102H1', 3, null::jsonb),
    ('HIS302H1', 'Material Culture in Victorian Britain', '24L', 'An examination of the products of the first and second industrial revolutions in Victorian England, including food, drugs, clothing, and trains. This course focuses on the cultural history of commercialization and consumerism.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS304H1', 'Topics in Middle East Histories', '24L', 'An in-depth examination of Middle East historical issues. Content in any given year depends on instructor. See History Website for more details.', null, 3, null::jsonb),
    ('HIS305H1', 'Death and Life in Plantation America', '24L', 'This course examines the experiences of enslaved people in the Americas and introduces students to the complex history of the ''plantation'' as a site of violence; social, economic, labour and political organization and experimentation; kinship, culture and community recreation and rebellion. The course will focus on the 17th to 19th century Caribbean in comparative and transnational relationship to the continental Americas.', null, 3, '{"operator": "OR", "items": ["HIS230H1", "HIS271Y1", "HIS291H1", "HIS295Y1"]}'::jsonb),
    ('HIS307H1', 'Oral Histories of Asian Canadians', '24L', 'This course explores the cultural and social history of everyday life as it affected Asian Canadians with focus on Chinese, Filipinos and South Asians from the 1960s to present. It introduces oral history and documentary film as key research methods for understanding changing cultural practices and identities within families, in food, and in social settings within and beyond ethnic communities.', 'HIS286H1', 3, null::jsonb),
    ('HIS309H1', 'Global Reformations', '36L', 'The Reformation has traditionally been approached as a 16th century European phenomenon. This course will consider religious reform movements from the 15th to 18th centuries and set these into a global framework, considering spatial and sensory dimensions, cross-cultural engagements and exchanges, and intersections with race and colonization.', 'HIS340H5/  RLG346H5', 3, '{"operator": "OR", "items": ["HIS102Y1", "HIS109Y1", "HIS243H1"]}'::jsonb),
    ('HIS310H1', 'Democracy and Dissent in Postwar Canada', '24L', 'This course will explore the background, experience, and legacy of protest movements in Canada in the post-1945 era. The course will draw on the latest historical literature and will situate Canadian social movements in the broad transnational context in which they unfolded. Topics will include anti-racist movements, feminism, nationalism, Indigenous politics, environmentalism, labour, and the New Right and the New Left.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('HIS311H1', 'Canada in the World', '24L', 'Ranging from the fifteenth through to the turn of the twenty-first century, students will learn about the treaties, trade agreements and alliances, as well as the informal traditions, working relationships and cultural ties that shape relations of people living within the boundaries of present-day Canada with the world. For this course, “international relations” is broadly defined, including military, political, economic, environmental and immigration policies, both official and informal.', 'HIS311Y1/  HIS311H5/  HISC46H3', 3, null::jsonb),
    ('HIS312H1', 'Immigration to Canada', '24L', 'From the colonial settlement to 21st century, immigration has been a key experience and much debated in Canadian life. Drawing on primary sources, as well as historical and contemporary scholarship, this course will discuss migration, citizenship and belonging as central features in Canada''s experience of immigration. This course focuses on the individuals, groups, and collectives who built, defined, contested, and reimagined this country, to help make and remake Canada through immigration.', null, 3, null::jsonb),
    ('HIS313H1', 'People and Other Animals in History', '24L', 'What happens to history when we consider nonhuman animals as subjects and actors alongside humans? This course revisits episodes, events, and historical processes with nonhuman animals in mind to explore the interpretive and analytic possibilities that emerge when other animals are considered as full participants in the historical record. Thematic focus is located in the Atlantic world since the early modern period.', null, 3, null::jsonb),
    ('HIS314H1', 'Twentieth-Century Quebec', '24L', 'This course will explore the history of Quebec in the 20th century. In addition to looking at more traditional themes focused on nationalism and constitutional politics, we will also look at the history of encounter between groups of different backgrounds and origins. As such, we will place a large emphasis on colonialism and Indigenous history, and the politics of language, race, and immigration. Themes will include, among others, the history of Quebec in an era of British imperialism, jazz, the art world, literature, the Oka Crisis, and Quebec''s ties to Haiti and other parts of the non-Western world.', 'HIS314Y1', 3, null::jsonb),
    ('HIS315H1', 'Decolonial Vietnamese Histories', '24L', 'This course introduces students to the narratives that diverse actors have used to talk about Vietnamese histories. We will focus on the histories and perspectives of the indigenous peoples of the peninsula, ethnic minority groups, as well as that of the majority "Kinh people." We''ll explore themes which have been central to shaping the geographic space, the socio-political regimes, and the cultural entity we now call "Viet Nam," while examining how varying types of historical method and archival strategies can influence the telling of histories. What kinds of techniques did Vietnamese and Western political actors, scholars, and writers, employ to narrate the Vietnamese past(s) and how do these visions tell us about the crafter of these narratives? What counts as “history” and who gets/got to decide? Whose experiences were relevant in the different epistemological approaches?', null, 3, null::jsonb),
    ('HIS316H1', 'Competing Colonialism in Northeast China The Harbin Experiment', '24L', 'This course explores the political, social, and cultural history of Harbin, one of the major cities of Manchuria/Northeast China, the product of competing Russian, Japanese, and international colonialism during the first half of the twentieth century, and an early case of multi-ethnic emigration and multiculturalism.', null, 3, '{"operator": "OR", "items": ["HIS250Y1", "HIS280Y1", "HIS281Y1"]}'::jsonb),
    ('HIS317H1', '20th Century Germany', '36L', 'A survey of modern German history in the twentieth century. Topics include World War I and the postwar settlement, the Weimar Republic, the National Socialist dictatorship, the Holocaust, the division of Germany, the Cold War, German reunification, Germany and the European Union, nationalism, political culture, war and revolution, religious and ethnic minorities and questions of history and memory.', null, 3, '{"operator": "OR", "items": ["HIS103Y1", "HIS109Y1", {"operator": "AND", "items": ["HIS241H1", "HIS242H1"]}, "EUR200Y1"]}'::jsonb),
    ('HIS318H1', 'Histories of the "Wild" West', '24L', 'What happens when histories of North America begin in the West? This course examines the critical challenges that the myths and legacies of the West pose to North American history, from pre-contract to 1990. Themes include First Nations and colonialism, immigration, racism, economic development, regionalism, prostitution and illegal economies.', null, 3, null::jsonb),
    ('HIS319H1', 'Histories of the Horn of Africa', '24L', 'A critical, introductory survey exploring major themes in the political, social, economic, and cultural histories of the Horn of Africa [Somalia, Ethiopia, Djibouti, Eritrea, Sudan, South Sudan] and surrounding Red Sea and Indian Ocean from prehistoric times to the present.', null, 3, null::jsonb),
    ('HIS320H1', 'Barbarian Invasions and the Fall of the Roman Empire', '24L', 'Covers major events and themes for the period 300-600, including decline of Greco-Roman paganism, conversion to Christianity, individual barbarian groups (Ostrogoths, Visigoths, Huns, Burgundians, Vandals, Franks, Lombards), their culture and impact on empire, Justinian''s reconquests.', null, 3, null::jsonb),
    ('HIS321H1', 'Dark Age Europe, 7th-10th Centuries', '24L', 'Surveys major events and figures for the period c. 600-1000, including: Pope Gregory the Great, the Merovingian Franks, Lombard Italy, Byzantine civilization, the rise of Islam, Charlemagne, the Carolingian Renaissance, the Vikings, Anglo-Saxon England to King Alfred, the Ottonians.', 'HIS320Y1', 3, null::jsonb),
    ('HIS322H1', 'Topics in African History', '24L', 'Selected topics on a specific period, aspect or themes in African history. Topics in any given year depend on the instructor.', null, 3, null::jsonb),
    ('HIS323H1', 'Rites of Passage and Daily Life in the Middle Ages', '36L', 'Reflecting on the life cycle and rites of passage in the medieval period gives the opportunity to study the daily lives of peasants, nobles, monks, nuns, and (Christian and Jewish) burghers, and to observe from an interesting angle the differences between female and male life experiences.', null, 3, null::jsonb),
    ('HIS324H1', 'The Criminalization of Protest in Latin American History', '24L', 'The criminalization of protest is generally understood in terms of policing, and the use of legal measures, including states of exception, to quell dissent. Criminalization can also refer to the stigmatization of individuals, groups, and communities by the state, and the marginalization of working class or racialized groups. This course invites students to study lived experiences of criminalization in Latin American history.', null, 3, '{"operator": "AND", "items": ["HIS292H1"]}'::jsonb),
    ('HIS325H1', 'Imperial Russia', '24L', 'This course focuses on Russia''s history during a period of remarkable change and turbulence, when the country more firmly established its far-flung empire while simultaneously attempting to define itself as a nation. From the wars and reforms of Peter the Great through the end of the empire during the First World War, the course touches on questions of social and cultural change, and the political events that allowed or constrained them.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS326H1', 'Topics in Asian Histories', '24L', 'A specific period in some aspect of Asian histories. Topics in any given year depend on the instructor.', null, 3, '{"operator": "AND", "items": ["HIS280Y1"]}'::jsonb),
    ('HIS327H1', 'Rome: The City in History', '24L', 'This course investigates the development of Rome from its mythical foundations, through the Empire, the Middle Ages, Renaissance and Baroque to the modern city, illustrating the shift from the pagan to the papal city and its emergence as the capital of a united Italy after 1870 and a modern European metropolis.', 'VIC348Y1 (offered in Fall/Winter 2012-2013, 2013-2014, 2014-2015 and 2015-2016) and  VIC162H1 (offered in Fall 2016, Fall 2017 and Fall 2018)', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('HIS328H1', 'Modern China', '24L', 'An examination of political, social and economic developments in modern Chinese history to the present day. Main topics may include the decline of the Imperial order and the challenge of Western imperialism; the Republican period; the rise of the Communist movement; the People''s Republic of China.', 'JMC201Y1,  HIS328Y1,  EAS285H1', 3, '{"operator": "AND", "items": ["HIS280Y1"]}'::jsonb),
    ('HIS329H1', 'Central Middle Ages (900-1200)', '36L', 'A chronological survey from 900, with the foundation of Cluny by the Duke of Aquitaine, the last waves of Vikings, and the decline and end of the Carolingian Empire, up to 1200, with the Battle of Bouvines, the more formal organization of the first universities and the construction of the Gothic cathedrals. The main question will be: what happens when there is no real central power? Why did the term “Feudalism,” now nicknamed the F word by medievalists, was judged inappropriate to describe the situation?', null, 3, null::jsonb),
    ('HIS330H1', 'Germany from Frederick the Great to the First World War', '24L', 'Topics include German reactions to the French Revolution, Napoleonic occupation, the Wars of Liberation, industrial expansion, the Revolutions of 1848, unification in 1871, Bismarck and Kaiser Wilhelm II, everyday life, gender relations, avant-garde culture, nationalism, antisemitism, colonialism, and the Great War of 1914-18.', 'HIS341Y1', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS331H1', 'Modern Baltic History', '24L', 'The history of the Baltic countries, Estonia, Latvia and Lithuania from 1900 to the present day, with emphasis on the emergence of independent Baltic states, World War II, communist era, the Baltic Revolution, the restoration of independence and European integration.', null, 3, null::jsonb),
    ('HIS332H1', 'Crime and Society in England, 1500-1800', '24L', 'The changing nature of crime and criminal justice in early-modern England; the emergence of modern forms of policing, trial and punishment.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS333H1', 'Catholic Asia in the Early Modern Era, 1500-1800', '24L', 'This course examines the impact of Catholicism in Asia, from its introduction to its relevance in the contemporary global order. Students will be introduced to how Catholicism and the technologies accompanying it affected historical transitions in local communities in Asia as well as how the growth of these communities has affected the global Catholic Church.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('HIS334H1', 'The Great Wall of China', '24L', 'Why was the Great Wall built? Did it keep the people of Mongolia out, or to keep the people of China in? How has it come to represent China''s past and present as a paradoxical symbol of civilizational glory and political tyranny? For almost 2,000 years, the question of how to handle the nomads of Mongolia was a central question of China''s foreign policy. Wall construction, in various places and times, was one of the consistent responses to the "nomad problem." The Great Wall came to symbolize the economic, military, political, and cultural clash between China and Mongolia. It was also a site of diplomacy, markets, and peace-making. Students will explore fundamental questions in frontier history and international relations: do contrasting environments create contrasting cultures? do culture and ideology constrain the responses of policy makers to foreign threats? does crossing a frontier change us? The class covers the 3rd century BCE to the 20th century CE, considering perspectives from both sides of the wall, and the legacy of the Great Wall as an international symbol in the present day.', null, 3, null::jsonb),
    ('HIS335H1', 'Canadian Legal Histories', '24L', 'This course examines Canadian legal history through differing Indigenous, civil, and common law legal traditions, using multiple categories of analysis, including race, gender, class, spirituality and sexuality. Legal history is a strong and engaging field of study in Canada. Topics will include constitutional histories, treaties, law-making, differing systems of land tenure, the franchise and the structure of deliberative bodies (e.g. legislatures), courts and systems of justice, policing and criminal law, punishment (including histories of incarceration and alternatives).', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, {"operator": "OR", "items": ["HIS263Y1", "HIS264H1"]}]}'::jsonb),
    ('HIS336H1', 'The History of Amazonia', '24L', 'Contrary to traditional images, Amazonia is not a pristine forest with sparse human presence. This course explores the complex societies developed around the Amazon River Basin and how they shaped the forest''s configuration. The course centers on the development of European colonialism in the region, the different modes of commodity extraction, and projects to incorporate Amazonia into nation-states. Amazonia''s history – and the history of the people who live there – helps us imagine the region''s role in our era of acute climate challenges. Topics may include empire, Indigenous history, economic development, and environment.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('HIS337H1', 'Culture, Politics and Society in 18th Century Britain', '24L', 'Deals with England, Scotland, Ireland and the Atlantic World. Addresses major political, social, economic, intellectual and cultural highlights of the "long" eighteenth century. Deals with enlightenment, industrialization and the loss of the first British empire. Interrogates Britain''s emerging status as a world power.', 'HIS337Y1', 3, null::jsonb),
    ('HIS338H1', 'The Holocaust, to 1942', '24L/5T', 'German state policy towards the Jews in the context of racist ideology, bureaucratic structures, and varying conditions in German-occupied Europe. Second Term considers responses of Jews, European populations and governments, the Allies, churches, and political movements.', 'HIS388Y1/ HIS398Y1/ HIS338H5', 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}]}'::jsonb),
    ('HIS339H1', 'History of Modern Israel', '24L', 'This course explores the history of the Jewish state from the rise of Zionism to the present. Topics include the Zionist-Arab conflict, immigration, the construction of a new Hebrew identity, interactions between religion and state, the impact of the Holocaust, and the relationship between Israel and the Jewish diaspora.', null, 3, '{"operator": "AND", "items": ["HIS208Y1"]}'::jsonb),
    ('HIS340H1', 'The Ottoman Empire, 1800-1922', '24L', 'The course examines the history of the Ottoman Empire from the beginning of the 19th c. until its dissolution in the course of World War I. Topics include Ottoman reforms, relations between the Empire''s populations and the state, the diplomatic interactions known as “the Eastern Question,” the Young Turk revolution, gender, and intellectual, cultural and artistic developments.', 'HIS389H1 (The Ottoman Empire, 1800-1922)', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS341Y1', 'Germany Among the Global Empires 1840-2010', '48L', 'This course places Germany''s long national history in a transnational and global context, exploring its place among the global empires of Britain, Russia, France and the United States from the mid-seventeenth century to the present. Events of the German nation-state''s political, social and cultural developments are analyzed through a framework focused on both military expansion and the development of the world economy after 1700. Particular attention is paid to the interplay between strategies for a global expansion and transformations in national culture, looking at Germany in the world and the world in Germany.', null, 3, '{"operator": "OR", "items": ["HIS102Y1", "HIS103Y1", "HIS107Y1", "HIS109Y1", "HIS241H1", "HIS242H1", "HIS243H1", "HIS244H1", "EUR200Y1", "HIS250Y1", "HIS271Y1"]}'::jsonb),
    ('HIS342H1', 'Political and Psychological Liberation in 20th Century Africa', '24L', 'This course examines the growth of movements for the political liberation of Africa and the psychological liberation of Africans from Western imperialism and cultural hegemony. Postcolonial thinking and art was fundamental to the project of decolonization. It uses primary text and films to explore African cultural and intellectual history.', null, 3, null::jsonb),
    ('HIS343H1', 'History of Modern Intelligence', '24L', 'This course explores the rise of modern intelligence over the long 20th century, from Anglo-Russian imperial competition before World War I through to the post-9/11 era. Students will study the contribution of intelligence services to victories and defeats in war, peace, and the grey areas in between. The course will also examine the relationship between intelligence services and society.Occasionally, this course will emphasize a specific theme of modern intelligence history; a specific type of intelligence; or the evolution of intelligence in a particular state. Details regarding specific topics will be available on the department''s website on an annual basis.', 'HIS343Y1', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('HIS344H1', 'The Global Cold War', '24L', 'This course examines the Cold War through its global dimensions, going beyond the American-Soviet bipolar rivalry to explore the impact of the Cold War in Latin America, Asia, and Africa. Students will work closely with original primary sources and interrogate historical interpretations of the Cold War through different regional and thematic perspectives.', 'HIS344Y1', 3, null::jsonb),
    ('HIS345H1', 'History and Film', '24L', 'This course is designed to further students knowledge of films relationship to the events they depict and their undeniable power as representational systems to render history effectively. This will necessarily entail both close examination of the formal systems film rely upon and an understanding of the distinction between fictional and non-fictional forms in film.', null, 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": "HIS"}]}'::jsonb),
    ('HIS346H1', 'Rice, Sugar, and Spice in Southeast Asia: a History of Food in the Region', '24L', 'This course examines the importance of food products in the livelihoods of the inhabitants of Southeast and in the world economy. It traces the circulation of these products within the Southeast Asian region in the pre-modern period, into the spice trade of the early modern era, and the establishment of coffee and sugar plantations in the late colonial period, and the role of these exports in the contemporary global economy.', null, 1, null::jsonb),
    ('HIS347H1', 'The Country House in England 1837-1939', '24L', 'This course examines class distinction and community through the lens of the English country house from 1837 to 1939. Topics include owners, servants, houses, collections, gardens and rituals such as fox hunting.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS348H1', 'Topics in Gender History', '24L', 'An in-depth examination of issues in gender history. Content in any given year depends on instructor. See History website for more details.', null, 3, null::jsonb),
    ('HIS349H1', 'History of Britain: Struggle for Power', '24L', 'An introduction to the history of modern Britain with emphasis on the crown, class, gender, political parties, race, ethnicity, European Union and Brexit.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HIS350H1', 'Topics in European Histories', '24L', 'Selected topics on a specific period and/or region in European Histories', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HIS351H1', 'The Soviet Union and After', '24L', 'A survey of the history of the Soviet Union and its successor states beginning with the collapse of the Russian Empire. The course draws on scholarly literature, memoirs, and often film to understand the social, cultural, and political developments of the Soviet state, including famine, terror, and war.', 'HIS351Y1/  HIS351H5', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS352H1', 'A History of Women in Pre-colonial East Africa', '24L', 'This course examines the lived experience of women in societies, communities and polities of varying sizes across territories that cover eight contemporary East African states. It encompasses the period from 1000 B.C to the end of the nineteenth century. Topics covered are clustered under four broad themes: a) Ecology, work in commodity production, wealth and exchange relations; b) “Institutional” power, ideology and structures; c) “Creative” power particularly in the areas of healing, resistance/contestation and transformation; and d) Violence, war and vulnerability. The course challenges present day gender and identity categories applied to Africa''s deep past and highlights critical nuances of gender, identity and power dynamics in Africa.', null, 3, '{"operator": "AND", "items": ["AFR150Y1"]}'::jsonb),
    ('HIS353Y1', 'Poland: A Crossroads of Europe', '48L', 'Social and political history of Poland from the 10th to the 20th century. Analysis of the political history in a broader, central European context; consequences of Christianization of medieval Poland and the Polish-Lithuanian union; Sarmatian culture, Antemurale, Polish Messianism and Cordon sanitaire.', null, 3, '{"operator": "AND", "items": ["HIS251Y1"]}'::jsonb),
    ('HIS354H1', 'Jews of Arab Lands: From the Prophet Muhammad to European Colonialism', '24L', 'This course introduces the Jewish communities of Arab lands by examining their social, cultural, and political experiences from the Arab conquests to European colonialism. We will examine the sometimes “symbiotic” relationship that existed between Jews and Muslims as well as the factors that threatened it by considering both the history of everyday life and of high culture. Many of Judaism''s formative institutions and literary works were developed in the Middle East and we will explore how they developed in dialogue with Islamic culture. Finally, we will study the impact of Western colonialism and nineteenth-century encounters between “Western” and “Eastern” Jews.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HIS355H1', 'A History of Pre-modern Medicine', '24L', 'This course surveys major themes and developments in the history of medicine from c.600 BCE to 1800 CE. Topics include: Hippocrates, Galen and their reception in the Middle Ages; monasteries, medicinal gardens and hospitals; medieval licensing of physicians and pharmacists; medieval scholastic medicine; the Black Death; Renaissance anatomy and charlatans; New World drug discoveries; William Harvey''s heart, William Withering''s foxglove, the isolation of morphine.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('HIS356H1', 'War in Canadian History', '24L', 'This course examines war as a major force in the history of Canada from the so-called colonial period to recent times. In addition to key dynamics in military history (e.g. battles, military organization), the course will stress the links between war and society, politics, empire and colonialism, technology and environment, memory and commemoration, and identity. Topics may include indigenous warfare and diplomacy, imperial rivalry in early North America, Canada and the British Empire, the world wars, the Cold War, and peacekeeping. Soldiers and peaceniks are both welcome and will be equally happy and annoyed.', null, 3, null::jsonb),
    ('HIS357Y0', 'The Renaissance', null, null, 'HIS357Y1/ HIS357H1/ HIS357Y5/ HIS357H5', null, null::jsonb),
    ('HIS358H1', 'Canadian History in 100 Objects', '24L', 'The Canadian history course focuses on museums and material culture (history of objects). Using museum visits, lectures, and workshops, students in this course have an opportunity to conduct original research on how artefacts (and the institutions that house them) offer us new ways of thinking about the past.', 'HIS389H1 (Material Culture in Canada)', 3, '{"operator": "OR", "items": ["HIS264H1", "HIS263Y1"]}'::jsonb),
    ('HIS359H1', 'Regional Politics and Radical Movements in the 20th Century Caribbean', '24L', 'The role of nationalism, race and ethnicity, class conflict and ideologies in the recent development of Caribbean societies; Europe''s replacement by the United States as the dominant imperial power in the Caribbean; how this mixture of regional and international pressures has led to widely differing political systems and traditions.', null, 3, null::jsonb),
    ('HIS360H1', 'Critical Histories of the Black Canadian Experience', '24L', 'This course addresses the long and diverse historical experiences of black people in Canada. Each year the course is offered, it will emphasize a specific theme which may include slavery and its afterlife, black liberation and resistance, black geographies, (im)migration, education, black diasporic communities, and black womanhood and gendered politics. Discussions in this course will consider the place of Canada within broader transnational debates about race and blackness. Details regarding specific topics will be available on the department''s website on an annual basis.', 'HIS360Y1', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS361H1', 'The Holocaust, from 1942', '24L/5T', 'Follows on  HIS338H1. Themes include: resistance by Jews and non-Jews; local collaboration; the roles of European governments, the Allies, the churches, and other international organizations; the varieties of Jewish responses. We will also focus on postwar repercussions of the Holocaust in areas such as justice, memory and memorialization, popular culture and politics.', 'HIS338Y1/ HIS361H5', 3, '{"operator": "AND", "items": [{"credits": 6.0, "department": null}, "HIS338H1"]}'::jsonb),
    ('HIS362H1', 'Topics in Early American History', '24L', 'Special topics in Early American History (to 1830). Topics will vary by the instructor and year.', null, 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HIS363H1', 'Dynamics of Gender in Canadian History', '24L', 'A lecture course which deals thematically with gender issues in Canadian history (including familial roles, changing patterns of work and employment, and participation in the public sphere).', null, 3, '{"operator": "OR", "items": ["HIS263Y1", "HIS264H1"]}'::jsonb),
    ('HIS364H1', 'From Revolution to Revolution: Hungary Since 1848', '24L', 'This course offers a chronological survey of the history of Hungary from the 1848 revolution until the present. It is ideal for students with little or no knowledge of Hungarian history but who possess an understanding of the main trends of European history in the 19th and 20th centuries. The focus is on the revolutions of 1848-1849, 1918-1919, the 1956 Revolution against Soviet rule and the collapse of communism in 1989. The story has not been invariably heroic, violent and tragic.', null, 3, null::jsonb),
    ('HIS365H1', 'History of the Great Lakes Region', '24L', 'This course is a survey of the Great Lakes Region as a “trans-national space” from the 1780s to recent times. Attention is focused on the development of the region from indigenous space to industrial heartland and its subsequent deindustrialization. Key themes include economic development, colonialism and re-settlement, environmental history (particularly of the lakes themselves), and the role of the Canada-US border in shaping the region. The course includes material from both Canadian and American history. Considerable attention is paid to Toronto as a Great Lakes city.', null, 3, null::jsonb),
    ('HIS367H1', 'The British Home Front: Britain in the Second World War, 1939-45', '24L', 'This course examines how British civilians responded to the Second World War at home in Britain. Topics include the Blitz, rationing, propaganda, directed labour, enemy internment, evacuees, the changing role of women, radio and movies.', null, 3, null::jsonb),
    ('HIS368H1', 'Early Modern Britain, 1485-1660', '24L', 'Introduction to the political, social and religious history of early modern England, Scotland and Ireland. Particular attention will be paid to the history of the monarchy, the Protestant Reformation, gender issues and relations between different parts of the British Isles.', null, 3, null::jsonb),
    ('HIS370H1', 'Modern Palestine', '24L', 'Weekly lectures provide an overview of the political struggles over Palestine between Zionist and Palestinian national movements in the twentieth century in the context of British colonialism, UN negotiations and resolutions, Third-Worldism, superpower rivalry and everyday cooperation and occupation on the ground.', 'HIS339H1', 3, null::jsonb),
    ('HIS371H1', 'Canadian Political History', '24L', 'This course examines the history of Canadian politics from the late colonial period to the recent past. Lectures and discussions will focus attention on specific political issues (responsible government, Confederation, war, welfare, battles over voting rights, campaigns for social change, etc.) but also consider the deeper structural, social, economic, and cultural dynamics that shaped politics over time. The course takes a broad view of politics (elections and parties but also social movements, interest groups, bureaucracy). A key theme is the nature of political power in a democratic polity.', null, 3, '{"operator": "OR", "items": ["HIS264H1", "HIS263Y1"]}'::jsonb),
    ('HIS372H1', 'Topics in U.S. History', '24L', 'In-depth examination of selected periods or themes in U.S. history. Topic in any given year depends on instructor. See History website for more details.', 'HIS372H5/ HISD36H3', 3, null::jsonb),
    ('HIS373H1', 'Servants and Masters, 1000- 1700', '36L', 'To explore the history of all types of servants, from the domestic slaves to the ladies-in-waiting, in Western Europe between 1000 and 1700. The goal will be to observe their working and living conditions, including the ones of life-cycle servants (between adolescence and early adulthood), as well as the changing perception of service through time.', null, 3, null::jsonb),
    ('HIS374H1', 'Mass Incarceration in the United States', '24L', 'The United States is home to five percent of the world''s population but twenty-five percent of the world''s prisoners, including a disproportionate number of African American, Latinx, and Native American people. This vast carceral archipelago is the subject of extensive scholarly and public debate over the history, ethics, and function of incarceration in the United States. In this course, we will explore the rise of contemporary mass incarceration from an interdisciplinary perspective that draws upon history, sociology, and legal studies to reveal the linkages among state-formation, politics, capitalism, and modern punishment as well as community responses to mass incarceration.', 'HIS389H1 (Topics in History: Mass Incarceration in the United States) offered in Fall 2018, 2019, and 2022.', 3, '{"operator": "OR", "items": ["HIS271Y1", {"operator": "AND", "items": ["HIS221H1", "HIS222H1"]}]}'::jsonb),
    ('HIS375H1', 'Crime and Punishment in the Early Modern World', '36L', 'What did it take to break the law in the period 1400-1800, and how were people prosecuted and punished when they did? We will review the kinds of crimes that triggered arrest, the different types of law codes in place and the importance of the revival of Roman law, ways of avoiding prosecution, the criminalization of “deviance”, judicial processes in colonization, and variations based on age and gender. We''ll also look at forms of punishment, including the varieties of corporal and capital punishment, the operation of prisons, the use of exile and transportation.', 'HIS357Y1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HIS377H1', 'The United States in the World', '24L', 'An exploration of the history of American foreign relations. Each year, this course will emphasize a specific era of the history of American foreign relations (For instance: foreign relations during the Revolution and Early Republic; the long nineteenth century; the rise of American power since 1898); or a specific theme (for instance: America as an imperial power; America at war; the presidency and foreign policy, etc.) Details regarding specific topics will be available on the department''s website on an annual basis.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('HIS378H1', 'America in the 1960s', '24L', 'A survey of one of the most turbulent decades in American history. Examines the political, social, economic and cultural revolutions that transformed the face of America.', null, 3, '{"operator": "AND", "items": ["HIS271Y1"]}'::jsonb),
    ('HIS379H1', 'Vietnam at War', '24L', 'This course examines war in modern Vietnam, beginning with Vietnamese nationalism in the 19th century to the conflicts with France, the United States, and China. We will consider the military, political, economic, and cultural contexts of these complex and interconnected wars, especially from the viewpoint of the Vietnamese people.', 'HIS400H1', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS380H1', 'Chinese Canadian History', '24L', 'Explores histories of Chinese in Canada, and how scholars have researched, interpreted and analyzed them in ethnic, multicultural, transnational and diasporic contexts. Students will be exposed to a wide range of research approaches including: archives, oral history, community studies, visual studies, popular culture, racial-ethnic studies, and food studies. Chinese in Greater Toronto will be a focus.', null, 3, null::jsonb),
    ('HIS381H1', 'Youth in the Early Modern World', '36L', 'Adolescence is a time of adaptation between childhood and adulthood, and it''s often described as a modern invention. This course will look at how people in their teens and twenties navigated social demands and expectations around work, law, education, and marriage in the period 1400-1700. The course will address issues around biology, gender, violence, sexuality, mobility, and forced labour, with attention to comparing experiences between distinct traditions in different parts of the early modern world.', 'HIS357Y1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('HIS382H1', 'China from the Mongols to the Last Emperor', '24L', 'This course traces the history of Chinese empire from its political reorganization, economic expansion, and cultural efflorescence in the 11th century, through its peak of power in the 18th century, and to its decline during the 19th. We will consider how these centuries broke with as well as continued previous developments, and how they have influenced Chinese and world history in the last 150 years.', null, 3, '{"operator": "OR", "items": ["HIS280Y1", "EAS103H1", "EAS209H1"]}'::jsonb),
    ('HIS383Y1', 'Women in African History', '48L', 'This course subjects our increasing knowledge about African women''s history from the mid-19th century to the present to critical analysis. It goes beyond restoring women to history and seeing African women as victims impacted upon and struggling against colonialism and neo-colonialism. It examines how African women''s lived experiences have been represented, packaged, and delivered to different audiences.', 'HIS383H1/ HISC97H3', 3, '{"operator": "OR", "items": ["HIS295Y1", "HIS297Y1", "AFR150Y1", "AFR250Y1", "AFR351Y1", "POL301Y1"]}'::jsonb),
    ('HIS384H1', 'The Baltic Sea Region from the Vikings to the Age of Nationalisms', '24L', 'This course traces political, cultural and socio-economic developments in North-Eastern Europe, the Baltic Sea region, from the Viking Age to the end of the 19th century. Topics include the crusades, the Hanseatic League and trade, the Reformation, the struggle for hegemony between the Swedish and Russian empires, the Enlightenment, national movements, and industrialization.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS386H1', 'Fascism', '24L', 'A comparative and transnational examination of fascist movements and regimes in Europe during 1919-1945. Beginning with Mussolini in Italy and Hitler in Germany, this course analyzes manifestations of the phenomenon in various European countries, including France, Spain, the Baltic states, Central Europe and Scandinavia. We analyze the factors that led to fascist movements obtaining power in certain countries and to their failure in others. Collaboration with Nazi Germany during the Second World War is also explored. Finally, we discuss whether the concept of ''generic'' fascism can also be applied to other regions and periods.', 'HIS389H1 (Topics in History: Fascism), offered in Winter 2018 and Winter 2019', 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS387H1', 'France 1610-1830', '24L', 'This course considers the history of France, from the rise of absolutist monarchy under the seventeenth-century, Bourbon monarchs, through the Enlightenment, the Revolution and Napoleonic Empire, and the Restoration, to the fall of the constitutional monarchy in 1848.', null, 3, null::jsonb),
    ('HIS388H1', 'France Since 1830', '24L', 'A study of French society, politics and culture from 1830 to the present. Special attention is paid to watersheds like the Paris Commune, the Dreyfus Affair and the Vichy regime, to issues of regionalism/nationalism, cultural pluralism, women''s rights, intellectual and cultural trends, and decolonization.', 'HIS388Y1', 3, '{"operator": "AND", "items": ["EUR200Y1"]}'::jsonb),
    ('HIS389H1', 'Topics in History', '24L', 'In-depth examination of historical issues. Content in any given year depends on the instructor and further prerequisites vary from year to year. See History website for more details.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS389Y1', 'Topics in History', '48L', 'In-depth examination of historical issues. Content in any given year depends on instructor. See History website for more details.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS390H1', 'Slavery in Latin America', '24L', 'This course focuses on the history of slavery in Latin America from its origins in the fifteenth century to its abolition in the nineteenth century. Readings will draw from primary sources and historical scholarship related to a range of topics, including the slave trade, gender, religious and cultural practices, and emancipation.', null, 3, '{"operator": "OR", "items": ["HIS231H1", "HIS291H1"]}'::jsonb),
    ('HIS393H1', 'Digital History', '24L', 'Explores implications for history and its methods of the shift from print to digital sources. Imparts introductory skills in the manipulation digital media, such as the use of maps, GIS and big data.', 'HIS389H1 (Topics in History: Digital History), offered in Summer 2015, Winter 2016, and Winter 2017', 3, '{"operator": "OR", "items": ["DHU235H1", "DHU236H1"]}'::jsonb),
    ('HIS394H1', '20th and 21st Century African Icons: Media and Biography', '24L', 'Superseding 19th century European missionary and explorers'' accounts of Africa; media in the 20th and 21st centuries have unequivocally played a key role in shaping the globe''s views of Africa and Africans. In 2005, BBC Focus on Africa put out an impressive list of more than 100 "African Icons". Since then, a number of websites have come up with various lists of African icons. Who are the African icons and what makes them icons? How have the media contributed in making them icons?', null, 3, '{"operator": "OR", "items": ["HIS295Y1", "HIS297Y1", "HIS383H1", "HIS383Y1", "HIS386H1", "HIS481H1", "NEW160Y1", "NEW261Y1", "AFR351Y1", "POL301Y1", "POL361H1"]}'::jsonb),
    ('HIS395H1', 'Independent Studies', null, 'This course provides an opportunity for exceptional third-year students to undertake an independent research project on a topic for which there is not a suitable course offering. Students must find an appropriate supervisor from the Department, submit a proposal, and receive approval for the project. Students must be enrolled in either a History Specialist or Major program; have taken at least 3.0 HIS credits with a B+ average; and have approval of an instructor willing to supervise the project. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 3.0, "department": "HIS"}]}'::jsonb),
    ('HIS395Y1', 'Independent Studies', null, 'This course provides an opportunity for exceptional third-year students to undertake an independent research project on a topic for which there is not a suitable course offering. Students must find an appropriate supervisor from the Department, submit a proposal, and receive approval for the project. Students must be enrolled in either a History Specialist or Major program; have taken at least 3.0 HIS credits with a B+ average; and have approval of an instructor willing to supervise the project. Not eligible for CR/NCR option.', null, null, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 3.0, "department": "HIS"}]}'::jsonb),
    ('HIS396H1', 'The Progressive Era and Rise of Big Business in America', '24L', 'This course examines the rise of big business in America and its relationship to social and economic changes in United States in the so-called Progressive Era (roughly 1880-1920). We will focus on several themes: the evolution and characteristics of big business; rise of organized labor; evolution of business-government relations; social and economic reform movements; and the changing status of immigrants, African Americans, and women (both white and African-American). In short, we will be studying a pivotal moment in the transformation of modern American society.', 'HIS389H1 (Topics in History: Business and Society), offered in Fall 2016 and  HIS372H1 (Topics in U.S. History: The Progressive Era and Rise of Big Business), offered in Winter 2018', 3, null::jsonb),
    ('HIS397H1', 'Political Violence and Human Rights in Latin America', '24L', 'This course will explore human rights theory and practice from a Latin American perspective.  There will be a focus on the local derivation, development and impact of the movement for human rights in Latin America.  The course will focus on the history of organized protest against violence in the twentieth century.', null, 3, '{"operator": "AND", "items": ["HIS292H1"]}'::jsonb),
    ('HIS398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HIS398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HIS399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HIS399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HIS400H1', 'The American War in Vietnam', '24S', 'This course examines the French and American Wars (1945-75) in Vietnam and its effects on the population of Vietnam and Southeast Asia. It begins with a brief overview of pre-colonial Vietnamese history and moves into a study of the impact and legacies of colonial rule and centres on the impact of the Wars on the cultures, economies, and societies of Southeast Asia.', 'HIS315H1', 3, '{"operator": "AND", "items": ["HIS379H1", {"credits": 14.0, "department": null}]}'::jsonb),
    ('HIS401H1', 'The Cold War through its Archives', '24S', 'The course reviews the history of the Cold War in light of formerly-secret archival documents. Examples include the US White House Tapes and Venona decrypts; massive declassification of records in the ex-Soviet bloc; and parallel developments in China, Cuba, and other Communist states. Archival discoveries have cast new light, not just on individual episodes (e.g., Cuban Missile Crisis of 1962, Soviet invasion of Afghanistan in 1979) but on the origins, strategies, and driving forces of this 45-year conflict. The focus will be mainly on the superpowers and their alliance systems.', 'HIS401Y1,  HIS306H5', 3, '{"operator": "OR", "items": ["HIS311Y1", "HIS344H1", "HIS344Y1", "HIS377H1"]}'::jsonb),
    ('HIS402H1', 'Sephardim: The Jews of Spain and their Diasporas', '24S', 'This course follows the journey of Sephardic Jews from their beginnings in Iberia to their diasporas in the Ottoman Empire and the New World. We begin by studying Jewish life and culture in Iberia itself. We then study the expulsion from Spain and Portugal and how Sephardic Jews managed to reconstruct their communities and maintain their identity in new lands until the Nineteenth Century. Themes discussed include mysticism and messianism, conversos and heresy, and trade and exploration. We will conclude by looking at how Sephardic Jews shaped ideas of modernity that were distinct from those of their Ashkenazi coreligionists.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 1.0, "department": "HIS/JHA/JHM/JHN/JIH/JSH"}]}'::jsonb),
    ('HIS403H1', 'Jews and Christians in Medieval and Renaissance Europe', '24S', 'The course focuses on aspects of Jewish-Christian relations ca.300-1600, such as royal and ecclesiastical Jewish policies; religious polemics; intellectual collaboration; social and economic interaction; anti-Judaism and religious violence. (Joint undergraduate-graduate)', 'HIS403Y1', 3, null::jsonb),
    ('HIS404H1', 'Advanced Topics in U.S. History', '24S', 'Selected topics in U.S. history. Topics in any given year depend on the instructor. Please see History website for details.', null, 3, '{"operator": "AND", "items": ["HIS271Y1"]}'::jsonb),
    ('HIS405Y1', 'Canadian Foreign Relations', '48S', 'A course on Canadian external relations since 1945. Topics include Canada and the Cold War, the Korean War, the Suez crisis and the war in Vietnam, membership in international organizations, and bilateral relations with other countries. (Joint undergraduate-graduate)', null, 3, '{"operator": "OR", "items": ["HIS311Y1", "POL312Y1"]}'::jsonb),
    ('HIS406H1', 'Advanced Topics in Gender History', '24S', 'An in-depth examination of issues in gender history. Content in any given year depends on instructor. See History website for more details.', null, 3, null::jsonb),
    ('HIS407H1', 'Imperial Germany, 1871-1918', '24S', 'Historiographical controversies and the latest empirical findings concerning social conflict and political mobilization under Bismarck and Wilhelm II. Problems raised by competing schools of interpretation include definitions of the authoritarian state, bourgeois hegemony, localism and regionalism, radical nationalism, workers'' culture, and gender relations. (Joint undergraduate-graduate)', 'HIS407H5', 3, '{"operator": "AND", "items": ["HIS317H1", "HIS330H1"]}'::jsonb),
    ('HIS408H1', 'Topics in Environmental History', '24S', 'This advanced undergraduate seminar will explore themes in environmental history. Thematic focus will vary from year to year, and may include extinction, nuclear power in environmental history, empire and environment, toxicity and contamination, climate change, the Columbian exchange, the Anthropocene, agriculture, animals, and/or other themes. Time period and geographical focus will also vary in keeping with the thematic focus of this course.', null, 3, '{"operator": "OR", "items": ["HIS218H1", "HPS316H1"]}'::jsonb),
    ('HIS409H1', 'Spas and Water Cures', '24S', 'This fourth-year seminar immerses students into the rich world of mineral water cures. It explores the relationship between the medical sciences and society, and the connections between prescriptive and normalizing medical rituals and sites of pilgrimage, capitalism, and sociability. The seminar will also focus on shifting medical meanings, on gender dynamics at these sites, and on uses and practices surrounding hot water springs, as well as varied experiences of spa towns as sites of leisure and tourism. The course is transnational and features case studies in Mexico, Madagascar, Britain, Germany, Tunisia, Japan, France, Austria, Hungary, Greece, and Canada.', null, 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": "HIS"}]}'::jsonb),
    ('HIS410H1', 'The Mongol Century', '24S', 'This course traces the emergence, expansion, consolidation, and fragmentation of the medieval empire of the Mongols through translated primary sources produced by those conquered by and in contact with the empire (Chinese, Islamic, European) and the conquerors (Mongolian). Topics include the life of Chinggis (Genghis) Khan, medieval Eurasian geopolitics and society, Mongol administration of China and Persia, military strategies and technology, the role of religion in imperial administration, cross-cultural encounter and exchange, and the legacy of the Mongols in the world.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 2.0, "department": "HIS"}]}'::jsonb),
    ('HIS411H1', 'Great Trials in History', '24S', 'This seminar course will study a handful of great trials in close detail. Using materials from the modern period in Europe and North America, we will look at the clash of ideas represented in these high-profile cases, the historical setting in which they were embedded, the human drama, legal and sometimes constitutional issues, and their impact both on their societies and our own.', null, 3, null::jsonb),
    ('HIS413H1', 'Slave Emancipation in the Atlantic World', '24S', 'This course explores the long process of the ''unfinished revolution'' of abolition in the Atlantic World from the 18th-late 19th century Atlantic World. It will take a comparative and transnational approach, with materials that include primary printed sources, classic texts, current historiography, literature, explorations of the history of emancipation through digital and visual culture. We will examine scholarship and historical debates about abolition in the Caribbean, North and South America, West Europe and Africa.', null, 3, '{"operator": "AND", "items": [{"credits": 0.5, "department": null}, {"operator": "OR", "items": ["HIS221H1", "HIS230H1", "HIS231H1", "HIS244H1", "HIS245H1", "HIS265Y1", "HIS271Y1", "HIS291H1", "HIS295Y1", "HIS357Y1", "HIS373H1"]}]}'::jsonb),
    ('HIS414H1', 'Down and Out in Medieval Europe', '24S', 'Explores the life conditions of individuals on the lower echelons of medieval society (the poor, servants and apprentices, the exiled, prisoners, slaves, foreigners and lepers). In parallel, we will discuss the various conceptions of poverty that prevailed in the Middle Ages. These objectives will allow us to glimpse the European Middle Ages from an unusual angle as well as reflect on important socio-economic and religious changes.', null, 3, null::jsonb),
    ('HIS415Y1', 'Nationalism & Memory in Modern Europe', '48S', 'Investigates the modern concept of the nation and its connections to the idea of collective memory in twentieth-century Europe. Through reading and discussing seminal works on nationalism and national memory, we will discuss the connections between modern notions of nation and practices of remembering.', 'HIS415H1', 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": null}, {"operator": "OR", "items": ["HIS102Y1", "HIS103Y1", "HIS109Y1", "HIS241H1", "HIS242H1", "HIS243H1", "HIS244H1", "HIS245H1", "EUR200Y1", "HIS317H1"]}]}'::jsonb),
    ('HIS416H1', 'Orientalism and Nationalism in Nineteenth-Century Germany', '24S', 'In 1771, with the translation of the Zend-Avesta by the French Scholar Anquetil-Duperron, a new era opened in German national culture. From the philosophy of Johann Gottfried von Herder to the novels of Thomas Mann, this course analyzes the ways in which German writers defined the substance and place of national culture in their writings about India, Central Asia and the East.', null, 3, '{"operator": "AND", "items": ["HIS241H1", {"operator": "OR", "items": ["HIS242H1", "HIS317H1"]}]}'::jsonb),
    ('HIS417H1', 'Sex Work History in North America, 1763 onwards', '24S', 'This seminar explores the historical effects of the "world''s oldest profession" in Canada and beyond. Using a range of texts, including film, memoirs, oral history and visual culture, it seeks to enhance both historical and contemporary discussions of the sex trade by examining its rich, difficult and problematic pasts. Seminar readings and discussions will examine the lives and experiences of multiple sex trade-involved populations, from affluent 19th-century madams to streetwalkers and queer and trans communities.', 'HIS417Y1', 3, '{"operator": "OR", "items": ["HIS263Y1", "HIS264H1"]}'::jsonb),
    ('HIS418H1', 'Themes in Canadian Environmental History', '24S', 'Environmental historians study the reciprocal relationship between humans and nature over time. This course examines key themes in the history of Canada''s environment. Possible topics include food, energy, pollution, cities, parks, and environmental movements. Specific themes vary by year, depending on the focus of the instructor. Strong emphasis is place on reading and research.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('HIS419H1', 'Canada By Treaty: Alliances, Title Transfers and Land Claims', '24S', 'A detailed study of the treaty process between indigenous peoples and newcomers in Canadian history, with examination of the shift between alliance treaties to land surrender agreements from the colonial period through to the signing of recent treaties including the Nunavut Land Claims Agreement and the Nisga''a Final Agreement.', null, 3, '{"operator": "OR", "items": ["HIS263Y1", "HIS264H1"]}'::jsonb),
    ('HIS421H1', 'Oral History', '24S', 'Exploration of oral history interview research methods, their contributions to the History field, and practical training in the skills and art of doing oral history. This is a research workshop course, oriented to developing student research projects, and each student will do oral history research. Topics include: memory, interviewing, ethics, interpreting oral testimonies and issues in community-engaged research.', null, 3, null::jsonb),
    ('HIS422H1', 'Early Modern English Popular Culture, 1500-1800', '24S', 'Deals with issues of orality, literacy, gender, class, cultural bricolage and vernacular epistemology – the constituents of popular, as opposed to elite knowledge - through the study of folklore, magic, religion, drink, sex, riot and festivity in early modern England. Some background in medieval and/or early modern history or literature is highly recommended. Extensive work will be undertaken with primary printed sources.', 'HIS496H1 (Topics in History: Early Modern English Popular Culture, 1600-1800), offered in Summer 2018', 3, '{"operator": "OR", "items": ["HIS101Y1", "HIS109Y1", "HIS220Y1", "HIS243H1", "HIS244H1", "HIS368H1", "HIS337H1", "HIS349H1", "HIS357Y1"]}'::jsonb),
    ('HIS423H1', 'Social History of Medicine in the 19th & 20th Centuries', '24S', 'Introduces students to current issues in the social history of medicine and some of the major developments in the modern history of the discipline. The format is class discussion based on themes covered in the course textbook, covering such topics as the history of the doctor-patient relationship, changes in physicians'' social status, changing attitudes toward the body, and the evolution of various medical and surgical specialties including obstetrics and gynecology. (Joint undergraduate-graduate).', 'HIS423Y1', 3, null::jsonb),
    ('HIS424H1', 'Violence in Medieval Society', '24S', 'This seminar explores the social function and meaning of violence in medieval society, and the development of rituals and institutions to control violence. Among the topics treated: Germanic blood feud, aristocratic violence and chivalry, criminal justice systems, violence against minorities, and violence and gender. (Joint undergraduate-graduate)', 'HIS327Y5', 3, '{"operator": "OR", "items": ["HIS220Y1", "HIS320H1", "HIS321H1", "HIS322H1"]}'::jsonb),
    ('HIS425H1', 'From the Weimar Republic to Nazi Germany: How Do Democracies Die?', '24S', 'This seminar on Weimar and National Socialist Germany analyzes the advent of the country''s first democracy after WWI, its destruction between 1929 and 1933 and the subsequent building of the National Socialist dictatorship. How does the destruction of Germany''s first democratic republic provide a map for how democracies die? What lessons can Germany''s history provide for the current political moment? In analyzing the country''s movement from democracy to dictatorship an interdisciplinary variety of texts will be studied, covering topics from political violence and economic instability, to the languages of civil society and the importance of trust in a democratic polity.', 'HIS496H1 (offered as "Weimar and Nazi Germany: How do Democracies Die?") taken in Fall 2019, 2022.', 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 2.0, "department": "HIS"}]}'::jsonb),
    ('HIS426H1', 'Early Medieval Italy 300-1000 CE', '24S', 'This seminar examines major developments in Italy 300-1000, including the Christianization of Italy, the collapse of Roman rule, the establishment of several barbarian successor kingdoms, and changes in architecture, art and literature in a period known as Italy''s Dark Ages.', null, 3, null::jsonb),
    ('HIS427H1', 'History and Historiography in the Golden Legend', '24S', 'The Golden Legend or Readings on the Saints, compiled by Jacobus de Voragine C. 1260, serves as the basis for a seminar on the relation of history and legend as understood in the High Middle Ages. (Joint undergraduate-graduate)', null, 3, '{"operator": "AND", "items": ["HIS220Y1"]}'::jsonb),
    ('HIS428H1', 'Medieval Institutes of Perfection', '24S', 'The first goal of this seminar is to help students read complex primary sources with a more critical eye, especially narrative sources (Lives of Saints) and "normative" sources (rules and customaries). The second goal is to study the evolution of the monastic ideal from its origin to the 12th century. (Joint undergraduate-graduate)', null, 3, '{"operator": "AND", "items": ["HIS220Y1"]}'::jsonb),
    ('HIS430H1', 'The Two Germanies and the Cold War, 1949-1989', '24S', 'This course explores central themes of the field of postwar German and Cold War history from national, European and global history perspectives. It familiarizes students with significant events, texts, dates and actors in its analysis of the histories of the two postwar German states and explores German history as a microcosm of Cold War relations. In analyzing the two Germanies after 1949 an interdisciplinary variety of texts will be studied, covering topics from diplomacy and economy, to gender, memory, politics and geopolitics.', 'HIS496H1 (offered as "The Two Germanies and the Cold War, 1949-1990") taken in Winter 2019, (offered as "The Two Germanies and the Cold War") taken in Fall 2020.', 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 2.0, "department": "HIS"}]}'::jsonb),
    ('HIS431H1', 'Historical Memory and Transitional Justice in Latin America', '24S', 'Transitional justice encompasses a broad range of experiences, including amnesties, peace agreements, memorial building, and criminal prosecutions, as well as truth and reconciliation commissions. Enthusiasm for transitional justice is understandable, and critical reflection on the politics of memory is imperative. In what ways has memory in Latin America been mobilized by various groups to confront serious violations of human rights? We will address the connections between memory, accountability and social reconstruction, and each student will be asked to write a research paper on a case study or topic of their choice.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 2.0, "department": "HIS/JHA/JHM/JHN/JIH/JSH"}]}'::jsonb),
    ('HIS432H1', 'Advanced Topics in Medieval History', '24S', 'The students define together with the professor eight different topics (e.g. relics, masculinity, leprosy, clothes, recluses, peasants houses, gynecology and the peace of God). Each topic is approached through a class discussion, on the basis of a common corpus of secondary sources, plus presentations by the students.', null, 3, '{"operator": "AND", "items": ["HIS220Y1"]}'::jsonb),
    ('HIS433H1', 'Polish Jews Since the Partition of Poland', '24S', 'To explore the history of Polish Jews from the Partitions of Poland to the present time, concentrating on the 19th and the first half of the 20th centuries: situation of Polish Jews in Galicia; Congress Kingdom of Poland; Prussian-occupied Poland before 1914; during World War II; and post-war Poland. Focus on an analysis of primary sources. (Joint undergraduate-graduate)', null, 3, '{"operator": "OR", "items": ["HIS208Y1", "HIS251Y1"]}'::jsonb),
    ('HIS434Y1', 'Kievan Rus', '48S', 'The origin of Rus, international trade, the impact of nomadic peoples, the introduction of Christianity, the economic system an the problem of feudalism, the political structure and the dilemma of princely succession; literature and architecture; the displacement of political power centres and depopulation, the preservation of the Kievan heritage. (Joint undergraduate-graduate)', null, 3, '{"operator": "OR", "items": ["HIS220Y1", "HIS250H1", "HIS250Y1", "HIS320H1", "HIS321H1", "HIS322H1"]}'::jsonb),
    ('HIS435H1', 'Themes in Toronto History', '24S', 'This course will examine aspects of Toronto''s history. It is not a general survey of Toronto history; instead, the course will normally revolve around a specific theme or group of themes. Specific themes vary by year, depending on the focus of the instructor. Strong emphasis will be placed on reading and research.', null, 3, '{"operator": "OR", "items": ["HIS263Y1", "HIS264H1"]}'::jsonb),
    ('HIS436H1', 'Stalinist Terror', '24S', 'This research seminar explores topics and issues of violence in the Soviet Union in the 1930s, beginning with forced collectivization and ending with the Great Terror. The seminar focuses on new archivally-based research and aims to contextualize Stalinist terror within larger theories of political and social violence.', null, 3, '{"operator": "OR", "items": ["HIS250Y1", "HIS351Y1"]}'::jsonb),
    ('HIS438H1', 'Inquisition and Society in Medieval and Early Modern Europe', '24S', 'Focusing on the institution of the inquisition, this seminar explores the response of ecclesiastical and secular authorities to religious heterodoxy. Among the groups prosecuted by the inquisition discussed: Cathar heretics in France, crypto-Jews and crypto-Muslims in Spain, and witches in Italy.', null, 3, null::jsonb),
    ('HIS439H1', 'Russia''s Empire', '24S', 'The collapse of the Soviet Union along national lines brought about a renewed interest in the non- Russian parts of the Imperial Russian state. This so-called “imperial turn” has altered the ways that we think about Tsarist Russian rule. In this course we address different approaches to the study of Empire as reflected in the Russian case from its origins in the sixteenth century until the collapse of the Tsarist state — but not precisely of its empire — in 1917.', null, 3, '{"operator": "AND", "items": ["HIS325H1", "HIS351H1"]}'::jsonb),
    ('HIS440H1', 'Maps and History', '24S', 'Examines the use of maps through the ages to depict spatial relationships and political, social, or cultural authority. Explores the visual display of quantitative information, the evolution of historical atlases, and cartographic crime. Such topics as Lebensraum and gerrymandering illustrate how maps can distort historical processes and communal relationships.', null, 3, null::jsonb),
    ('HIS442H1', 'Jews and the Holocaust in the Soviet Union', '24S', 'This course is an advanced research seminar in Soviet history. It will explore the Jewish experience in the Soviet Union, with a focus on the Holocaust. The seminar will begin with an examination of the history of Jews in the Russian Empire and the Soviet Union in the years leading up to the Second World War. Then the course will pivot directly to the topic of the Holocaust on Soviet soil. How did the Holocaust in the “east” differ from the Holocaust in the “west”? How did the conduct of war condition genocide in the Soviet Union? How did Soviet Jews and non-Jews respond to the German genocide? What was the response of Stalin and the Soviet government to the Holocaust? How is the Holocaust remembered by the states and people of the former Soviet Union.', null, 3, '{"operator": "AND", "items": ["HIS351Y1"]}'::jsonb),
    ('HIS443H1', 'Space and Sense in the Early Modern World', '24S', 'How did early moderns experience sense and space and how did the expanding cultural, political, and social horizons of the period emerge from and shape those experiences? This course explores Florence, Amsterdam, Boston, Manila to compare how experiences of space and sense varied by age, gender, race, and class.', null, 3, '{"operator": "OR", "items": ["HIS243H1", "HIS244H1", "HIS357Y1"]}'::jsonb),
    ('HIS444H1', 'Advanced Topics in Jewish History', '24S', 'Selected topics on a specific period or theme in Jewish history. Topic in any given year will depend on the instructor. Please see History website for details.', null, 3, null::jsonb),
    ('HIS445H1', 'Nationalism', '24S', 'What is a nation? Are nations ancient or modern, unchanging or malleable? Do nations create states, or does the state create the nation? This course seeks to answer these questions through an examination of nationalism, primarily in Europe, from the 1700s through the present.', null, 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": "HIS"}]}'::jsonb),
    ('HIS446H1', 'Gender and Slavery in the Atlantic World', '24S', 'The course examines the relationship between gender and the experience of slavery and emancipating several Atlantic world societies from the 17th-19th centuries. Areas to be covered are the Caribbean, Brazil, the U.S. South, West and South Africa and Western Europe.', 'HIS446Y1', 3, '{"operator": "OR", "items": ["HIS291H1", "HIS294Y1", {"operator": "AND", "items": ["HIS230H1", "HIS231H1"]}, "HIS295Y1"]}'::jsonb),
    ('HIS447H1', 'Globalization and Empire', '24S', 'What is globalization? What is empire? What are the relationships between them? Globalization, one of the most widely-used concepts today, is often taken out of the historical contexts out of which it arose. This course analyzes its connections with European imperial projects (British, French, German and Russian) of "world making" and the types of connections--economic, political and cultural--that they fostered. The connections between globalization, the forging of the world economy and the histories of capitalism are a central focus of the course. The goal is to seek to understand the types of globalization active today, including the creation of a world based on global inequality and environmental degradation in which older colonial relationships of power (vis a vis the global south, for example) continue to hold sway. In other words, through a historical analysis of globalization and empire the course explores processes of economic and political transformation that created the modern present. Methodologically the course is an introduction to the field(s) of transnational and global history.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('HIS449Y1', 'Ukrainian National Revival', '48S', 'The role of the intelligentsia in East European national revivals; the ethnographic and literary revival; the language question; the press and cultural organizations; education; religion; and political movements. (Joint undergraduate-graduate)', null, 3, null::jsonb),
    ('HIS450H1', 'Advanced Topics in African Histories', '24S', 'Senior seminar discussing readings on a specific period, aspect or themes in African history. Topics in any given year depend on the instructor.', null, 3, '{"operator": "OR", "items": ["HIS295Y1", {"credits": 1.0, "department": null}]}'::jsonb),
    ('HIS451H1', 'World War II in East Central Europe', '24S', 'The fall of the Versailles system, German and Soviet diplomatic and military activities and their occupational policies in East Central Europe during World War II, economic exploitation, collaboration, resistance, and genocide in the discussed region, its liberation and sovietization in 1944-1945. (Joint undergraduate-graduate)', null, 3, '{"operator": "OR", "items": ["EUR200Y1", "HIS251Y1", "HIS334H1"]}'::jsonb),
    ('HIS452H1', 'Advanced Topics in European History', '24S', 'Selected topics in a specific period of European History. Content in any given year depends on instructor. Please see the History Department website for complete description.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["HIS241H1", "HIS242H1", "HIS243H1", "HIS244H1"]}, {"credits": 1.0, "department": "HIS"}]}'::jsonb),
    ('HIS453H1', 'Slavery in North America', '24S', 'Slavery has existed in many human societies. Beginning in the sixteenth century, European empires pioneered a novel system of racialized chattel slavery that ensnared unknown numbers of Indigenous people and spurred the transportation of millions of African captives to various plantation zones in the Americas. This course examines the history of slavery in North America, Canada, and the United States (c. 1500-1865). Topics include Indigenous and Atlantic slaveries; slavery and the rise of British, French, and Spanish colonialism in North America; racial formation; the Atlantic and domestic slave trades; gender and reproduction; enslaved people''s politics and social worlds; and the gradual abolition of slavery in the United States and Canada (1780-1865).', 'HIS404H1 (Senior Seminar in U.S. History: American Slavery) offered in Winter 2021 and  HIS404H1 (Senior Seminar in U.S. History: Slavery in North America) offered Winter 2023.', 3, '{"operator": "OR", "items": ["HIS271Y1", {"operator": "AND", "items": ["HIS221H1", "HIS222H1"]}]}'::jsonb),
    ('HIS455Y1', 'Hacking History: Digital Projects Capstone Class', '48S', 'This course provides a unique opportunity to grapple with the challenges of public history, while exploring new methods and technologies in the digital humanities. Each year, we partner with one or more community groups to create historical websites which endure well beyond the school year. Topics vary annually.', null, 3, '{"operator": "AND", "items": ["HIS393H1"]}'::jsonb),
    ('HIS457H1', 'The French Revolution and the Napoleonic Empire', '24S', 'Explores the central themes in the history of the French Revolution: the causes of the Revolution; the contested varied efforts to build a new regime; the invention of a novel republican political culture; counterrevolution and Terror; the Haitian Revolution; Napoleon and the Empire; the Revolution as a global phenomenon; the Restoration; the Revolution''s legacy today.', 'HISC26H3', 3, '{"operator": "OR", "items": ["HIS243H1", "HIS244H1", "HIS319H1", "HIS341Y1", "HIS387H1"]}'::jsonb),
    ('HIS459H1', 'Soviet History and Film, 1921-1946', '24S', 'The history of Soviet cinema and the importance of film as a historical source. Documentary and fiction film; editing, narration, and sound; film distribution and exhibition; the Soviet school of montage and socialist realism; nationality and gender; the Soviet musical comedy of the Stalin era; resistance and dissidence.', 'HIS450Y1/ SLA233H1/ SLA234H1', 1, '{"operator": "OR", "items": ["CIN105Y1", "HIS250Y1", "HIS250H1", "HIS335H1"]}'::jsonb),
    ('HIS460H1', 'Soviet History and Film, 1941-1991', '24S', 'Soviet film as a historical source and the institutional and ideological history of Soviet film production, distribution, and exhibition. Fiction and documentary film during World War II; the cinema of the Cold War and the Thaw; Soviet new realism and the return of the village; avant-garde cinema of the 1960s-80s; memory and historical revision in late Soviet film. Screenings include never-before-seen archival footage, as well as films and film clips subtitled by the instructor.', 'HIS450Y1/ SLA233H1/ SLA234H1', 1, '{"operator": "OR", "items": ["CIN105Y1", "HIS250Y1", "HIS335H1"]}'::jsonb),
    ('HIS461H1', 'Poland in the 20th Century', '24S', 'The 20th century has been an age of experiments for Poland. Universal, general problems of democracy, authoritarianism, totalitarianism, communism, socialism, free market and centrally planned economies, are examined, as are the ongoing adjustments made by the Polish people. (Joint undergraduate-graduate)', null, 3, '{"operator": "OR", "items": ["HIS334H1", "HIS353Y1"]}'::jsonb),
    ('HIS464H1', 'Religion and Violence in Comparative Perspective', '24S', 'Examines varying roles of religion in cases of genocide and extreme violence. Seminar proceeds from recent cases (Darfur, Rwanda, wars associated with break-up of Yugoslavia) backward through the 20th century (Cambodia, Indonesia, the Holocaust, Armenians, Herero) and the 19th century (Belgian Congo, Caucasus, native peoples in the Americas).', null, 3, null::jsonb),
    ('HIS465H1', 'Gender and International Relations', '24S', 'This seminar explores the use of gender as a category of analysis in the study of international relations. Topics include gendered imagery and language in foreign policymaking; beliefs about women''s relationship to war and peace; issues of gender, sexuality, and the military; gender and global governance; gender and the global economy; sexual violence; and contributions of feminist theory to international relations theory.', null, 2, null::jsonb),
    ('HIS466H1', 'Advanced Topics in Canadian History', '24S', 'Selected topics in a specific period of Canadian history. Content in any given year depends on instructor. Please see the History Department website for complete description.', null, 3, '{"operator": "OR", "items": ["HIS263Y1", "HIS264H1"]}'::jsonb),
    ('HIS467H1', 'French Colonial Indochina: History, Cultures, Texts, Film', '24S', 'Examines French colonial Indochina through several different lenses. Themes include the cross-cultural contact zones between colonial and colonized societies, imperial culture, expressions of colonial power, and forms of opposition. Colonial novels, translated resistance literature, documentaries, and films are utilized as primary sources to be examined critically.', 'HIS467Y1', 3, '{"operator": "OR", "items": ["ANT344Y1", "EAS204Y1", "GGR342H1", "HIS104Y1", "HIS107Y1", "HIS280Y1", "HIS283Y1", "HIS284Y1", "HIS315H1", "HIS388H1", "NEW369Y1"]}'::jsonb),
    ('HIS468H1', 'Commemorations and Public History in Canada, 1800-2000', '24S', 'This course explores selected topics in the history of commemoration, public memory, and public history in Canada. Remembering the past has often involved various groups - political, economic, and social elites - who have attempted to create ''pasts'' or ''traditions'' for themselves and others in society, often as part of creating socio-economic and political hegemony. We also will read about their contestation by women, working-class people, and ethnic and racialized groups to counter the powerful''s apparent monopoly on public memory. As well, we will explore how historical memories have shaped and created landscapes, in ways both discursive and material.', 'HIS466H1 (offered as "History of Commemoration in Canada") taken in Winter 2015, Fall 2016 or 2018, (offered as "Commemorations and Public History, Canada, 1800s-2000") taken in Fall 2020 or 2021, (offered as "Commemoration in Canada") taken in Fall 2022.', 3, '{"operator": "AND", "items": ["HIS264H1"]}'::jsonb),
    ('HIS469H1', 'Upper Canada:  Creating a Settler Society, 1790s-1860s', '24S', 'This course explores selected topics in the history of Upper Canada: its formation in the crucible of transatlantic and imperial warfare, relationships with Indigenous people, the creation of multiple institutions, and colonial leisure and culture. As well as having its own particular local characteristics and features, not least its proximity to the United States, Upper Canada was one of a number of settler societies within the British Empire. The course explores various dimensions of these aspects and considers the relationships between local dynamics and imperial currents.', 'HIS466H1 (offered as "Upper Canada: Creating a Settler Society") taken in Fall 2014, Winter 2016, 2017, 2019, 2022 or 2023, (offered as "Upper Canada") taken in Fall 2019, (offered as "Upper Canada: Creating a Settler Society, 1790s-1860s") taken in Winter 2021.', 3, '{"operator": "OR", "items": ["HIS264H1", "HIS263Y1"]}'::jsonb),
    ('HIS470H1', 'History, Rights, and Difference in South Asia', '24S', 'Addressing South Asian history after 1750, this course examines ideas of rights, contract, and the rule of law in colonial and postcolonial contexts. Attention is paid to the intellectual history of rights and the central place of colonial and postcolonial questions within that history. Topics include rights and questions concerning indigenous culture, caste and customary practice, gender and capitalist development.', null, 3, '{"operator": "AND", "items": ["HIS282Y1"]}'::jsonb),
    ('HIS474H1', 'Emancipate Yourselves from Mental Slavery? Historical Narratives of Caribbean Decolonization', '24S', 'This course is a critical intellectual history of Caribbean decolonization. It begins with the Haitian Revolution, exploring and comparing how history was mobilized to structure anti-colonial theories about the making of postcolonial Caribbean societies. Key conceptual frameworks to be examined include indigenism, noirism, creolization, métissage; Caribbean interpretations of Marxism, Negritude and Pan-Africanism.', null, 3, '{"operator": "OR", "items": ["HIS294Y1", {"operator": "AND", "items": ["HIS230H1", "HIS231H1"]}]}'::jsonb),
    ('HIS475H1', 'Senior Research Seminar', '24S', 'In this seminar, students will learn the historical methodology skills required to undertake their major independent research project for future professional use or graduate studies, including the development of a topic, formal literature reviews, and the writing of research and grant proposals. History Specialists & Majors only (priority enrollment for Specialists). Not eligible for CR/NCR option. See department website for prerequisite details and registration instructions. Students may count  HIS475H1 towards the Specialty methodology pathway or carry on to  HIS476H1: Senior Thesis.', 'HIS498H1,  HIS499Y1,  HIS476Y1,  HIS491Y1', 3, null::jsonb),
    ('HIS476H1', 'Senior Thesis Seminar', '24S', 'Students research and write a primary-sourced based thesis of approximately 7,000 words, building on the prospectus and literature review developed in  HIS475H1. Students attend seminar meetings to discuss the hypotheses they have formulated, present their work in progress and engage in constructive critique of other students'' work. History Specialists & Majors only (priority enrollment for Specialists). Students must find topics and thesis supervisors. Not eligible for CR/NCR option. See department website for prerequisite details and registration instructions.', 'HIS476Y1,  HIS498H1,  HIS499Y1,  HIS491Y1', 3, '{"operator": "AND", "items": ["HIS475H1"]}'::jsonb),
    ('HIS477H1', 'Topics in the Social and Cultural History of Victorian Britain', '24S', 'Examination of the impact of industrialism on Victorian society and values. Concentration on Victorian social critics including Engels, Owen, Mayhew, Dickens and Morris.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 1.0, "department": "History"}]}'::jsonb),
    ('HIS479H1', 'US Foreign Policy Since World War II', '24S', 'An in-depth study of U.S. behaviour in the global arena since World War II. Particular attention will be paid to the origins and evolution of the Cold War, the Vietnam War, the initiatives of the Nixon-Kissinger years, the end of the Cold War, and the relevance of globalization.', null, 3, '{"operator": "OR", "items": ["HIS271Y1", "HIS377H1"]}'::jsonb),
    ('HIS480H1', 'Modernity and its Others: History and Postcolonial Critique', '24S', 'Engaging with influential perspectives in postcolonial historiography, this seminar tracks three major themes in the history of the idea of modernity from the late 18th through the 20th centuries: political freedom, citizenship and the nation-state; capitalism and its critique; and the relationship of history, memory, and identity. (Joint undergraduate-graduate)', null, 3, '{"operator": "AND", "items": ["HIS282Y1", "HIS470H1"]}'::jsonb),
    ('HIS481H1', 'Elite Women, Power, and Modernity in Twentieth-Century Africa', '24S', 'The role of elite women in twentieth-century Africa has been overshadowed by studies of non-elite women so much so as to suggest that all women lacked power. This course aims to show how a very limited but important group of women negotiated power in a century of increasing patriarchy. It combines gender with class analysis.', null, 3, null::jsonb),
    ('HIS483H1', 'Space and Power in Modern Africa', '24S', 'This course examines the production, experience, and politics of space in modern Africa from a historical perspective. How is space - local, national, and imperial - produced? In what ways does power inscribe these spaces? This course will explore these questions through a variety of readings examining historical examples and cases from across the continent.', null, 3, '{"operator": "OR", "items": ["HIS319H1", "AFR290H1", "AFR370H1"]}'::jsonb),
    ('HIS484H1', 'The Car in North American History', '24S', 'This seminar examines the history of the car in North America from the perspective of technology, business, landscape and popular culture. Particular attention is paid to issues of production, consumption, geography, and daily life, and to the importance of class race, gender, region, and age in shaping the meaning and experience of car culture.', null, 3, '{"operator": "OR", "items": ["HIS263Y1", "HIS264H1", "HIS271Y1"]}'::jsonb),
    ('HIS485H1', 'Advanced Topics in Asian Histories', '24S', 'A seminar on selected aspects of Asian history from 1368 to the present. Please see History website for detailed description of topic in any given year.', null, 3, '{"operator": "OR", "items": ["EAS102Y1", "HIS280Y1", "JMC201Y1"]}'::jsonb),
    ('HIS487H1', 'Animal and Human Rights in Anglo-American Culture', '24S', 'Examines the parallel discourses of animal and human rights in Anglo-American culture from the eighteenth century to the present. The courses explores issues of subjectivity and consciousness as well as cruelty and pain. Topics include slavery and abolition, animal welfare and antivivisection, anti-colonial liberation movements, and animal rights campaigns.', null, 3, null::jsonb),
    ('HIS488H1', 'Advanced Topics in Latin American Histories', '24S', 'A seminar course in which students engage in advanced reading and discussion of topics, themes, periods or problems in some aspect of Latin American history. The focus in any given year will depend upon the instructor offering the course. Students should have existing coursework in Latin American History. Please see the History Department website for complete description and course specific recommended preparation.', null, 3, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"operator": "OR", "items": ["HIS291H1", "HIS292H1"]}]}'::jsonb),
    ('HIS489H1', 'The History of Psychiatry and Psychiatric Illness', '24S', 'Introduces students to current issues in the history of psychiatry and some of the major developments in the evolution of this unique medical specialty. the format is class discussion based on themes covered in the course textbook, covering such topics as changing perspectives on the nature of psychotic illness, the psychoneuroses, disorders of the mind/body relationship, psychiatric diagnosis, and presentations of illness. (Joint undergraduate-graduate).', 'HIS423Y1', 3, null::jsonb),
    ('HIS490H1', 'Everyday Stalinism', '24S', 'This seminar explores issues of everyday life in Soviet Russia during the Stalin era. What was the Soviet normal? Topics will include belief systems, dreams and myths, terror, fear, repression, and resistance. Texts include a range of different sources, memoirs, diaries, official state documents, and secondary sources.', null, 3, null::jsonb),
    ('HIS491Y1', 'Senior Thesis', '48S', 'Students research and write a primary-sourced based thesis of approximately 7,000 words. They attend seminar to provide training in reviewing literature, writing research proposals, formulating hypotheses, oral presentation of findings and constructive critique of other students work. History Specialists & Majors only (priority enrollment for Specialists). Students must find topics and thesis supervisors. Not eligible for CR/NCR option. See department website for prerequisite details and registration instructions.', 'HIS476Y1,  HIS498H1,  HIS499Y1', 3, null::jsonb),
    ('HIS492H1', 'Empire & Colonization in the French Atlantic World', '24S', 'The first French empire (1604-1791) is typically considered a failed empire. Beginning with the first French exploratory expeditions in the South Atlantic in the mid-16th century, this course examines the social, economic and political history of French imperial expansion during the Ancien régime in order to consider the meaning of success, as applied to empire during this period. The focus is on the development of the two colonial centres of the French New World: New France and the French Caribbean.', null, 3, '{"operator": "OR", "items": ["HIS244H1", "HIS294Y1", {"operator": "AND", "items": ["HIS230H1", "HIS231H1"]}]}'::jsonb),
    ('HIS493H1', 'Humanity in War: The Modern Evolution of the Law of Armed Conflict', '24S', 'This course explores the development of international humanitarian law over the course of the nineteenth and twentieth centuries. Questions asked will include how modern warfare has been understood as a political, cultural, social and legal phenomenon, and the ways in which such perspectives developed into a program of restraint.', null, 3, '{"operator": "OR", "items": ["HIS241H1", "HIS242H1", "HIS344H1", "HIS344Y1", "EUR200Y1"]}'::jsonb),
    ('HIS494H1', 'Gandhi''s Global Conversations', '24S', 'Primary source analysis of global circuits of ethico-political thought via work and life of Gandhi.  Charts transnational environment of Gandhian thought (eg. Ruskin and Tolstoy), its critics (advocates of minority rights, also revolutionary violence) and global afterlife (eg. King, Mandela).  Teaches methods in intellectual and political history of the global.', null, null, '{"operator": "AND", "items": ["HIS282Y1"]}'::jsonb),
    ('HIS495H1', 'Advanced Topics in History', '24S', 'An in-depth examination of historical issues. Content in any given year depends on instructor. See History website for more details.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 2.0, "department": "HIS"}]}'::jsonb),
    ('HIS495Y1', 'Advanced Topics in History', '48S', 'An in-depth examination of historical issues. Content in any given year depends on instructor. See History website for more details.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 2.0, "department": "HIS"}]}'::jsonb),
    ('HIS496H1', 'Advanced Topics in History', '24S', 'An in-depth examination of historical issues. Content in any given year depends on instructor. See History website for more details.', null, null, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, {"credits": 2.0, "department": "HIS"}]}'::jsonb),
    ('HIS497H1', 'Animal Politics and Science', '24S', 'Why is thinking about the animal unsettling for some or strange for others? Especially since Darwin, the question of the animal-what it says about being or not being human-has been at the core of important philosophical and scientific debates. This course examines the ways that question has been answered over time.', null, 2, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('HIS498H1', 'Independent Studies', null, 'History Majors and Specialists only. These courses result in the production of an independent research project. This may not necessarily take the form of a thesis. Students must find topics and project supervisors. Not eligible for CR/NCR option. See department website for specific registration instructions.', null, null, '{"operator": "AND", "items": [{"credits": 3.0, "department": "HIS"}]}'::jsonb),
    ('HIS499Y1', 'Independent Studies', null, 'History Majors and Specialists only. These courses result in the production of an independent research project. This may not necessarily take the form of a thesis. Students must find topics and project supervisors. Not eligible for CR/NCR option. See department website for specific registration instructions.', null, null, '{"operator": "AND", "items": [{"credits": 3.0, "department": "HIS"}]}'::jsonb),
    ('HMB200H1', 'Introduction to Neuroscience', '24L/12T', 'An introductory course that explores the development, physiology and continually changing function of the nervous system as it relates to certain types of human behaviour. Critical analysis of scientific evidence is used to enrich learning.', null, 4, '{"operator": "AND", "items": ["BIO120H1", "BIO130H1"]}'::jsonb),
    ('HMB201H1', 'Introduction to Applied Genetics and Biotechnology', '24L/12T', 'The course provides a comprehensive introduction to a variety of therapeutic approaches including gene therapy, CRISPR-based gene editing, epigenetic manipulations & regenerative medicine. This course consists of three parts: tools and techniques of gene & genome manipulations; medical, environmental and agricultural biotechnology applications; and ethical, legal and social aspects of modern biotechnology as it pertains to human health and wellbeing.', null, 4, '{"operator": "AND", "items": ["BIO120H1", "BIO130H1"]}'::jsonb),
    ('HMB202H1', 'Introduction to Health and Disease', '24L/12P', 'An introductory course in Health and Disease using an interdisciplinary approach that integrates bacteriology and virology with other aspects of human biology, including chronic disease and neoplasia. An exploration of the key concepts and approaches that are necessary for understanding the dynamic nexus of human health and disease. (Lab Materials Fee: $30)', 'HMB203H1/  HMB204H1', 4, '{"operator": "AND", "items": ["BIO120H1", "BIO130H1"]}'::jsonb),
    ('HMB203H1', 'Introduction to Global Health', '24L/12T', 'An introductory course covering the theories, operational components and strategies of implementing health care in resource-poor settings. Topics may include education, control of vector-borne diseases, essential drug provision, maternal and child health, nutrition, incorporation of alternative and complementary technologies, community participation and deployment of health service providers', 'HMB202H1/ HMB204H1', 4, '{"operator": "AND", "items": ["BIO120H1", "BIO130H1"]}'::jsonb),
    ('HMB204H1', 'Introduction to Human Biology', '24L/12T', 'An introduction to the biological, health, environmental, and sociopolitical issues that influence human health and well-being. Topics include genetic variation within and across human populations, biological variation related to the environment, determinants of health and disease, and human behaviour and development.', 'HMB202H1/  HMB203H1', 4, '{"operator": "AND", "items": ["BIO120H1", "BIO130H1"]}'::jsonb),
    ('HMB226H1', 'Indigenous Holistic Health', '2P/22S', 'What is holistic health in an Indigenous framework? How can holistic health (physical, mental, emotional, and spiritual) be ethically explored to inform health and healing? What is cultural safety in health care systems? This course explores the effects of traditional practices, culture, activities, arts, land-based healing, music and ceremony in health and healing. Enrolment is by application. Detailed application instructions are available on the HMB Special Enrolment website: https://www.hmb.utoronto.ca/special-enrolment. The application will ask about motivation and/or relevant experience. Applications are received during priority course enrollment, and late applications considered if space remains. Applications will be assessed based on prerequisites, submitted answers to application prompts and cGPA. This course is open to all Human Biology students.', null, 4, null::jsonb),
    ('HMB265H1', 'General & Human Genetics', '24L/12T', 'An introduction to classical and modern methods of genetic analysis. Topics include Mendelian genetics, the genetics of human population and disease, genomics, and applications of genetics to human society.', 'BIO260H1/  BIO207H5', 4, '{"operator": "AND", "items": ["BIO120H1", "BIO130H1", {"operator": "OR", "items": [{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM135H1", "CHM139H1"]}, {"operator": "OR", "items": ["CHM136H1", "CHM138H1"]}]}, "CHM151Y1"]}]}'::jsonb),
    ('HMB299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HMB299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities…. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('HMB300H1', 'Neurobiology of Behaviour', '24L/12T', 'This neuroscience course focuses on higher brain functions and the mechanisms underlying human and animal behaviours. Topics may include the emerging role of the gut microbiome''s impact on behaviour, pathogens that alter neuronal development and the biological basis of mindfulness and placebos. In addition, the impact that exercise and sleep play in modulating these behaviours are examined. Common experimental techniques used in neuroscience research such as brain imaging and cellular genetics are emphasized.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}, {"operator": "OR", "items": ["HMB200H1", "PSY290H1", "PSL300H1", "CJH332H1"]}]}'::jsonb),
    ('HMB301H1', 'Biotechnology', '24L/12T', 'Students gain an appreciation for how science, government and society drive the development of biotechnology products. Topics include emerging immunotherapies, "living therapeutics", emerging challenges, CRISPR-based therapeutics, emerging diagnostics, and stem cells and regenerative medicine.', null, 4, '{"operator": "AND", "items": ["HMB201H1", {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}, {"operator": "OR", "items": ["EEB225H1", "STA220H1", "STA288H1", "PSY201H1"]}]}'::jsonb),
    ('HMB302H1', 'Vertebrate Histology and Histopathology', '24L/36P', 'Laboratory and lecture course studying the structure of the cell, various tissues and organ systems. Emphasis is on functional morphology and the adaptive response (including the inflammatory reaction) by comparing histological sections of normal tissues and organs with common diseases including neoplasia, respiratory, and liver disease. (Lab Materials Fee: $27)', null, 4, '{"operator": "OR", "items": ["BIO230H1", "BIO255H1"]}'::jsonb),
    ('HMB303H1', 'Global Health and Human Rights', '28L/8S', 'The Global Health & Human Rights course uses a multidisciplinary approach to consider the theory and practice of global health as well as human rights from a global health perspective. The course has an emphasis on the social, historical, economic and political determinants of global health and human rights. The critical approach used in the course will also allow students to begin to consider the limitations and contradictions inherent in the theory and practice of global health and in human rights.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["HMB202H1", "HMB203H1", "HMB204H1", "HST209H1", "HST211H1", "HST250H1"]}]}'::jsonb),
    ('HMB304H1', 'Challenges of Antimicrobial Resistance in Human Biology', '24L/12T', 'Pathogens are becoming increasingly resistant to our available treatments, driving the spread and worsening the impact of infectious diseases. This course offers an in-depth examination of the key challenges of antimicrobial resistance in human biology, with a focus on the complexities of human health. Students will investigate how microbes develop drug resistance, how this knowledge can be used to counteract resistance, and how environmental and societal factors influence our responses to this growing global threat.', null, 4, '{"operator": "AND", "items": ["BIO230H1", "BCH210H1", "HMB204H1", "HMB265H1"]}'::jsonb),
    ('HMB306H1', 'Ethical Considerations in Emerging Technology', '14L/10S', 'Advancing technology increases our ability to intervene in the course of natural events involving human health and well being. Questions arise as whether we ought to and who will benefit or be harmed. This course considers the far-reaching bioethical implications of emerging bio-technology. Topics to be explored include-but are not limited to- ethical considerations in emerging reproductive technologies, genetic alteration/genetic enhancement. Use of life support technologies, synthetic life, life extension.', null, 4, '{"operator": "AND", "items": ["BIO230H1", {"operator": "OR", "items": ["HMB265H1", "BIO260H1"]}]}'::jsonb)
